// Correcciones Simulia — tanda 3 — parte 1 de 8: fotos, protocolos, escalas y dudas (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_completos', {"question": "Según el sistema de vigilancia de la mortalidad diaria (Sistema MoMo), NO es cierto que:"}, {"long_answer": "La afirmación falsa es la del índice Kairós: el enfoque predictivo de MoMo ofrece predicciones del riesgo de mortalidad atribuible a exceso o defecto de temperatura para el día en curso y los cinco días siguientes, no para los siete siguientes. El resto es cierto. MoMo vigila a diario la mortalidad por todas las causas y la asociada a excesos de temperatura, y está implantado en la Unidad de Vigilancia de la Mortalidad Diaria del Centro Nacional de Epidemiología del Instituto de Salud Carlos III. Para ello integra tres fuentes: el Instituto Nacional de Estadística, el Ministerio de Justicia, a través de los registros civiles informatizados, y la Agencia Estatal de Meteorología."});
fix('examen_completos', {"question": "Con relación a la soledad como problema de salud, señale la respuesta INCORRECTA:"}, {"answer": 4, "option_1": "Weiss (1973) distinguió entre la soledad emocional, por ausencia de una relación íntima, y la soledad social, por carencia de una red social de pertenencia.", "long_answer": "La afirmación incorrecta es que la soledad no se aborda en el Marco Estratégico para la Atención Primaria y Comunitaria de 2019: este documento sí la contempla, ya que entre sus acciones incluye que el trabajo social sanitario desarrolle protocolos de atención a la soledad no deseada, junto a cronicidad, dependencia, vulnerabilidad o maltrato. El resto es cierto. Weiss, en 1973, diferenció la soledad emocional, ligada a la falta de una figura íntima, de la soledad social, ligada a la falta de una red de pertenencia. La sensación de soledad puede medirse con la escala de soledad de UCLA, y la soledad no deseada se asocia a mayor morbilidad y mortalidad."});
fix('examen_completos', {"question": "¿Cuál de los siguientes hallazgos clínicos NO se encuentra en una persona con demencia tipo Alzheimer leve?:"}, {"option_2": "Incapacidad para reconocer a familiares cercanos y dependencia total para las actividades básicas de la vida diaria.", "long_answer": "La incapacidad para reconocer a familiares cercanos y la dependencia total para las actividades básicas no son propias de la demencia tipo Alzheimer leve, sino de las fases moderada-grave y grave, cuando el deterioro cognitivo y funcional es profundo. En la fase leve predomina la alteración cognitiva con autonomía básica conservada: fallo de la memoria reciente y de fijación, que suele ser el primer síntoma; desorientación temporal, que precede a la espacial y a la personal; y empobrecimiento del lenguaje con dificultad de nominación o anomia. Por eso estas tres alteraciones son hallazgos esperables al inicio de la enfermedad, mientras que la opción señalada no lo es."});
fix('examen_completos', {"question": "Señale cuál de las siguientes afirmaciones es INCORRECTA en relación a la endometriosis en las mujeres que padecen esta enfermedad:"}, {"option_3": "El dolor crónico de la endometriosis se asocia con frecuencia a ansiedad y depresión y afecta a la calidad de vida, la vida sexual y la actividad laboral.", "long_answer": "La afirmación incorrecta es la que dice que los síntomas son menos intensos durante la menstruación y empeoran con la menopausia. El tejido endometrial ectópico responde a los estrógenos, de modo que la dismenorrea y el dolor pélvico empeoran durante la regla y tienden a mejorar tras la menopausia, al caer los niveles hormonales. El resto es cierto según la guía de atención a la endometriosis del Ministerio: la infertilidad puede afectar al 30-40 % de estas mujeres; puede ser una enfermedad crónica e invalidante, sobre todo en la forma profunda; y el dolor crónico se asocia a menudo a ansiedad y depresión, con repercusión en la calidad de vida, la sexualidad y el trabajo."});
fix('examen_completos', {"question": "Indique la opción INCORRECTA en relación a la clasificación de la Fontaine:"}, {"option_2": "El grado II es claudicación intermitente. Siendo IIa la claudicación que aparece a menos de 150 metros y IIb la claudicación que aparece a más de 150 metros.", "long_answer": "La afirmación incorrecta es la del grado II, porque invierte los subgrados: en la clasificación de Fontaine el grado IIa corresponde a la claudicación intermitente no limitante, que aparece tras recorrer una distancia larga, y el IIb a la claudicación limitante, que aparece a distancias cortas. El punto de corte varía según la fuente, 150 o 200 metros, pero en todos los casos el IIb es el que aparece con menor distancia. El resto es correcto: el grado I es asintomático, con lesión arterioesclerótica sin obliteración significativa; el grado III supone dolor isquémico en reposo; y el grado IV aparece cuando hay lesiones tróficas, necrosis o gangrena."});
fix('examen_completos', {"question": "Indique la opción INCORRECTA con relación a los efectos secundarios de los pacientes sometidos a radioterapia en patologías de cuello y cabeza:"}, {"option_3": "El trismo es una complicación excepcional, que afecta a menos del 1% de las personas sometidas a radioterapia de cabeza y cuello, por lo que no precisa ejercicios ni medidas preventivas.", "option_4": "La disfagia y la toxicidad esofágica tras la radioterapia son complicaciones infravaloradas, ya que pueden aparecer de forma tardía, meses o años después del tratamiento.", "long_answer": "La afirmación incorrecta es la del trismo: no es excepcional, sino una complicación frecuente de la radioterapia de cabeza y cuello por fibrosis de los músculos masticadores y de la articulación temporomandibular, con frecuencias descritas de hasta un tercio de los pacientes según las series. Por eso se recomiendan ejercicios mandibulares, dispositivos de movilización pasiva y férulas. El resto es correcto: la xerostomía es la complicación más común y mejora con alimentos húmedos y blandos y la humidificación ambiental; el linfedema interno afecta a mucosa y tejidos blandos y puede causar ronquera, disfagia y compromiso de la vía aérea; y la disfagia y la toxicidad esofágica tardías están infravaloradas porque pueden aparecer meses o años después."});
fix('examen_completos', {"question": "En un paciente en parada cardiorrespiratoria que presenta hipotermia con una temperatura corporal <30º C señale la afirmación INCORRECTA:"}, {"option_2": "Por debajo de 30 °C se debe suspender la administración de adrenalina hasta que la temperatura corporal supere los 30 °C.", "long_answer": "La afirmación incorrecta es que la frecuencia de compresiones y ventilaciones sea diferente: según las guías del European Resuscitation Council, en la parada cardiorrespiratoria por hipotermia se mantienen la misma frecuencia y la misma relación compresiones-ventilaciones que en el paciente normotérmico. Lo que se modifica es el tratamiento farmacológico y eléctrico. Por debajo de 30 °C se suspende la adrenalina hasta superar esa temperatura, y entre 30 y 35 °C se espacian las dosis cada 6-10 minutos. Si la fibrilación ventricular persiste tras tres descargas, se retrasan nuevos intentos hasta superar los 30 °C. Para estimar el pronóstico del recalentamiento hospitalario se recomiendan las escalas HOPE o ICE."});
fix('examen_completos', {"question": "En relación con el manejo de las fístulas arteriovenosas en hemodiálisis, indique la opción INCORRECTA:"}, {"option_4": "La punción de una fístula arteriovenosa de reciente creación debe realizarla personal de enfermería con experiencia en la canulación del acceso vascular.", "long_answer": "La afirmación incorrecta es que se recomiende la técnica en ojal frente a la punción escalonada en las fístulas nativas. La Guía Clínica Española del Acceso Vascular para Hemodiálisis (GEMAV) no la prioriza de forma general: la punción escalonada es la técnica de referencia, y el ojal, que se asocia a más bacteriemias, se reserva para casos seleccionados, como fístulas de trayecto corto o difícil canulación. El resto es correcto: en las fístulas protésicas no se aplica compresión proximal para puncionar; la aguja venosa se inserta proximal a la arterial para evitar la recirculación; y las fístulas recientes deben canularlas enfermeras con experiencia para prevenir hematomas y la pérdida del acceso."});
fix('examen_completos', {"question": "Entre los elementos que pueden enlentecer o impedir la cicatrización de heridas crónicas, señale cual NO es habitual:"}, {"option_4": "Aporte nutricional adecuado, con suficientes proteínas y calorías.", "long_answer": "Un aporte nutricional adecuado, con suficientes proteínas y calorías, no enlentece la cicatrización: al contrario, la favorece, porque aporta el sustrato necesario para la síntesis de colágeno y la reparación tisular. El resto son elementos habituales que retrasan o impiden la cicatrización de las heridas crónicas. La sequedad excesiva deshidrata el lecho y frena la migración celular, mientras que el exceso de humedad o de exudado macera los bordes y la piel perilesional, por lo que la cura en ambiente húmedo busca un equilibrio. Vivir solo es un factor psicosocial de riesgo, ya que suele implicar menos apoyo, peor adherencia a los cuidados y peor alimentación."});
fix('examen_completos', {"question": "Conforme a la Ley 3/2005, de 23 de mayo, por la que se regula el ejercicio del derecho a formular instrucciones previas en el ámbito sanitario y se crea el registro correspondiente, indique cuál de las siguientes opciones NO se contempla:"}, {"long_answer": "La opción no contemplada es la voluntad de ser informado en los supuestos de diagnóstico fatal. El artículo 6.4 de la Ley 3/2005 de la Comunidad de Madrid recoge lo contrario: que el paciente pueda manifestar anticipadamente su voluntad de no ser informado en esos supuestos, designando a quién debe informar el médico. Ser informado es el derecho general del paciente, que no requiere instrucciones previas. Sí se contemplan el destino del cuerpo, órganos o piezas anatómicas tras el fallecimiento; la donación con finalidad terapéutica, docente o de investigación; y, en el artículo 6.5, estar acompañado en la intimidad en los momentos cercanos al exitus y que los acompañantes reciban el trato apropiado a las circunstancias."});
fix('examen_completos', {"question": "Señale la opción INCORRECTA:"}, {"option_2": "El “Descriptores en Ciencias de la Salud” (DeCS) es un tesauro disponible únicamente en inglés.", "long_answer": "La afirmación incorrecta es que el DeCS solo esté disponible en inglés. Los Descriptores en Ciencias de la Salud los elabora BIREME a partir del MeSH precisamente para ofrecer un vocabulario controlado en otros idiomas, y se pueden consultar en español, portugués, inglés y francés. El resto es cierto: el Medical Subject Headings de la National Library of Medicine es un tesauro, es decir, un vocabulario controlado y jerarquizado que se usa para indizar y buscar en bases como MEDLINE; en un tesauro cada descriptor tiene una definición explícita y relaciones con otros términos; y tanto el MeSH como el DeCS son de consulta gratuita en internet."});
fix('examen_completos', {"question": "Señale la respuesta INCORRECTA sobre Insuficiencia Renal:"}, {"option_4": "El hematocrito bajo por hemodilución y el aumento de la presión arterial pueden indicar el exceso de líquidos en el cuerpo.", "long_answer": "La afirmación incorrecta es que resulte difícil recibir un aporte continuo suficiente de líquido por la medicación intravenosa: al contrario, los sueros y diluciones de los fármacos pueden aportar un volumen considerable y causar sobrecarga en el paciente renal, por lo que deben contabilizarse en el balance. El resto es cierto. El peso diario, medido en las mismas condiciones, es el mejor indicador del equilibrio hídrico. La taquicardia, la somnolencia o la confusión son signos frecuentes de infección en estos pacientes, en los que la fiebre puede faltar. Y la hemodilución con descenso del hematocrito, junto con el aumento de la presión arterial, orienta a exceso de volumen."});
fix('examen_completos', {"question": "En el manejo de la Enfermedad Renal Crónica (ERC) según el documento “Guía de Práctica Clínica sobre la Detección y el Manejo de la Enfermedad Renal Crónica”. Ministerio de Sanidad, Servicios Sociales e Igualdad, 2016 (Guías de Práctica Clínica en el SNS), señale cuál de las siguientes recomendaciones es INCORRECTA:"}, {"long_answer": "La recomendación incorrecta es la tercera por su grado: la guía de enfermedad renal crónica del Ministerio de 2016 establece que no se recomienda establecer cifras objetivo de presión arterial inferiores a 140/90 mmHg en los pacientes con ERC, pero como recomendación fuerte, no débil. La guía considera que reducir la presión por debajo de ese umbral no ha demostrado beneficios claros y aumenta efectos adversos. El resto está bien formulado: el ejercicio físico regular y el abandono del tabaco se recomiendan con grado fuerte, y se sugiere, con recomendación débil, no alterar el tratamiento antihipertensivo cuando la presión ya es inferior a 140/90 mmHg."});
fix('examen_completos', {"question": "En referencia al cáncer de próstata, indique la opción INCORRECTA:"}, {"option_1": "Tras una braquiterapia con semillas permanentes no es necesaria ninguna precaución en las relaciones sexuales, ya que las semillas no pueden expulsarse con el semen.", "long_answer": "La afirmación incorrecta es que no se precise ninguna precaución tras la braquiterapia con semillas permanentes: alguna semilla puede migrar y expulsarse con el semen, por lo que se aconseja usar preservativo durante las primeras semanas tras el implante, según el protocolo del centro; además, las primeras eyaculaciones pueden ser hemáticas. El resto es correcto: la resección transuretral extirpa tejido del cuello vesical y lo deja incompetente, lo que causa eyaculación retrógrada; la prostatectomía abierta retropúbica se emplea en glándulas de gran tamaño porque ofrece buena visión del campo quirúrgico; y tras una prostatectomía la actividad sexual suele poder reanudarse a las 6-8 semanas."});
fix('examen_completos', {"question": "Cuando se habla de actitud empática del profesional sanitario en la relación con el paciente NO es cierto que:"}, {"option_2": "La actitud empática supone transmitir al paciente que el profesional comprende cómo se siente con la situación que le está relatando.", "long_answer": "La afirmación falsa es que la actitud empática suponga no dar retroalimentación al paciente. La empatía consiste en comprender lo que siente el paciente y, además, hacérselo saber; por eso implica siempre devolverle lo que ha expresado, de forma verbal y no verbal, para que se sienta entendido. Las demás afirmaciones describen rasgos aceptados de la comunicación empática: el profesional transmite al paciente que comprende cómo se siente; responde con frases cortas, ajustadas y relativamente frecuentes; y la llamada empatía avanzada consiste en reflejar no solo lo que el paciente dice abiertamente, sino también lo que deja entrever o expresa a medias."});
fix('examen_completos', {"question": "Las consecuencias fisiopatológicas del climaterio son las siguientes EXCEPTO:"}, {"option_4": "Aumento de la producción ovárica de estrógenos.", "long_answer": "El aumento de la producción ovárica de estrógenos no es una consecuencia del climaterio: este periodo se caracteriza justamente por el agotamiento folicular y la caída progresiva de los estrógenos. Esa deprivación estrogénica explica las demás consecuencias. En la perimenopausia aparecen ciclos anovulatorios con irregularidad menstrual. La atrofia urogenital produce sequedad vaginal y dispareunia. La pérdida acelerada de masa ósea favorece la osteoporosis y las fracturas. Además, aumenta el riesgo cardiovascular, porque desaparece el efecto protector de los estrógenos sobre el perfil lipídico y la función endotelial. Por eso la única opción que no corresponde a la fisiopatología del climaterio es la señalada."});
fix('examen_completos', {"question": "De las siguientes contraindicaciones a la vacunación, identifique la INCORRECTA:"}, {"option_1": "Niño con reacción anafiláctica previa a una dosis de vacuna antigripal, contraindica nuevas dosis de esa vacuna.", "long_answer": "La afirmación incorrecta es que la anafilaxia al huevo contraindique la vacuna de la varicela: esta vacuna se cultiva en células diploides humanas y no contiene proteínas de huevo. Las demás son contraindicaciones correctas. Una reacción anafiláctica previa a una dosis de una vacuna, como la antigripal, contraindica dosis posteriores de esa vacuna. La triple vírica está contraindicada ante anafilaxia a la neomicina, que contiene en trazas. La vacuna de la fiebre amarilla se cultiva en huevo embrionado y contiene cantidades relevantes de sus proteínas, por lo que la anafilaxia al huevo la contraindica. Conviene recordar que la alergia al huevo, incluso grave, ya no contraindica la vacuna antigripal."});
fix('examen_completos', {"question": "Entre las enfermedades y trastornos neurológicos con influencia de factores genéticos, NO se encuentra:"}, {"option_4": "Traumatismo craneoencefálico.", "long_answer": "El traumatismo craneoencefálico es un trastorno neurológico adquirido, causado por una fuerza externa como caídas, accidentes de tráfico o agresiones, sin influencia de factores genéticos en su origen. En cambio, las demás tienen base genética total o parcial. La distrofia muscular de Duchenne se hereda de forma recesiva ligada al cromosoma X por mutaciones del gen de la distrofina. La esclerosis lateral amiotrófica presenta formas familiares, en torno al 10 %, ligadas a genes como SOD1 o C9orf72. Muchas epilepsias tienen una base genética reconocida. La espina bífida es un defecto del tubo neural de origen multifactorial, con predisposición genética y relación con el déficit de ácido fólico."});
fix('examen_completos', {"question": "Señale cuál de las siguientes alteraciones NO se corresponde con las manifestaciones clínicas de la diabetes tipo 1 en los niños:"}, {"option_3": "Poliuria, que puede manifestarse como enuresis secundaria.", "option_5": "Astenia y cansancio.", "long_answer": "El aumento de peso no corresponde a la clínica de la diabetes tipo 1 en los niños: lo característico es la pérdida de peso, a pesar de que comen más, porque el déficit de insulina impide utilizar la glucosa y obliga a catabolizar grasa y músculo. El debut típico incluye poliuria por diuresis osmótica, que en niños ya continentes puede manifestarse como enuresis secundaria; polidipsia, para compensar la pérdida de agua; polifagia, por la falta de aprovechamiento de la glucosa; y astenia y cansancio. Si el diagnóstico se retrasa puede evolucionar a cetoacidosis, con vómitos, dolor abdominal y respiración de Kussmaul."});
fix('examen_completos', {"question": "El señor Fernández tiene un problema renal y ha sido necesario su ingreso para control y tratamiento. ¿Cuál de las siguientes preguntas NO es adecuada para valorar su equilibrio hidroelectrolítico?:"}, {"option_1": "¿Qué actividades de ocio realiza habitualmente en su tiempo libre?", "option_5": "¿Ha notado últimamente calambres o debilidad muscular?", "long_answer": "Preguntar por las actividades de ocio no aporta información sobre el equilibrio hidroelectrolítico; puede ser útil en otros patrones de la valoración, pero no para este fin. Las demás preguntas sí son adecuadas en un paciente renal. Los cambios en la cantidad o el color de la orina orientan sobre la diuresis y la capacidad de concentración. El número de almohadas que usa para dormir explora la ortopnea, signo de sobrecarga de volumen e insuficiencia cardiaca. La confusión o la dificultad para concentrarse pueden deberse a alteraciones del sodio o a uremia. Los calambres o la debilidad muscular sugieren alteraciones del potasio, el calcio o el magnesio."});
fix('examen_completos', {"question": "Señale cuál de las siguientes variables NO corresponde a una espirometría forzada:"}, {"option_2": "Volumen Residual.", "long_answer": "El volumen residual no corresponde a la espirometría forzada: es el aire que queda en los pulmones tras una espiración máxima, no puede ser exhalado y, por tanto, no se mide con el espirómetro; requiere técnicas como la pletismografía corporal o la dilución de helio. En cambio, la espirometría forzada proporciona la capacidad vital forzada (FVC), el volumen espiratorio forzado en el primer segundo (FEV1) y el cociente FEV1/FVC, que es el parámetro clave para definir la obstrucción cuando es inferior a 0,70 tras broncodilatación, además de los flujos mesoespiratorios. Por eso las otras tres opciones sí son variables propias de esta prueba."});
fix('examen_completos', {"question": "Respecto a la medición de la presión arterial (PA) en consulta, ¿cuál de las siguientes afirmaciones es INCORRECTA?"}, {"option_1": "Se deben tomar tres mediciones, separadas 1-2 minutos; si hay diferencias mayores de 10 mmHg se toman medidas adicionales. La PA se debe registrar como la media de las dos últimas medidas.", "option_3": "Se puede utilizar un manguito de tamaño estándar en todos los pacientes, independientemente del perímetro del brazo.", "long_answer": "La afirmación incorrecta es la del manguito: no puede usarse un tamaño estándar en todos los pacientes, sino que debe ajustarse al perímetro del brazo, con una cámara que abarque el 75-100 % de esa circunferencia en longitud y el 35-50 % en anchura; un manguito pequeño sobrestima la PA y uno grande la infraestima. El resto se ajusta a la guía ESC 2024: tres mediciones separadas 1-2 minutos, con medidas adicionales si difieren más de 10 mmHg, registrando la media de las dos últimas; reposo sentado de 5 minutos, sin ejercicio, cafeína ni tabaco en los 30 minutos previos; y evaluación de hipotensión ortostática a 1 y/o 3 minutos de la bipedestación con umbral de 20/10 mmHg."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43945f") }, {"Pregunta": "El Test de Malinas se utiliza en la atención extrahospitalaria de la gestante en trabajo de parto. ¿Qué puntuación indica que todavía es posible el traslado a la maternidad?", "Respuesta_1": "Puntuación inferior a 5", "Respuesta_2": "Puntuación de 8 o más", "Respuesta_3": "Puntuación de 10", "Respuesta_4": "Puntuación de 6-7 con sensación de pujo", "Respuesta_Correcta": "A", "Justificacion": "El Test de Malinas suma cinco ítems puntuados de 0 a 2: paridad, duración del trabajo de parto, duración de las contracciones, intervalo entre contracciones y rotura de membranas, con un total de 0 a 10. Una puntuación inferior a 5 indica que hay tiempo suficiente para trasladar a la gestante a la maternidad. A partir de 6, y sobre todo con puntuaciones de 8 o más o si la mujer siente ganas de empujar, el parto se considera inminente y debe prepararse la asistencia in situ, por lo que el traslado deja de ser la opción indicada. La escala no se usa para diferenciar las fases latente y activa del parto."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43946c") }, {"Justificacion": "El HATCH Score se construyó para predecir la progresión de la fibrilación auricular paroxística hacia formas persistentes o permanentes y se ha utilizado también para estimar la probabilidad de mantener el ritmo sinusal tras la cardioversión. Puntúa hipertensión (1), edad mayor de 75 años (1), AIT o ictus previo (2), EPOC (1) e insuficiencia cardíaca (2); a mayor puntuación, mayor sustrato auricular y menor probabilidad de mantener el ritmo sinusal. El CHA2DS2-VASc estima el riesgo tromboembólico, el HAS-BLED el riesgo hemorrágico de la anticoagulación y la escala EHRA gradúa la intensidad de los síntomas atribuibles a la FA."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439485") }, {"Respuesta_2": "Taquicardia de 30 lpm o más por encima de la normalidad para la edad, relleno capilar de 5 segundos o más, o piel grisácea y moteada", "Respuesta_4": "Frecuencia cardíaca normal para la edad con relleno capilar de 1-2 segundos", "Justificacion": "En la subescala cardiovascular del PEWS de Monaghan la puntuación máxima de 3 corresponde al niño con piel grisácea y moteada, relleno capilar de 5 segundos o más, taquicardia de 30 lpm o más por encima de la normalidad para su edad o bradicardia. La puntuación 0 corresponde a coloración rosada y relleno capilar de 1-2 segundos, como describe la opción D; 1 a palidez o relleno de 3 segundos, y 2 a coloración grisácea, relleno de 4 segundos o taquicardia de 20 lpm sobre lo normal. Una FC de 140 lpm puede ser normal en un lactante y la hipotensión no forma parte de esta subescala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394a1") }, {"Pregunta": "La Escala de Berg (Berg Balance Scale). ¿Cuántos ítems tiene y por debajo de qué puntuación se considera habitualmente que existe un riesgo aumentado de caídas?", "Respuesta_2": "14 ítems (0-2 cada uno, máximo 28); riesgo aumentado <19 puntos", "Justificacion": "La Escala de Berg valora el equilibrio mediante 14 tareas funcionales, como levantarse, sentarse, alcanzar objetos, girar o mantenerse sobre un pie, puntuadas de 0 a 4, con un máximo de 56 puntos. El punto de corte más utilizado para identificar riesgo aumentado de caídas en personas mayores es una puntuación inferior a 45; por debajo de 36 el riesgo es muy elevado y por debajo de 20 suele asociarse a dependencia de silla de ruedas. La opción con 28 puntos máximos y corte en 19 corresponde a la escala de Tinetti, la de 10 ítems es incorrecta y un corte en 50 no es el estándar."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439454") }, {"Justificacion": "La Escala de Cincinnati valora asimetría facial, caída del brazo y alteración del lenguaje. Basta con que uno solo de los tres parámetros sea anormal para considerar sospecha de ictus, ya que en el estudio de validación la presencia de un hallazgo alterado se asociaba a una probabilidad de ictus cercana al 72%. Por eso, ante un parámetro positivo y un inicio brusco de los síntomas, se debe activar el Código Ictus según los criterios temporales del protocolo autonómico, sin esperar a que aparezcan los tres signos. Exigir dos o tres hallazgos positivos reduciría la sensibilidad y retrasaría el tratamiento de reperfusión."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43945a") }, {"Respuesta_2": "≥3 puntos", "Justificacion": "La puntuación de Bishop valora dilatación, borramiento, consistencia y posición del cérvix y altura de la presentación. Una puntuación de 8 o más indica un cérvix claramente favorable, con una probabilidad de parto vaginal tras la inducción similar a la del inicio espontáneo, por lo que se puede inducir directamente con oxitocina y amniotomía sin maduración cervical previa. Puntuaciones bajas, como 3 o 5, definen un cérvix desfavorable en el que se indica maduración cervical previa con prostaglandinas o métodos mecánicos. Exigir 10 puntos sería un umbral excesivo y no es el criterio utilizado en la práctica."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439484") }, {"Justificacion": "La escala CRIES fue desarrollada por Krechel y Bildner para valorar el dolor postoperatorio en neonatos y se validó en recién nacidos de 32 a 60 semanas de edad gestacional. Valora cinco parámetros, llanto, necesidad de oxígeno para mantener saturación superior al 95%, aumento de constantes vitales, expresión facial e insomnio, cada uno de 0 a 2, con un total de 0 a 10; una puntuación de 4 o más indica dolor que requiere tratamiento. No se validó para menores de 32 semanas, por lo que en grandes prematuros se prefieren otras escalas como la PIPP, ni se limita a recién nacidos a término."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394cb") }, {"Justificacion": "La clasificación AKIN divide la lesión renal aguda en tres estadios según el aumento de creatinina o la disminución de la diuresis en 48 horas. El estadio 3 se define por creatinina igual o superior a 3 veces la basal, creatinina de 4 mg/dL o más con un aumento agudo de al menos 0,5 mg/dL, inicio de terapia renal sustitutiva, diuresis inferior a 0,3 ml/kg/h durante 24 horas o anuria durante 12 horas. El estadio 1 corresponde a un aumento de 0,3 mg/dL o de 1,5-2 veces la basal y el estadio 2 a un aumento de 2-3 veces. No tiene cinco ni cuatro estadios."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394fd") }, {"Respuesta_2": "Para cuantificar objetivamente el grado de prolapso de los órganos pélvicos (cistocele, rectocele, uterocele, enterocele) mediante 9 medidas estandarizadas respecto al himen; estadifica en 5 estadios (0-IV)", "Justificacion": "El POP-Q, propuesto por la International Continence Society, cuantifica de forma objetiva el prolapso de órganos pélvicos con nueve medidas en centímetros referidas al himen: Aa, Ba, C, D, Ap, Bp, hiato genital, cuerpo perineal y longitud vaginal total. Clasifica en cinco estadios: 0 sin prolapso; I, punto más distal a más de 1 cm por encima del himen; II, entre 1 cm por encima y 1 cm por debajo; III, más de 1 cm por debajo del himen sin eversión completa; y IV, eversión total. No valora la incontinencia urinaria ni se limita al prolapso uterino."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43942a") }, {"Pregunta": "Aplicando el Índice de Katz, un anciano es independiente para WC, transferencia, continencia y alimentación, pero dependiente para baño y vestido. ¿Qué grado le corresponde?", "Respuesta_Correcta": "B", "Justificacion": "El Índice de Katz clasifica a la persona en grados de la A a la G siguiendo el orden jerárquico de pérdida de las actividades básicas: baño, vestido, uso del WC, transferencia, continencia y alimentación. El grado C corresponde a quien es independiente para todas las funciones excepto el baño y otra función más, que es el caso de este paciente, dependiente para baño y vestido. El grado B indica dependencia en una sola función. El grado D exige dependencia en baño, vestido y otra función, y el grado E en baño, vestido, WC y otra función más."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43944a") }, {"Respuesta_4": "Para decidir cuándo reintubar por fracaso del destete"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439452") }, {"Pregunta": "En el modelo dicotómico de la Escala de Wells para TVP (TVP «probable» frente a «improbable»), ¿a partir de qué puntuación se considera la TVP probable?", "Justificacion": "En el modelo dicotómico de Wells para trombosis venosa profunda, una puntuación de 2 o más clasifica la TVP como probable y menos de 2 como improbable. Con TVP improbable se solicita dímero D, y si es negativo se descarta la trombosis; con TVP probable se realiza directamente ecografía doppler, ya que un dímero D negativo no basta para excluirla. El corte de 3 o más corresponde a la probabilidad alta del modelo original de tres niveles, no al dicotómico, y el umbral de 1 es demasiado bajo. Una puntuación superior a 4 no se emplea en la escala de TVP."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43945c") }, {"Justificacion": "La escala de Silverman-Andersen valora la dificultad respiratoria del recién nacido mediante cinco ítems puntuados de 0 a 2: movimientos toracoabdominales, tiraje intercostal, retracción xifoidea, aleteo nasal y quejido espiratorio. La puntuación total va de 0 a 10, y a diferencia del Apgar, una puntuación más alta indica mayor gravedad: 0 corresponde a ausencia de dificultad, 1-3 a dificultad leve, 4-6 a moderada y 7 o más a dificultad respiratoria grave. Las opciones con cuatro o seis ítems son incorrectas, y un rango de 0-5 no es posible porque cada ítem puede sumar hasta 2 puntos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43948e") }, {"Pregunta": "La Escala ESAS-r (revisada). ¿Cuántos ítems incluye en total, contando el ítem abierto para «otro problema»?", "Justificacion": "La ESAS-r, revisada por Watanabe y colaboradores en 2011, valora nueve síntomas predefinidos, dolor, cansancio, somnolencia, náuseas, falta de apetito, disnea, depresión, ansiedad y bienestar, y añade un décimo ítem abierto para que el paciente registre otro problema relevante, por ejemplo estreñimiento, lo que da un total de diez ítems puntuados de 0 a 10. La revisión no amplió el número de síntomas, sino que aclaró definiciones, cambió el orden de los ítems, precisó que se valora el momento actual y facilitó su comprensión. Las cifras de 9, 11 y 12 no corresponden al total de ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394dc") }, {"Justificacion": "La escala CHEOPS fue desarrollada por McGrath y colaboradores en 1985 para valorar el dolor postoperatorio en niños de 1 a 7 años, una etapa en la que la autoevaluación es poco fiable. Incluye seis parámetros conductuales, llanto, expresión facial, verbalización, posición del tronco, tacto y posición de las piernas, con una puntuación total de 4 a 13, en la que 4 indica ausencia de dolor y valores superiores sugieren dolor que debe valorarse y tratarse. Para menores de 6 meses o neonatos se emplean escalas específicas como CRIES o NIPS, y en adolescentes se prefieren escalas de autoevaluación."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439439") }, {"Respuesta_3": "6 ítems; rango 0-18", "Respuesta_Correcta": "B", "Justificacion": "La Escala de Braden consta de seis ítems: percepción sensorial, exposición a la humedad, actividad, movilidad, nutrición, y roce y peligro de lesiones cutáneas. Los cinco primeros se puntúan de 1 a 4 y el de fricción y cizallamiento de 1 a 3, por lo que el rango total es de 6 a 23 puntos, y a menor puntuación mayor riesgo de lesión por presión. Las opciones de cinco ítems con rango 5-20 o siete ítems con rango 7-28 no corresponden a esta escala; esta última recuerda a la Braden Q pediátrica. Un rango de 0-18 es imposible, ya que ningún ítem puntúa 0."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439462") }, {"Pregunta": "La Perineal Assessment Tool (PAT) de Nix se utiliza para valorar el riesgo de dermatitis asociada a la incontinencia. ¿Cuántos parámetros evalúa?", "Respuesta_1": "2 parámetros (tipo de irritante y duración de la exposición)", "Respuesta_2": "3 parámetros (intensidad del irritante, estado de la piel perineal y movilidad)", "Respuesta_3": "4 parámetros (tipo e intensidad del irritante, duración de la exposición, estado de la piel perineal y factores contribuyentes)", "Respuesta_4": "5 parámetros (añade el estado nutricional)", "Respuesta_Correcta": "C", "Fuente": "Nix DH. Ostomy Wound Manage. 2002.", "Justificacion": "La Perineal Assessment Tool, desarrollada por Nix, valora el riesgo de dermatitis asociada a la incontinencia mediante cuatro parámetros: tipo e intensidad del irritante (heces formes, blandas o líquidas, con o sin orina), duración de la exposición según la frecuencia de cambios, estado de la piel perineal y factores contribuyentes como hipoalbuminemia, antibióticos, nutrición por sonda o infección. Cada parámetro puntúa de 1 a 3, con un total de 4 a 12, y una puntuación de 7 o más indica riesgo alto. Las opciones de dos, tres o cinco parámetros no corresponden a la herramienta, que no incluye movilidad ni estado nutricional como ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439486") }, {"Pregunta": "La Escala de Downes original para la valoración de la dificultad respiratoria del recién nacido. ¿Cuántos ítems tiene?", "Fuente": "Downes JJ et al. Clin Pediatr. 1970.", "Justificacion": "La escala de Downes original valora la dificultad respiratoria neonatal con cinco ítems puntuados de 0 a 2: frecuencia respiratoria, cianosis, retracciones, quejido espiratorio y entrada de aire a la auscultación, con un total de 0 a 10 en el que una puntuación mayor indica más gravedad. No debe confundirse con la escala de Wood-Downes modificada por Ferrés, empleada en la bronquiolitis y las crisis asmáticas, que valora seis parámetros: sibilancias, tiraje, entrada de aire, cianosis, frecuencia respiratoria y frecuencia cardíaca. Las opciones de tres o cuatro ítems son incorrectas."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439490") }, {"Fuente": "Latorre Marco I, Solís Muñoz M et al. Enferm Intensiva. 2011.", "Justificacion": "La escala Campbell, validada en España para valorar el dolor en pacientes críticos que no pueden comunicarse, puntúa cinco ítems conductuales, musculatura facial, tranquilidad, tono muscular, respuesta verbal y confortabilidad, de 0 a 2, con un total de 0 a 10. Su interpretación es: 0 sin dolor, 1-3 dolor leve a moderado, 4-6 dolor moderado a grave y más de 6, es decir, 7 o más, dolor muy intenso. Por tanto, una puntuación de 7 o más indica dolor intenso y exige revisar y aumentar la analgesia. Una puntuación de 3 o 5 indica dolor de menor intensidad, y 10 es el máximo de la escala, no su umbral."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394d7") }, {"Respuesta_2": "6 ítems de cribado (preguntas 1-6 del ASRS completo, Parte A); 4 o más respuestas en las casillas sombreadas sugieren TDAH del adulto", "Justificacion": "La ASRS-v1.1 de la OMS tiene 18 ítems basados en los criterios DSM, y sus seis primeras preguntas forman la Parte A, que es la versión de cribado. Cada pregunta se responde con nunca, rara vez, a veces, a menudo o muy a menudo, y se considera positiva cuando la respuesta cae en la casilla sombreada, que es a veces o más en los tres primeros ítems y a menudo o más en los tres siguientes. Cuatro o más ítems positivos indican síntomas compatibles con TDAH del adulto y justifican una evaluación diagnóstica. No exige que los seis sean positivos ni tiene versiones de 10 ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394f4") }, {"Pregunta": "La herramienta HomeFAST (Home Falls and Accidents Screening Tool). ¿Qué evalúa en la visita domiciliaria?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439522") }, {"Respuesta_2": "Es el componente 6 (uso de medicación para dormir), que puntúa de 0 a 3 según su frecuencia en el último mes: ninguna vez=0; menos de una vez a la semana=1; una o dos veces a la semana=2; tres o más veces a la semana=3", "Justificacion": "El Índice de Calidad de Sueño de Pittsburgh agrupa sus ítems en siete componentes puntuados de 0 a 3: calidad subjetiva, latencia, duración, eficiencia habitual, perturbaciones del sueño, uso de medicación hipnótica y disfunción diurna. El componente 6 recoge la frecuencia con la que la persona ha tomado medicación para dormir en el último mes, desde ninguna vez hasta tres o más veces por semana. La suma de los siete componentes oscila entre 0 y 21, y una puntuación global superior a 5 indica mala calidad del sueño. La latencia es el componente 2 y la disfunción diurna el componente 7."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43944c") }, {"Justificacion": "El índice de oxigenación se calcula multiplicando la FiO2 por la presión media de la vía aérea en cmH2O y por 100, y dividiendo el resultado entre la PaO2. A diferencia del cociente PaO2/FiO2, incorpora la intensidad del soporte ventilatorio, por lo que es el parámetro recomendado por la conferencia PALICC para clasificar el SDRA pediátrico en ventilación invasiva: leve con IO de 4 a menos de 8, moderado de 8 a menos de 16 y grave con 16 o más. También se emplea en neonatología para valorar la indicación de óxido nítrico o ECMO. Las demás fórmulas no corresponden al IO."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43949c") }, {"Respuesta_3": "Embarazo en curso"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394bf") }, {"Justificacion": "En la escala GAF del DSM-IV, el tramo 21-30 describe una conducta muy influida por ideas delirantes o alucinaciones, o bien una alteración grave de la comunicación o del juicio, o la incapacidad para funcionar en casi todas las áreas, por lo que corresponde al enunciado. El tramo 31-40 indica alguna alteración de la percepción de la realidad o de la comunicación o una afectación importante en varias áreas; el 41-50, síntomas graves o afectación grave del funcionamiento social o laboral; y el 11-20, algún peligro de causar lesiones a otros o a uno mismo o incapacidad ocasional para mantener una higiene mínima."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394e3") }, {"Respuesta_2": "10 niveles (0-9); nivel 0=asintomático; a partir del nivel 7 usa silla de ruedas para la mayoría de actividades y en los niveles 8-9 está confinado en ella", "Respuesta_4": "10 niveles; silla de ruedas desde el nivel 3", "Justificacion": "El Índice de Ambulación de Hauser gradúa la marcha en la esclerosis múltiple de 0 a 9 según el tiempo empleado en recorrer unos 8 metros y el apoyo necesario. El 0 es asintomático; 1-2, fatiga o marcha anormal; 3, marcha sin ayuda; 4, con apoyo unilateral; 5-6, con apoyo bilateral, y en el 6 puede usar ocasionalmente la silla de ruedas. En el 7 solo da unos pasos con apoyo bilateral y usa la silla para la mayoría de actividades; en el 8 está confinado en silla pero se transfiere solo, y en el 9 no puede transferirse. El nivel 3 corresponde a marcha independiente."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43943a") }, {"Respuesta_1": "I → II → III → IV, más las categorías adicionales «No estadiable» y «Lesión de tejidos profundos»", "Respuesta_3": "I → III → II → IV", "Justificacion": "La clasificación NPUAP/EPUAP/PPPIA ordena las lesiones por presión numeradas de menor a mayor profundidad: categoría I, eritema no blanqueable con piel intacta; II, pérdida parcial del espesor de la piel con exposición de dermis; III, pérdida total del espesor con tejido subcutáneo visible; y IV, pérdida total con exposición de fascia, músculo, tendón o hueso. A ellas se añaden dos categorías adicionales: no estadiable, cuando la base está cubierta por esfacelo o escara, y lesión de tejidos profundos, con piel intacta y coloración púrpura o granate. Situar la DTI al principio, alterar el orden II-III o usar términos genéricos es incorrecto."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394ab") }, {"Respuesta_Correcta": "D", "Justificacion": "En la puntuación de Bishop, el borramiento cervical se puntúa con 0 puntos si es del 0-30%, 1 punto si es del 40-50%, 2 puntos si es del 60-70% y 3 puntos si es del 80% o más. Por tanto, un borramiento del 80% otorga la puntuación máxima de 3 puntos para este parámetro. En la versión modificada se sustituye el porcentaje de borramiento por la longitud cervical, que también llega hasta 3 puntos cuando el cuello está borrado. Las opciones de 0, 1 y 2 puntos corresponden a grados menores de borramiento."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394c4") }, {"Respuesta_1": "4 dominios (malestar físico, malestar psicosocial, preocupaciones e inquietudes, y satisfacción); 28 ítems"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394cf") }, {"Justificacion": "En el Constant-Murley Score la fuerza aporta un máximo de 25 de los 100 puntos de la escala. Se mide con el brazo a 90 grados de abducción en el plano de la escápula, unos 30 grados por delante del plano frontal, y el paciente sostiene la posición mientras se registra la fuerza con un dinamómetro o con pesas. Se asigna un punto por cada 0,5 kg, aproximadamente una libra, hasta un máximo de 25 puntos, que equivale a 12,5 kg. No se mide con dinamometría de prensión manual ni con la escala MRC, y el test de Jobe es una maniobra exploratoria del supraespinoso, no el sistema de medida de esta escala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439433") }, {"Respuesta_Correcta": "C", "Justificacion": "La Escala de Incapacidad Física de la Cruz Roja tiene seis grados, del 0 al 5. El grado 0 indica que la persona se vale totalmente por sí misma y camina con normalidad; el 1, que realiza las actividades de la vida diaria y deambula con alguna dificultad; el 2, que necesita ayuda ocasional y deambula con bastón; el 3, grave dificultad con ayuda de al menos una persona; el 4, ayuda para casi todas las actividades y deambulación con extrema dificultad con dos personas; y el 5, inmovilización en cama o sillón con cuidados continuos. Junto con la escala de Cruz Roja Mental, se usa mucho en geriatría."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439448") }, {"Respuesta_1": "3 ítems (expresión facial, movimiento de extremidades superiores, adaptación a la VM); dolor significativo >5", "Justificacion": "La Behavioral Pain Scale de Payen valora el dolor en pacientes críticos sedados y ventilados mediante tres ítems puntuados de 1 a 4: expresión facial, movimiento de extremidades superiores y adaptación a la ventilación mecánica, con un total de 3 a 12. Una puntuación de 3 indica ausencia de dolor y una puntuación superior a 5 se considera dolor significativo que requiere intervención analgésica y reevaluación. Por tanto, el umbral de 3 es incorrecto porque corresponde al mínimo de la escala, y las opciones de cuatro o cinco ítems no corresponden a la BPS. Su rendimiento es comparable al de la CPOT."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439470") }, {"Respuesta_Correcta": "D", "Justificacion": "En la respuesta verbal de la Escala de Coma de Glasgow, V4 corresponde a la respuesta confusa: el paciente es capaz de construir frases y conversar, pero está desorientado en tiempo, espacio o persona. Por encima está V5, el paciente orientado. V3 son palabras inapropiadas, es decir, palabras reconocibles pero aisladas, sin construir frases coherentes; V2 son sonidos incomprensibles como gemidos o quejidos; y V1 es la ausencia de respuesta verbal. Por tanto, las opciones de sin respuesta, sonidos incomprensibles y palabras inapropiadas corresponden respectivamente a V1, V2 y V3."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439475") }, {"Respuesta_2": "M4 porque implica una retirada (flexión normal) ante el estímulo doloroso", "Justificacion": "En la respuesta motora de Glasgow, M4 corresponde a la retirada o flexión normal ante el dolor, que indica mayor integridad de las vías motoras que M1, ausencia de respuesta, M2, extensión anormal o descerebración, y M3, flexión anormal o decorticación. La localización del dolor corresponde a M5 y la obediencia de órdenes a M6. El pronóstico mejora a medida que asciende la puntuación motora, por lo que M1 es la peor respuesta posible, M2 indica una afectación grave del tronco y no puede afirmarse que M1 y M4 tengan igual pronóstico."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394bd") }, {"Justificacion": "La función de riesgo de Framingham de Wilson y colaboradores incluye edad, sexo, colesterol total, colesterol HDL, presión arterial sistólica con o sin tratamiento antihipertensivo, tabaquismo y diabetes, y estima el riesgo de enfermedad coronaria a 10 años. No incorpora directamente el LDL, la presión diastólica, la obesidad, el sedentarismo ni marcadores como la PCR o la homocisteína. En España, la ecuación REGICOR es una adaptación calibrada de Framingham para nuestra población, mientras que SCORE procede de cohortes europeas propias. Las opciones que reducen las variables a edad, sexo, TA y tabaco son incompletas."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394cd") }, {"Respuesta_1": "La diuresis residual carece de valor clínico una vez iniciada la diálisis", "Respuesta_2": "Una diuresis residual por encima de unos 100-200 mL/día se considera clínicamente relevante; su preservación se asocia a menor mortalidad, mejor control del volumen y de la tensión arterial y mejor calidad de vida", "Justificacion": "La función renal residual se valora mediante la diuresis residual, y por debajo de unos 100 mL al día se habla de anuria. Mantener una diuresis superior a ese nivel contribuye a la depuración de solutos y moléculas medianas, facilita el control del volumen y de la tensión arterial, reduce la restricción hídrica y se asocia a menor mortalidad y mejor calidad de vida, tanto en hemodiálisis como en diálisis peritoneal. Por ello hay que evitar nefrotóxicos e hipotensiones. Es falso que no tenga valor una vez iniciada la diálisis o que solo importe en diálisis peritoneal, y 1.000 mL al día no indican que no se necesite diálisis."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394ed") }, {"Respuesta_1": "History, ECG, Age, Risk factors, Troponin; bajo riesgo ≤5", "Justificacion": "El HEART Score valora cinco variables puntuadas de 0 a 2: historia clínica, ECG, edad, factores de riesgo y troponina. En el ECG, la depresión significativa del ST puntúa 2 y las alteraciones inespecíficas de la repolarización, incluido el bloqueo de rama, 1. La edad de 65 años o más puntúa 2 y la de 45-64, 1. Tres o más factores de riesgo o aterosclerosis conocida puntúan 2, y una troponina mayor de tres veces el límite normal, 2. El total va de 0 a 10: 0-3 es bajo riesgo de eventos cardíacos adversos, 4-6 intermedio y 7 o más alto. Un umbral de 5 o menos no es el corte de bajo riesgo."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439518") }, {"Pregunta": "En la valoración del pronóstico neurológico de la encefalopatía hipóxico-isquémica tras una parada cardíaca, ¿cuándo debe realizarse y qué herramientas se usan?", "Justificacion": "Las guías ERC-ESICM de 2021 recomiendan establecer el pronóstico neurológico a partir de las 72 horas tras la recuperación de la circulación espontánea, una vez excluidos los efectos de la sedación y de la hipotermia. La valoración es multimodal: exploración clínica con ausencia de reflejos pupilares y corneales y presencia de estatus mioclónico precoz, EEG con patrones muy malignos, ausencia bilateral de la onda N20 en los potenciales evocados somatosensoriales, enolasa neuronal específica elevada a las 48-72 horas y lesiones difusas en TC o RM. Ningún signo aislado basta, por lo que no se usa solo el GCS, la pupilometría o la RM."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439442") }, {"Pregunta": "La Escala de Ramsay tiene 6 niveles. ¿Qué nivel corresponde a un 'paciente dormido con respuesta lenta a un golpecito glabelar o a un estímulo auditivo fuerte'?", "Justificacion": "En la escala de Ramsay, el nivel 1 es el paciente ansioso o agitado; el 2, despierto, cooperador y tranquilo; el 3, el que solo responde a órdenes verbales; el 4, dormido con respuesta rápida a un golpecito glabelar o a un estímulo auditivo fuerte; el 5, dormido con respuesta lenta a esos mismos estímulos; y el 6, dormido sin respuesta. Por tanto, la respuesta lenta corresponde al nivel 5, que indica sedación profunda. El nivel 4 se distingue por la rapidez de la respuesta, el nivel 3 conserva respuesta a la voz y el nivel 6 no presenta respuesta alguna."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394b8") }, {"Justificacion": "La escala de Borg modificada o CR10 va de 0 a 10 y permite valorar la intensidad de la disnea o del esfuerzo percibido. El 0 significa nada en absoluto, es decir, ausencia total de disnea; 0,5 es muy, muy leve, apenas perceptible; 1 muy leve; 2 leve; 3 moderada; 4 algo intensa; 5 intensa; 7 muy intensa; 9 muy, muy intensa; y 10 máxima. Por tanto, la escala no empieza en 1 ni en 0,5, sino en 0, que es un valor válido. Se usa en rehabilitación respiratoria, pruebas de esfuerzo y seguimiento de pacientes con EPOC o insuficiencia cardíaca."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394c3") }, {"Justificacion": "Los criterios de gravedad japoneses para la pancreatitis aguda pueden aplicarse en cualquier momento de la evolución, mientras que el Score de Ranson necesita 48 horas para completarse. La versión actual combina nueve factores pronósticos clínicos y analíticos, como exceso de bases o shock, PaO2, BUN o creatinina, LDH, plaquetas, calcio, PCR, criterios de SIRS y edad de 70 años o más, con la gradación de la TC con contraste. Se considera grave con 3 o más factores o con grado 2 o superior en la TC. No es más antiguo que Ranson ni se limita a tres parámetros analíticos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394df") }, {"Respuesta_1": "15 ítems autocumplimentados por los padres; se aplica desde los 6 años", "Justificacion": "La CARS de Schopler y colaboradores consta de 15 ítems que el profesional puntúa a partir de la observación directa del niño y de la información de los padres: relación con las personas, imitación, respuesta emocional, uso del cuerpo y de los objetos, adaptación al cambio, respuestas visual, auditiva y sensorial, miedo o nerviosismo, comunicación verbal y no verbal, nivel de actividad, nivel intelectual e impresión general. Cada ítem va de 1 a 4, con un total de 15 a 60; 30 o más sugiere autismo y 37 o más, autismo grave. Se aplica desde los 2 años y no es un cuestionario autocumplimentado por los padres."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43945d") }, {"Justificacion": "En España, el cribado de diabetes gestacional se realiza con el test de O'Sullivan, una sobrecarga de 50 g de glucosa con determinación a la hora, que es positivo con 140 mg/dL o más. Si es positivo, el Grupo Español de Diabetes y Embarazo recomienda confirmar el diagnóstico con una sobrecarga oral de 100 g de glucosa durante 3 horas, aplicando los criterios del NDDG: basal 105, 1 hora 190, 2 horas 165 y 3 horas 145 mg/dL. Dos o más valores alterados confirman la diabetes gestacional. No se inicia dieta ni insulina sin confirmación ni se repite el cribado al mes."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439474") }, {"Justificacion": "El Mini Examen Cognoscitivo de Lobo es la adaptación y validación española del MMSE de Folstein. Su versión original, el MEC-35, valora orientación temporal y espacial, fijación, concentración y cálculo, memoria diferida, pensamiento abstracto mediante semejanzas, y lenguaje y praxis, con nombrar, repetir, comprensión de órdenes, lectura, escritura y copia de un dibujo. Su puntuación máxima es de 35 puntos, y en personas mayores se considera sugestiva de deterioro cognitivo una puntuación inferior a 24, ajustando por edad y escolaridad. La versión MEC-30, equiparable al MMSE, tiene un máximo de 30 puntos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439489") }, {"Justificacion": "En la escala de Silverman-Andersen, la coordinación entre tórax y abdomen se valora con el ítem de movimientos toracoabdominales o disociación toracoabdominal. Puntúa 0 cuando tórax y abdomen se elevan de forma sincrónica, 1 cuando el tórax queda inmóvil y solo se mueve el abdomen, y 2 cuando aparece el balanceo o respiración en balancín, en la que el tórax se hunde mientras el abdomen se eleva. El quejido espiratorio y el aleteo nasal son ítems distintos de la escala, y la expansión torácica no forma parte de ella. Una puntuación alta indica mayor dificultad respiratoria."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394a6") }, {"Justificacion": "En el APACHE II, el apartado de salud crónica suma puntos si el paciente presenta insuficiencia orgánica grave o inmunodepresión. Se otorgan 5 puntos si el paciente no es quirúrgico o si ingresa en la UCI tras cirugía urgente, y 2 puntos si ingresa tras cirugía programada. Por tanto, el ingreso no electivo de un paciente con enfermedad crónica grave suma 5 puntos. Es incorrecto afirmar que no hay diferencia según el tipo de ingreso, y los valores de 2 y 3 puntos no corresponden a esta situación. Este apartado se suma a la puntuación fisiológica aguda y a la puntuación por edad."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439502") }, {"Respuesta_2": "Módulo genérico + módulos específicos de enfermedad (DM, asma, cardiopatía, cáncer, etc.); versiones por grupos de edad (2-4, 5-7, 8-12 y 13-18 años) con autoinforme del niño desde los 5 años e informe paralelo de los padres"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43950b") }, {"Justificacion": "El Index of Spouse Abuse de Hudson y McIntosh tiene 30 ítems distribuidos en dos subescalas: violencia física, con 11 ítems, y violencia no física o psicológica, con 19 ítems. Se responde en escala Likert de 1 a 5 y cada subescala se transforma en una puntuación de 0 a 100, con puntos de corte de 10 para la violencia física y de 25 para la no física. Permite detectar y cuantificar el maltrato en la pareja. La enfermera de atención primaria lo emplea junto con otras herramientas, como el WAST, en el marco del Protocolo Común de Actuación Sanitaria ante la Violencia de Género."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439526") }, {"Pregunta": "En la detección prehospitalaria del ictus, ¿qué herramienta tiene mayor sensibilidad para identificar oclusión de gran vaso (OGV)?", "Respuesta_2": "El RACE Score (Rapid Arterial oCclusion Evaluation), diseñado específicamente para detectar OGV (sensibilidad aproximada del 85% con RACE ≥5)", "Justificacion": "La escala RACE se diseñó en Cataluña como versión prehospitalaria simplificada de la NIHSS para detectar oclusión de gran vaso. Valora paresia facial, del brazo y de la pierna, desviación oculocefálica y afasia o agnosia, y con 5 o más puntos muestra una sensibilidad cercana al 85% para OGV. Esto permite trasladar directamente al paciente a un centro con trombectomía. La Escala de Cincinnati y la de Los Ángeles detectan ictus en general, pero no discriminan bien la OGV, y la NIHSS completa es poco práctica en el medio prehospitalario."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439438") }, {"Respuesta_1": "La categoría I es piel intacta con eritema no blanqueable; la DTI es piel intacta con decoloración púrpura/marrón o ampolla de contenido hemático por daño tisular profundo"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43943f") }, {"Justificacion": "La Braden Q, adaptación pediátrica de la escala de Braden de Quigley y Curley, añade a los seis ítems de la escala adulta un séptimo ítem de perfusión tisular y oxigenación, que tiene en cuenta la presión arterial, la saturación de oxígeno, la hemoglobina y el relleno capilar. Todos los ítems se puntúan de 1 a 4, con un total de 7 a 28, y una puntuación de 16 o menos indica riesgo de lesión por presión. No incluye la edad gestacional ni la temperatura corporal, y la nutrición ya forma parte de la escala original."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439488") }, {"Respuesta_1": "Se sustituye por la valoración de la reactividad pupilar durante el primer año de vida", "Justificacion": "La apertura ocular es un componente observable desde el nacimiento, por lo que en la escala de Glasgow pediátrica se mantiene igual que en el adulto: 4 espontánea, 3 a la voz o llamada, 2 al dolor y 1 ausente. Las adaptaciones pediátricas afectan sobre todo a la respuesta verbal, que se sustituye por llanto, balbuceo o palabras según la edad, y en menor medida a la motora. La reactividad pupilar no sustituye a ningún componente de la escala, sino que se valora aparte. No es cierto que la apertura ocular no pueda evaluarse en menores de 6 meses, y la referencia al llanto de la madre no forma parte de los descriptores."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394ac") }, {"Respuesta_2": "Aleteo nasal y retracciones (tiraje intercostal y retracción xifoidea)", "Justificacion": "La escala de Silverman-Andersen valora cinco signos puntuados de 0 a 2: movimientos toracoabdominales, tiraje intercostal, retracción xifoidea, aleteo nasal y quejido espiratorio. El aleteo nasal y las retracciones intercostal y xifoidea reflejan el reclutamiento de musculatura accesoria ante un aumento del trabajo respiratorio, por lo que son los ítems que mejor lo representan. El quejido es un mecanismo de cierre glótico para mantener volumen pulmonar al final de la espiración, no un signo de musculatura accesoria. La disociación toracoabdominal traduce asincronía y fatiga, y limitarse a las retracciones intercostales deja fuera otros signos de trabajo accesorio."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394d4") }, {"Pregunta": "La Escala de Evaluación de la Actividad Social y Laboral (SOFAS) frente a la GAF. ¿Cuál es la principal ventaja de la SOFAS?", "Respuesta_1": "La SOFAS es más antigua que la GAF y por tanto está más validada", "Respuesta_2": "La SOFAS valora el funcionamiento social y laboral de forma independiente de la gravedad de los síntomas psicopatológicos, evitando la mezcla síntoma-funcionamiento de la GAF", "Respuesta_3": "La GAF no evalúa en absoluto el funcionamiento social; la SOFAS sí", "Respuesta_4": "Son equivalentes en todas las situaciones", "Justificacion": "La GAF combina en una única puntuación de 0 a 100 la gravedad de los síntomas y el nivel de funcionamiento, lo que genera confusión cuando ambos no coinciden, por ejemplo síntomas leves con gran discapacidad. La SOFAS, propuesta en el DSM-IV a partir de la GAF, utiliza la misma escala de 0 a 100 pero puntúa solo el funcionamiento social y laboral, sin que influya directamente la intensidad de los síntomas. No es más antigua que la GAF, sino derivada de ella. La GAF sí incluye el funcionamiento social, aunque mezclado con los síntomas, y ambas escalas no son equivalentes."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394d9") }, {"Respuesta_2": "11 ítems puntuados todos de 0 a 4; puntuación máxima 44", "Respuesta_3": "11 ítems (7 puntuados de 0 a 4 y 4 de 0 a 8); total 0-60, con puntuaciones ≥26 indicativas de manía grave", "Justificacion": "La YMRS de Young (1978) consta de 11 ítems valorados por el clínico: siete se puntúan de 0 a 4 y cuatro (irritabilidad, velocidad y cantidad del habla, contenido del pensamiento y conducta disruptiva-agresiva) de 0 a 8, por su mayor peso, con un total de 0 a 60. En una de las clasificaciones más utilizadas, 0-12 indica ausencia de manía, 13-19 leve, 20-25 moderada y a partir de 26 grave. Un corte por encima de 20 corresponde aún a manía moderada, no todos los ítems puntúan de 0 a 4 y la escala no tiene 15 ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394fb") }, {"Respuesta_1": "11 síntomas; el insomnio tiene el mayor peso (×4)", "Respuesta_2": "11 síntomas (sofocos, parestesias, insomnio, nerviosismo, melancolía, vértigo, debilidad, artralgias/mialgias, cefalea, palpitaciones y hormigueos); los sofocos tienen el mayor peso (×4)", "Justificacion": "El índice de Kupperman valora 11 síntomas climatéricos cuya intensidad (0-3) se multiplica por un factor de ponderación. Los sofocos tienen el mayor peso (×4); parestesias, insomnio y nerviosismo se multiplican por 2, y el resto (melancolía, vértigo, debilidad, artralgias o mialgias, cefalea, palpitaciones y hormigueos) por 1, con una puntuación máxima de 51. El insomnio pondera ×2, no ×4, la escala no tiene 8 síntomas y los ítems no tienen el mismo peso. Aunque se ha sustituido en parte por la Menopause Rating Scale, sigue siendo muy citado en ginecología."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43942f") }, {"Justificacion": "La versión femenina del índice de Lawton-Brody valora 8 actividades instrumentales: uso del teléfono, compras, preparación de la comida, cuidado de la casa, lavado de la ropa, uso de medios de transporte, responsabilidad sobre la medicación y manejo del dinero. Cada actividad puntúa 1 si se conserva la capacidad y 0 si no, de modo que el máximo es 8 puntos (independencia). En la versión clásica para hombres se excluyen la preparación de la comida, el cuidado de la casa y el lavado de la ropa, por lo que su máximo es 5 puntos. Las cifras de 6 y 10 puntos no corresponden a ninguna versión."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43948d") }, {"Respuesta_2": "3", "Respuesta_3": "5-6", "Respuesta_Correcta": "B", "Justificacion": "En la escala de Borg modificada (CR-10), de 0 a 10, el valor 3 corresponde a disnea o esfuerzo moderado. Los descriptores son: 0 nada, 0,5 muy muy leve, 1 muy leve, 2 leve, 3 moderada, 4 algo intensa, 5-6 intensa, 7-8 muy intensa, 9 muy muy intensa y 10 máxima. Los valores 0-1 representan disnea ausente o muy leve, 5-6 disnea intensa y 7-9 disnea muy intensa. En rehabilitación respiratoria suele buscarse un entrenamiento con disnea entre moderada y algo intensa, en torno a 3-4."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439512") }, {"Pregunta": "El MoCA-BLIND es la versión del MoCA adaptada para personas con déficit visual. ¿Cuántos puntos se eliminan respecto a la versión estándar?", "Respuesta_2": "4 puntos (dibujo del cubo y del reloj); puntuación máxima 26", "Respuesta_3": "8 puntos (alternancia conceptual, copia del cubo, dibujo del reloj y denominación de animales); puntuación máxima 22", "Respuesta_Correcta": "C", "Justificacion": "El MoCA-BLIND (Wittich et al., 2010) suprime todos los ítems que requieren estímulos visuales: el trazo alternante (1 punto), la copia del cubo (1), el dibujo del reloj (3) y la denominación de los tres animales (3), es decir, 8 puntos, por lo que la puntuación máxima pasa de 30 a 22. Se conservan memoria, atención, repetición de frases, fluidez verbal, abstracción, recuerdo diferido y orientación. Eliminar solo el cubo y el reloj dejaría ítems visuales como la denominación, y retirar 3 o 5 puntos tampoco corresponde a la versión publicada."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43951c") }, {"Respuesta_2": "10=marcha débil pero no inestable (camina encorvado o se apoya en el mobiliario, pero mantiene el equilibrio); 20=marcha deteriorada o inestable (camina de forma errática y necesita asistencia)"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439527") }, {"Respuesta_3": "10 ítems; la MADRS incluye más síntomas somáticos que la HDRS"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439435") }, {"Justificacion": "La versión corta de 12 ítems de la escala de Zarit (Bédard et al., 2001) se obtuvo a partir de la entrevista original de 22 ítems; cada ítem puntúa de 0 a 4 y una puntuación de 17 o más se considera indicativa de sobrecarga. No debe confundirse con la versión reducida de 7 ítems validada en España para cuidadores en cuidados paliativos, que también emplea el corte de 17, pero que no es la versión de 12 ítems. Los cortes de 25 o 10 no corresponden a esta versión. En la escala completa de 22 ítems, una puntuación de 56 o más indica sobrecarga intensa."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43944b") }, {"Respuesta_2": "Paciente combativo, violento, con peligro inmediato para el personal sanitario"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394a8") }, {"Pregunta": "En el Sistema de Triaje de Manchester, ¿cuántos discriminadores generales, comunes a todos los diagramas de flujo, contempla?", "Respuesta_2": "6 discriminadores generales (riesgo vital, hemorragia, dolor, nivel de conciencia, temperatura y agudeza o tiempo de evolución)", "Justificacion": "El Sistema de Triaje de Manchester utiliza 52 diagramas de flujo según el motivo de consulta y, en todos ellos, aplica seis discriminadores generales: riesgo vital, hemorragia, dolor, nivel de conciencia, temperatura y agudeza o tiempo de evolución. Estos se combinan con discriminadores específicos de cada diagrama para asignar uno de los cinco niveles de prioridad, del rojo al azul. Las cifras de 5 o 10 discriminadores generales no corresponden al sistema, y no es cierto que todos los discriminadores sean específicos de cada flujo, ya que los generales se repiten en todos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394ff") }, {"Respuesta_2": "En atención primaria, como versión abreviada del AUDIT para un cribado rápido del consumo problemático de alcohol; incluye los ítems 1, 2, 4, 5 y 10 del AUDIT completo", "Justificacion": "El AUDIT-PC (Piccinelli et al., 1997) es una versión de 5 ítems del AUDIT pensada para atención primaria. Combina los ítems 1 y 2 de consumo (frecuencia y cantidad habitual) con los ítems 4 (pérdida de control), 5 (incumplimiento de obligaciones) y 10 (preocupación de otros), lo que permite valorar consumo, dependencia y consecuencias en poco tiempo; un punto de corte de 5 se asocia a consumo problemático. No sirve para diagnosticar una intoxicación aguda en urgencias, no equivale al AUDIT completo en todos los contextos y no se limita a pacientes con alcoholismo ya diagnosticado."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439482") }, {"Justificacion": "La escala de Westley para el crup valora cinco parámetros: estridor (0-2), tiraje (0-3), entrada de aire (0-2), cianosis (0-5, con 4 puntos con la agitación y 5 en reposo) y nivel de conciencia (0 o 5 si hay desorientación). La puntuación máxima es por tanto 17 puntos. En la clasificación más utilizada, una puntuación de 2 o menos indica crup leve, 3-7 moderado, 8-11 grave y 12 o más insuficiencia respiratoria inminente. Las cifras de 10, 12 o 15 no corresponden al máximo de la escala, aunque 12 es el umbral de insuficiencia respiratoria inminente."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394e5") }, {"Pregunta": "El Índice de Discapacidad Cervical (NDI - Neck Disability Index). ¿Cuántos ítems tiene y qué evalúa?", "Respuesta_1": "10 ítems (intensidad del dolor, cuidado personal, levantar peso, lectura, cefalea, concentración, trabajo, conducción, sueño y ocio); discapacidad grave 50-68%", "Justificacion": "El NDI (Vernon y Mior, 1991) consta de 10 secciones que valoran el impacto del dolor cervical en la vida diaria: intensidad del dolor, cuidado personal, levantar peso, lectura, cefalea, concentración, trabajo, conducción, sueño y actividades de ocio. Cada una puntúa de 0 a 5 (total 0-50, que suele expresarse en porcentaje). Se interpreta como sin discapacidad 0-8%, leve 10-28%, moderada 30-48%, grave 50-68% y completa por encima del 70%. No tiene 15 ni 5 ítems, no se limita a la intensidad del dolor y un 40% corresponde todavía a discapacidad moderada."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394e8") }, {"Pregunta": "El Cuestionario Breve de Actividad Física (BPAAT, Brief Physical Activity Assessment Tool). ¿Para qué se usa en enfermería comunitaria?", "Respuesta_2": "Para valorar de forma rápida la actividad física habitual del adulto y clasificarlo como suficiente o insuficientemente activo según las recomendaciones de la OMS, orientando el consejo de actividad física en consulta", "Justificacion": "El BPAAT es un cuestionario de dos preguntas sobre la frecuencia y duración de la actividad física vigorosa y moderada en una semana habitual, validado en atención primaria española. Permite clasificar en pocos segundos al adulto como suficientemente activo o insuficientemente activo según las recomendaciones de la OMS (al menos 150 minutos semanales de actividad moderada o 75 de vigorosa) y orientar el consejo breve de actividad física. No diagnostica el sedentarismo como enfermedad, no es una herramienta de prescripción de ejercicio en cardiopatía y tiene aplicación clínica directa, no solo epidemiológica."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394f9") }, {"Justificacion": "El DRSP (Endicott et al., 2006) es un registro diario prospectivo que recoge los 11 síntomas del trastorno disfórico premenstrual del DSM, más ítems de interferencia funcional en el trabajo, las actividades sociales y las relaciones, puntuados de 1 a 6. El diagnóstico requiere confirmar de forma prospectiva, durante al menos dos ciclos consecutivos, la aparición de los síntomas en la fase lútea y su remisión tras la menstruación. Un solo ciclo no basta para el diagnóstico, y el registro no se limita a 5 síntomas ni incluye 20 síntomas a lo largo de 3 ciclos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439504") }, {"Respuesta_1": "Número de cigarrillos/día × años fumando; un índice ≥400 se asocia a riesgo elevado de cáncer de pulmón y EPOC", "Respuesta_3": "Número de paquetes consumidos al día multiplicado por los meses de consumo", "Respuesta_Correcta": "A", "Justificacion": "El índice de Brinkman (Brinkman y Coates, 1963) cuantifica la exposición tabáquica acumulada multiplicando el número de cigarrillos fumados al día por los años de consumo, sin dividir entre 20. Valores de 400 o más se consideran de riesgo elevado de cáncer de pulmón y EPOC. La fórmula que divide los cigarrillos diarios entre 20 y multiplica por los años corresponde al índice paquetes-año, otra medida distinta. Multiplicar paquetes diarios por meses no es ninguna fórmula estandarizada, y un índice que solo considere los cigarrillos diarios ignora la duración de la exposición."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439508") }, {"Pregunta": "El Inventario de Hándicap Auditivo para Adultos (HHIA - Hearing Handicap Inventory for Adults). ¿En qué se diferencia del HHIE-S?", "Respuesta_4": "El HHIA solo puede aplicarse tras una audiometría patológica; el HHIE-S no la requiere", "Justificacion": "El HHIE (Ventry y Weinstein, 1982) se diseñó para personas mayores y su versión de cribado HHIE-S tiene 10 ítems. El HHIA (Newman et al., 1990) es la adaptación para adultos de cualquier edad, con preguntas sobre la vida laboral y social del adulto más joven. Ambos valoran el impacto emocional y social o situacional de la hipoacusia mediante autoinforme. No son idénticos, ninguno incluye audiometría y su aplicación no depende de un resultado audiométrico previo, ya que precisamente sirven para detectar a quién derivar."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43950c") }, {"Pregunta": "El HITS (Hurt, Insult, Threaten, Scream) para la detección de violencia de género. ¿Cuántas preguntas tiene y en qué contexto se aplica?", "Respuesta_2": "4 preguntas de cribado breve (daño físico, insultos, amenazas y gritos), aplicables a cualquier mujer que acude a consulta o a urgencias por cualquier motivo; una puntuación >10 sugiere posible situación de violencia", "Justificacion": "El HITS (Sherin et al., 1998) es un instrumento de cribado breve de violencia en la pareja con 4 preguntas sobre la frecuencia con la que la pareja la daña físicamente, la insulta, la amenaza y le grita, puntuadas de 1 a 5 (total 4-20); más de 10 puntos sugiere violencia. Por su brevedad es útil en atención primaria y en urgencias, servicio al que acuden con frecuencia las mujeres en esta situación, y se aplica a cualquier mujer independientemente del motivo de consulta. No tiene 5 ni 20 preguntas, no se limita a urgencias obstétricas y no exige una agresión física documentada."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439437") }, {"Pregunta": "La Escala de Norton modificada por Ek incorpora la ingesta de alimentos y la ingesta de líquidos a los ítems de la Norton original. ¿Cuántos ítems tiene la versión de Ek?", "Respuesta_Correcta": "C", "Justificacion": "La escala de Norton original tiene 5 ítems: estado físico general, estado mental, actividad, movilidad e incontinencia. La versión modificada por Ek (Modified Norton Scale) añade dos ítems relacionados con la nutrición, la ingesta de alimentos y la ingesta de líquidos, por lo que consta de 7 ítems puntuados de 1 a 4, con un rango de 7 a 28; las puntuaciones más bajas indican mayor riesgo de úlceras por presión. Cinco ítems corresponden a la Norton original, y las cifras de 6 u 8 ítems no corresponden a esta versión."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43943b") }, {"Justificacion": "El RESVECH 2.0 (Restrepo-Medrano y Verdú) es un índice de valoración de la evolución de heridas crónicas que consta de 6 ítems: dimensiones de la lesión, profundidad o tejidos afectados, bordes, tipo de tejido en el lecho, exudado, y signos de infección o inflamación, este último formado por varios subítems. La puntuación total oscila entre 0 y 35, de modo que una puntuación más alta indica peor estado de la herida y su descenso progresivo refleja la cicatrización. Las cifras de 4, 5 u 8 ítems no corresponden a la escala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439450") }, {"Justificacion": "El CURB-65 incluye como único parámetro analítico la urea sérica superior a 7 mmol/L, equivalente a unos 42 mg/dL de urea. Los demás criterios son clínicos: confusión, frecuencia respiratoria de 30 rpm o más, presión arterial sistólica inferior a 90 o diastólica de 60 mmHg o menos, y edad de 65 años o más. Por ello existe la versión CRB-65, sin urea, pensada para atención primaria y otros entornos sin analítica disponible. El lactato, la proteína C reactiva y la creatinina no forman parte de la escala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439431") }, {"Respuesta_Correcta": "B", "Justificacion": "En la escala GDS de Reisberg, el estadio 5 (deterioro cognitivo moderadamente grave, demencia moderada) se caracteriza porque la persona ya no puede recordar aspectos relevantes de su vida actual, como su dirección, su número de teléfono o los nombres de familiares cercanos como los nietos, y necesita ayuda para elegir la ropa. En el GDS 4 los déficits afectan a tareas complejas, como finanzas o viajes, pero se recuerdan los familiares. En el GDS 6 puede olvidar ocasionalmente el nombre del cónyuge y necesita ayuda en las actividades básicas, y en el GDS 7 se pierde el lenguaje y la capacidad psicomotora."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439457") }, {"Justificacion": "El SAPS II (Le Gall, 1993) utiliza 17 variables: 12 fisiológicas recogidas en las primeras 24 horas (frecuencia cardiaca, presión sistólica, temperatura, PaO2/FiO2 si ventilación, diuresis, urea, leucocitos, potasio, sodio, bicarbonato, bilirrubina y Glasgow), la edad, el tipo de ingreso (médico, quirúrgico programado o urgente) y tres enfermedades crónicas (sida, cáncer metastásico y neoplasia hematológica). Estima la mortalidad hospitalaria del paciente crítico y es una alternativa más sencilla al APACHE II. Las cifras de 10, 12 o 20 variables no corresponden a esta escala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43948f") }, {"Pregunta": "La Escala de Menten valora 8 signos clínicos para identificar la situación de últimos días. ¿Cuántos signos deben estar presentes para considerar que el paciente se encuentra en situación agónica?", "Respuesta_1": "1 signo", "Respuesta_2": "2 signos", "Respuesta_3": "4 o más signos", "Respuesta_4": "Los 8 signos", "Respuesta_Correcta": "C", "Justificacion": "La escala de Menten recoge 8 signos de proximidad de la muerte: nariz fría o pálida, extremidades frías, livideces, labios cianóticos, estertores premortem, pausas de apnea de más de 15 segundos, oliguria inferior a 300 mL al día y somnolencia de más de 15 horas al día. La presencia de 4 o más signos indica situación agónica, con alta probabilidad de fallecimiento en los días siguientes, y debe orientar la adecuación de los cuidados. Uno o dos signos aislados no permiten establecer la situación agónica, y no es necesario que estén presentes los 8."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394c2") }, {"Pregunta": "El Índice de Calidad de Vida Gastrointestinal (GIQLI, Gastrointestinal Quality of Life Index) de Eypasch. ¿Para qué enfermedad gastrointestinal fue diseñado y cuántos ítems tiene?", "Justificacion": "El GIQLI (Eypasch et al., 1995) es un cuestionario de calidad de vida de 36 ítems puntuados de 0 a 4, con un total de 0 a 144, en el que mayor puntuación indica mejor calidad de vida. Agrupa los ítems en cinco dimensiones: síntomas gastrointestinales, estado emocional, función física, función social y tratamiento médico. Está diseñado para cualquier enfermedad gastrointestinal, por lo que permite comparar el impacto de distintas patologías digestivas y de su tratamiento, médico o quirúrgico. No es específico de la enfermedad inflamatoria intestinal, del reflujo gastroesofágico ni del intestino irritable."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394ce") }, {"Pregunta": "El cuestionario DASH (Disabilities of the Arm, Shoulder and Hand). ¿Cuál es la MCID (mínima diferencia clínicamente importante) de su versión abreviada QuickDASH?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394e4") }, {"Respuesta_2": "4 pruebas: orientación temporal de Benton, fluidez verbal por categorías (animales), recuerdo facilitado de 16 ítems y test del reloj", "Justificacion": "El 7-Minute Screen (Solomon et al., 1998) se diseñó para detectar la enfermedad de Alzheimer en unos 7 minutos mediante 4 pruebas: orientación temporal de Benton, recuerdo libre y facilitado de 16 ítems presentados con imágenes, test del reloj y fluidez verbal semántica de animales durante un minuto. Sus resultados se combinan para estimar la probabilidad de demencia, con alta sensibilidad y especificidad frente al envejecimiento normal. No consta de 7 pruebas de un minuto, no evalúa actividades básicas ni movilidad y no se limita a memoria y función ejecutiva, ya que incluye orientación y lenguaje."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43947f") }, {"Justificacion": "La PANSS consta de 30 ítems (7 positivos, 7 negativos y 16 de psicopatología general), cada uno puntuado de 1 (ausente) a 7 (extremo). Como el valor mínimo de cada ítem es 1, la puntuación mínima posible es 30, que indica ausencia de síntomas, y la máxima 210. Por ello no puede obtenerse 0 puntos. Las cifras de 7 y 14 corresponden a los mínimos de las subescalas positiva o negativa por separado, no al total. Los criterios de remisión de Andreasen (2005) exigen puntuaciones de 3 o menos en ocho ítems clave mantenidas al menos seis meses."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394be") }, {"Justificacion": "La escala de incapacidad física de la Cruz Roja tiene 6 grados, de 0 a 5. El grado 2 describe a la persona que tiene alguna dificultad para las actividades de la vida diaria, necesita ayuda ocasional y deambula con bastón u otro apoyo, manejándose en general por sí misma, que es el caso planteado. El grado 0 corresponde a independencia total y marcha normal; el 1 a quien realiza las actividades de forma suficiente con alguna dificultad para deambular; el 3 a grave dificultad, con marcha que precisa ayuda de al menos una persona; el 4 a necesidad de ayuda para casi todo, y el 5 a encamamiento con cuidados constantes."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394c5") }, {"Respuesta_2": "Para lactantes en los primeros meses de vida, con fotografías que valoran la consistencia, la cantidad y el color de las heces del lactante", "Justificacion": "La Amsterdam Infant Stool Scale (Bekkali et al., 2009) se desarrolló para describir de forma fiable las heces de lactantes pequeños, alimentados con leche materna o con fórmula, en los que la escala de Bristol no es adecuada porque sus heces son más blandas y de colores distintos. Mediante fotografías clasifica la consistencia (líquida, blanda, formada o dura), la cantidad y el color. No está pensada para escolares ni adolescentes, en los que se usa la escala de Bristol, ni se limita a valorar el meconio en las primeras 48 horas de vida."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394c9") }, {"Pregunta": "La técnica SLED (Sustained Low-Efficiency Dialysis). ¿Qué es y en qué se diferencia de la HDVVC?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394cc") }, {"Pregunta": "La versión renal del Sistema de Evaluación de Síntomas de Edmonton (ESAS-r: Renal). ¿Para qué se usa en la enfermería nefrológica?", "Justificacion": "El ESAS-r: Renal adapta el ESAS revisado a la enfermedad renal crónica, añadiendo síntomas frecuentes en la uremia como el prurito, los calambres, las piernas inquietas o los problemas de sueño. Permite cuantificar de 0 a 10 la carga sintomática de pacientes con ERC avanzada, tanto en diálisis como en tratamiento conservador, y orientar el control de síntomas, la planificación entre diálisis y manejo conservador y el seguimiento de la calidad de vida. No decide por sí solo el inicio de la diálisis, no clasifica el síndrome nefrótico y no se limita a la hemodiálisis."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394de") }, {"Pregunta": "¿Qué escala se utiliza para valorar el nivel de sedación y el malestar en el niño con ventilación mecánica ingresado en UCIP?", "Respuesta_2": "La Escala COMFORT-B, diseñada para valorar sedación y malestar en niños ventilados de todas las edades en UCIP", "Justificacion": "La escala COMFORT-B (van Dijk et al., 2000) es la referencia para valorar sedación y malestar en niños con ventilación mecánica en UCIP. Observa seis conductas: alerta, calma o agitación, respuesta respiratoria (o llanto en respiración espontánea), movimientos físicos, tono muscular y tensión facial, cada una de 1 a 5, con un total de 6 a 30. Puntuaciones de 6 a 10 sugieren sobresedación, de 11 a 22 un nivel adecuado y de 23 o más malestar. La escala de Ramsay no es específica pediátrica, la RASS se diseñó en adultos y el Glasgow mide el nivel de conciencia, no la sedación."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4394e0") }, {"Pregunta": "El Cuestionario de Tos de Leicester (LCQ - Leicester Cough Questionnaire). ¿Qué evalúa y en qué pacientes se utiliza?", "Respuesta_1": "Evalúa la función pulmonar mediante autoevaluación en el asma persistente", "Respuesta_2": "Evalúa el impacto de la tos crónica en la calidad de vida (dominios físico, psicológico y social) en adultos con tos crónica", "Respuesta_3": "Evalúa solo la tos de la tosferina en la fase catarral", "Respuesta_4": "Evalúa las exacerbaciones de la fibrosis quística como criterio de ingreso", "Justificacion": "El LCQ (Birring et al., 2003) es un cuestionario autoadministrado de 19 ítems que mide el impacto de la tos crónica en la calidad de vida del adulto en tres dominios: físico, psicológico y social, con una puntuación total de 3 a 21, en la que valores más altos indican mejor calidad de vida. Se utiliza para valorar la repercusión de la tos y su respuesta al tratamiento. No mide la función pulmonar, que requiere espirometría, no es específico de la tosferina y no es un marcador de exacerbación en la fibrosis quística. Para niños existen adaptaciones específicas."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43950a") }, {"Pregunta": "En atención primaria, ¿cuál es la forma más breve y habitual de determinar la fase de abandono del tabaco en la que se encuentra un fumador?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43955e") }, {"Pregunta": "En el Sistema de Evaluación de Síntomas de Edmonton (ESAS), ¿a partir de qué puntuación se considera que un síntoma tiene intensidad grave?", "Respuesta_1": "≥1 punto", "Respuesta_2": "≥4 puntos", "Respuesta_3": "≥7 puntos", "Respuesta_4": "Solo la puntuación de 10", "Justificacion": "En el ESAS cada síntoma se puntúa de 0 (ausente) a 10 (peor posible). Por convención, 1-3 se considera intensidad leve, 4-6 moderada y 7-10 grave, de modo que un síntoma con 7 o más puntos se califica como grave y requiere una intervención activa y una reevaluación precoz. Una puntuación de 1 indica únicamente que el síntoma está presente, de 4 a 6 corresponde a intensidad moderada, y limitar la gravedad al valor 10 dejaría fuera síntomas intensos que precisan tratamiento."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439562") }, {"Respuesta_2": "El KPS tiene 11 niveles (de 0 a 100 de 10 en 10), lo que dificulta la reproducibilidad entre evaluadores, mientras que el ECOG tiene 6 categorías (0-5) más diferenciadas y mejor concordancia", "Justificacion": "La principal crítica al índice de Karnofsky es su menor reproducibilidad entre observadores, ya que tiene 11 niveles de 0 a 100 que a veces son difíciles de distinguir. El ECOG, con 6 categorías (0 a 5, donde 5 es fallecimiento), es más sencillo y muestra mejor concordancia, por lo que se prefiere en ensayos clínicos; a cambio, el KPS discrimina mejor cambios sutiles. El KPS es válido para tumores sólidos y hematológicos y para pacientes hospitalizados, y el ECOG no es superior en todos los aspectos."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439592") }, {"Pregunta": "El cuestionario SDSCA (Summary of Diabetes Self-Care Activities). ¿Qué lo diferencia del DTSQ?", "Respuesta_1": "El SDSCA evalúa solo la actividad física en la diabetes; el DTSQ evalúa la satisfacción", "Respuesta_2": "El DTSQ evalúa la satisfacción con el tratamiento; el SDSCA evalúa la frecuencia con que el paciente realiza las conductas de autocuidado (dieta, ejercicio, autoanálisis, cuidado de los pies y medicación)", "Respuesta_4": "El SDSCA es para DM1 y el DTSQ para DM2", "Justificacion": "El DTSQ (Diabetes Treatment Satisfaction Questionnaire) mide la satisfacción percibida con el tratamiento de la diabetes. El SDSCA (Toobert et al., 2000) pregunta en cuántos de los últimos siete días el paciente siguió el plan de alimentación, hizo ejercicio, realizó autoanálisis de glucemia, revisó sus pies y tomó la medicación, es decir, cuantifica la conducta de autocuidado. Son instrumentos complementarios y no equivalentes. El SDSCA no se limita a la actividad física, y ninguno de los dos es exclusivo de un tipo de diabetes."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395a4") }, {"Pregunta": "¿Cuál de las siguientes escalas está diseñada específicamente para valorar el riesgo de caídas en pacientes hospitalizados y es una de las más usadas en los hospitales españoles?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395af") }, {"Pregunta": "La Escala Nottingham Extendida de Actividades de la Vida Diaria (NEADL) frente al índice de Barthel. ¿Cuál es la diferencia principal?", "Respuesta_1": "La NEADL valora actividades instrumentales en el domicilio y la comunidad (movilidad exterior, cocina, tareas domésticas y ocio); el Barthel valora solo actividades básicas", "Respuesta_2": "La NEADL valora solo la movilidad en la cama y las transferencias; el Barthel incluye las tareas domésticas", "Respuesta_Correcta": "A", "Justificacion": "La NEADL (Nouri y Lincoln, 1987) consta de 22 ítems agrupados en cuatro áreas: movilidad, cocina, tareas domésticas y ocio, por lo que valora actividades instrumentales propias de la vida en el domicilio y en la comunidad. El índice de Barthel, en cambio, valora 10 actividades básicas como alimentación, baño, aseo, vestido, continencia, uso del retrete, transferencias, deambulación y escaleras. La NEADL no se limita a la movilidad en la cama, las escalas no son equivalentes y, aunque se desarrolló en pacientes con ictus, se aplica también en otras poblaciones."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395d4") }, {"Justificacion": "En la escala de Bromage, 0 indica ausencia de bloqueo (eleva la pierna extendida), 1 bloqueo parcial (flexiona la rodilla pero no eleva la pierna extendida), 2 bloqueo casi completo (solo mueve los pies) y 3 bloqueo completo. La puérpera descrita presenta Bromage 1, es decir, mantiene bloqueo motor residual, por lo que debe permanecer en la URPA vigilando la regresión del bloqueo y la estabilidad hemodinámica hasta cumplir los criterios de alta motora del protocolo. No está en Bromage 0, y los grados 2 y 3 no corresponden a la exploración ni justifican intubación o reintervención."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439531") }, {"Respuesta_2": "Para evaluar la MOTIVACIÓN del fumador para dejar de fumar (4 preguntas sobre el deseo de dejarlo, el interés, el intento en las próximas dos semanas y la expectativa de ser exfumador en 6 meses); orienta el tipo de intervención", "Justificacion": "El test de Richmond (1993) mide la motivación para dejar de fumar con 4 preguntas: si le gustaría dejarlo si pudiera hacerlo fácilmente (0-1), cuánto interés tiene en dejarlo (0-3), si intentará dejarlo en las próximas dos semanas (0-3) y qué probabilidad cree tener de ser exfumador en 6 meses (0-3). El total va de 0 a 10: 6 o menos indica motivación baja, 7-9 moderada y 10 alta. La dependencia física se mide con el test de Fagerström, y el Richmond no calcula la dosis de parches ni detecta síntomas de abstinencia."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43954b") }, {"Respuesta_1": "Pressure, Elasticity, Relaxation, Flexibility, Extension, Contraction, Tone", "Justificacion": "El esquema PERFECT (Laycock) valora la musculatura del suelo pélvico mediante palpación: P (Power, fuerza según la escala de Oxford), E (Endurance, segundos de contracción mantenida), R (Repetitions, número de contracciones mantenidas), F (Fast, contracciones rápidas) y ECT, que en la versión más difundida se desglosa en Elevation (elevación), Co-contraction (cocontracción abdominal) y Timing (coordinación con la tos). Las demás opciones no corresponden al acrónimo: la combinación de presión, elasticidad o tono no forma parte de la escala, y no es un acrónimo en español."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43953c") }, {"Respuesta_1": "1 punto por cada 5 años a partir de los 65 años"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439556") }, {"Justificacion": "El Copenhagen Burnout Inventory (Kristensen et al., 2005) entiende el burnout como fatiga y agotamiento físico y psicológico, sin incluir la despersonalización ni la realización personal del MBI. Consta de 19 ítems en tres subescalas: burnout personal (6 ítems), burnout relacionado con el trabajo (7) y burnout relacionado con el cliente o paciente (6), puntuadas de 0 a 100; valores de 50 o más suelen considerarse elevados. No es un constructo unitario, no es exclusivo de profesionales sanitarios y es posterior al MBI, al que no ha sustituido."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439566") }, {"Justificacion": "El SNAQ (Kruizenga et al., 2005) es una herramienta de cribado nutricional holandesa con 3 preguntas: pérdida de peso involuntaria (más de 6 kg en 6 meses puntúa 3; más de 3 kg en el último mes, 2), disminución del apetito en el último mes (1) y uso de suplementos o nutrición por sonda en el último mes (1). Una puntuación de 0-1 no requiere intervención, 2 indica desnutrición moderada y 3 o más desnutrición grave. Se usa en pacientes hospitalizados y ambulatorios. No tiene 5, 10 o 4 ítems ni es exclusivo de oncología o de residencias."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395d0") }, {"Pregunta": "La Escala de Resultados y Gravedad de la Disfagia (DOSS - Dysphagia Outcome and Severity Scale). ¿Cuántos niveles describe y cuál indica que el paciente no puede alimentarse por vía oral?", "Respuesta_4": "7 niveles; nivel 7 = alimentación exclusiva por sonda", "Respuesta_Correcta": "B", "Justificacion": "La DOSS (O'Neil et al., 1999) clasifica la disfagia en 7 niveles a partir de la exploración de la deglución. El nivel 1 corresponde a disfagia grave en la que no es posible ninguna ingesta oral segura, por lo que el paciente se alimenta solo por sonda; los niveles 2 a 5 describen disfagia de grave a leve con distintas modificaciones de dieta y supervisión; el 6 límites funcionales con independencia modificada, y el 7 deglución normal en todas las situaciones. La escala no tiene 5 niveles y el nivel 7 corresponde a dieta normal, no a alimentación por sonda."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43953b") }, {"Justificacion": "El delirium es muy frecuente en UCI: según los estudios de Ely y otros autores, afecta al 60-80% de los pacientes con ventilación mecánica invasiva y al 20-50% de los no ventilados. Se asocia a más días de ventilación, mayor estancia, mayor mortalidad y deterioro cognitivo a largo plazo, por lo que debe cribarse de forma sistemática con la CAM-ICU. Las medidas preventivas más eficaces son no farmacológicas y se agrupan en el paquete ABCDEF: valoración y manejo del dolor, pruebas de despertar y de respiración espontánea, elección de analgesia y sedación, delirium, movilización precoz e implicación de la familia. Las cifras de 5-20% infravaloran el problema."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43956e") }, {"Pregunta": "La Escala de Frecuencia de Espasmos de Penn. ¿Para qué tipo específico de espasticidad fue diseñada y cómo se diferencia de la Ashworth?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395ae") }, {"Justificacion": "En la escala de Braden, el ítem nutrición puntúa 1 (muy deficiente) cuando el paciente nunca come una comida completa, raramente come más de un tercio de lo que se le ofrece, toma dos raciones de proteínas o menos al día, bebe pocos líquidos y no toma suplementos, o bien está en dieta absoluta o con líquidos claros más de cinco días. La puntuación 2 (probablemente inadecuada) corresponde a quien raramente come más de la mitad, la 3 (adecuada) a quien come más de la mitad de la mayoría de las comidas o recibe nutrición enteral o parenteral adecuada, y la 4 (excelente) a quien come la mayor parte de cada comida."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395b3") }, {"Pregunta": "¿Qué herramienta permite estimar el riesgo individual de sepsis neonatal precoz combinando los factores de riesgo maternos con la evolución clínica del recién nacido?", "Respuesta_2": "La Calculadora de Sepsis Neonatal de Kaiser Permanente (Early-Onset Sepsis Calculator), basada en factores de riesgo maternos y neonatales", "Justificacion": "La calculadora de sepsis neonatal precoz de Kaiser Permanente (Escobar, Puopolo et al.) estima el riesgo individual en recién nacidos de 34 semanas o más combinando la edad gestacional, la temperatura materna intraparto, las horas de bolsa rota, el estado de colonización por estreptococo del grupo B y el tipo de profilaxis antibiótica intraparto con la situación clínica del neonato. Expresa el riesgo por cada 1.000 nacidos y recomienda observación, analítica o antibioterapia, lo que ha reducido el uso innecesario de antibióticos. El CRIES valora el dolor, el Apgar la adaptación al nacer y una PCR aislada al nacimiento no estima el riesgo."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395cb") }, {"Justificacion": "El DAPSA suma cinco componentes: número de articulaciones dolorosas (sobre 68), número de articulaciones tumefactas (sobre 66), PCR en mg/dL, valoración del dolor por el paciente (EVA 0-10) y valoración global de la actividad por el paciente (EVA 0-10). La puntuación se interpreta así: remisión ≤4, actividad baja 5-14, moderada 15-28 y alta >28, por lo que la opción correcta combina cinco componentes con remisión ≤4. Las opciones con cuatro o tres componentes no corresponden a la estructura del índice, y el umbral ≤8 no define remisión sino que ya se sitúa en actividad baja. Es el índice de actividad específico recomendado en la artritis psoriásica periférica."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395d6") }, {"Pregunta": "El Perineal Assessment Tool (PAT) de Nix valora cuatro factores: intensidad del irritante (tipo de incontinencia), duración de la exposición al irritante, estado de la piel perineal y factores contribuyentes. ¿Cuál es el objetivo principal de esta herramienta?", "Respuesta_2": "Valorar el riesgo de dermatitis asociada a la incontinencia (DAI) en la piel perineal para orientar medidas preventivas", "Justificacion": "El PAT, desarrollado por Nix, es una herramienta de valoración del riesgo de dermatitis asociada a la incontinencia. Puntúa de 1 a 3 cuatro factores: intensidad del irritante (heces formadas, blandas o líquidas, con o sin orina), duración de la exposición, estado de la piel perineal y factores contribuyentes como hipoalbuminemia, antibióticos o nutrición enteral. El total oscila entre 4 y 12, y una puntuación de 7 a 12 indica alto riesgo, lo que orienta a intensificar la limpieza suave, la protección cutánea y el control de la incontinencia. No sirve para valorar el dolor perineal posparto, clasificar desgarros obstétricos ni medir la cicatrización de la episiotomía.", "Fuente": "Nix DH. Validity and reliability of the Perineal Assessment Tool. Ostomy Wound Manage. 2002;48(2):43-9."});
rm('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43953f") });
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439551") }, {"Respuesta_Correcta": "B", "Justificacion": "Prechtl describió cinco estados conductuales del recién nacido, definidos por la apertura ocular, la regularidad respiratoria, los movimientos groseros y la vocalización: estado 1, sueño tranquilo o regular; estado 2, sueño activo o irregular; estado 3, despierto con ojos abiertos y sin movimientos groseros; estado 4, despierto con ojos abiertos y movimientos groseros; y estado 5, llanto. La clasificación de seis estados, que separa somnolencia, alerta tranquila, alerta activa y llanto, corresponde a la escala de Brazelton, no a la de Prechtl. Las opciones de tres y cuatro estados no recogen la secuencia completa sueño-vigilia-llanto descrita por Prechtl."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43958b") }, {"Justificacion": "La clasificación PEDIS del International Working Group on the Diabetic Foot valora cinco dimensiones: Perfusion (perfusión arterial, grados 1-3), Extent/size (extensión de la úlcera en cm²), Depth/tissue loss (profundidad: 1 superficial, 2 hasta fascia, músculo o tendón, 3 con afectación de hueso o articulación), Infection (1 sin infección, 2 leve, 3 moderada, 4 grave con respuesta sistémica) y Sensation (1 sin neuropatía, 2 neuropatía presente). Se diseñó para investigación y comunicación entre profesionales, y su componente de infección es la base de la clasificación IWGDF/IDSA. Las demás opciones inventan dimensiones como edema, presión, desbridamiento o severidad, que no forman parte del acrónimo."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395a3") }, {"Respuesta_2": "El apoyo social funcional percibido (confidencial y afectivo); 11 ítems. Punto de corte de bajo apoyo social: puntuación total <32", "Justificacion": "El cuestionario DUKE-UNC-11, validado en España por Bellón y colaboradores, mide el apoyo social funcional percibido en dos dimensiones: apoyo confidencial (tener personas con quien hablar de problemas y que aconsejen) y apoyo afectivo (demostraciones de cariño y empatía). Tiene 11 ítems tipo Likert de 1 a 5, con un rango total de 11 a 55, y una puntuación inferior a 32 indica apoyo social percibido bajo. Se utiliza en atención primaria para detectar aislamiento y riesgo social. No mide el tamaño de la red social, no se limita al apoyo emocional con cinco ítems y no está diseñado para el contexto laboral."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395c9") }, {"Pregunta": "La Escala de Espasticidad de Tardieu. ¿En qué se diferencia de la Escala de Ashworth Modificada?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395da") }, {"Pregunta": "La enfermera de atención primaria aplica el Cuestionario de calidad de vida en estreñimiento CVE-20 a una paciente de 68 años. ¿Qué dimensiones evalúa este cuestionario?", "Respuesta_2": "Emocional, física general, física rectal y social", "Justificacion": "El CVE-20 es un cuestionario específico de calidad de vida en el estreñimiento crónico desarrollado y validado en España por Garrigues y colaboradores. Sus 20 ítems se agrupan en cuatro dimensiones: emocional (preocupaciones, obsesión por evacuar), física general (hinchazón, malestar, molestias de los tratamientos), física rectal (dolor anal, miedo a desgarrarse, hemorroides) y social (gases, dependencia de laxantes, vergüenza). Cada ítem se puntúa de 0 a 4 y las respuestas próximas a nunca reflejan mejor calidad de vida. No mide hábitos como dieta o hidratación, ni frecuencia y consistencia de las heces, ni parámetros manométricos o de tránsito colónico."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43953d") }, {"Justificacion": "STRATIFY (Oliver y colaboradores, 1997) es una herramienta de cinco ítems dicotómicos, desarrollada en pacientes mayores ingresados en plantas de agudos: caída previa (en el ingreso actual o motivo de ingreso), agitación, deterioro visual que afecta a la vida diaria, necesidad de ir al baño con frecuencia y una puntuación combinada de transferencia y movilidad del Barthel de 3 o 4 (movilidad parcialmente comprometida). El total va de 0 a 5 y una puntuación ≥2 indica alto riesgo de caída. No se diseñó para urgencias ni para residencias, tiene cinco ítems y no siete, y no es una adaptación europea de la escala de Morse."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43956d") }, {"Respuesta_4": "La Rankin evalúa exclusivamente la función cognitiva y el lenguaje tras el ictus", "Justificacion": "El índice de Barthel puntúa de 0 a 100 diez actividades básicas de la vida diaria concretas y es más sensible a los cambios funcionales durante la rehabilitación. La escala de Rankin modificada clasifica en siete categorías (0-6) el impacto global de la discapacidad, por lo que es menos sensible al cambio pero muy útil para expresar el resultado funcional a largo plazo y es la variable principal de los ensayos de reperfusión en ictus. No miden lo mismo, ninguna es superior para todos los propósitos y la Rankin no se limita a la cognición o el lenguaje, sino que valora la discapacidad global y el grado de dependencia."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439576") }, {"Respuesta_2": "10 ítems; punto de corte ≥20 para derivación", "Justificacion": "La EPDS consta de 10 ítems puntuados de 0 a 3, con un total de 0 a 30. En España se utiliza habitualmente una puntuación ≥10 como cribado positivo de posible depresión perinatal que requiere evaluación por salud mental, y puntuaciones más altas (≥12-13) se asocian a probable depresión mayor. El ítem 10, sobre pensamientos de autolesión, exige valoración inmediata con cualquier puntuación total. Un punto de corte de ≥20 dejaría sin detectar a la mayoría de los casos, ≥8 no es el umbral de derivación recomendado y la escala no tiene 14 ítems. Se aplica en el embarazo y en el posparto."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439540") }, {"Pregunta": "La Escala de Agitación-Sedación de Richmond (RASS). ¿Qué nivel de RASS indica el objetivo ideal de sedación en un paciente en VMI según las guías PADIS 2018?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439545") }, {"Respuesta_1": "Cualquier ganancia de peso, aunque sea inferior a 1 gramo", "Respuesta_2": "Más de 1 gramo", "Justificacion": "En el pad test de 1 hora estandarizado por la ICS, la paciente lleva una compresa previamente pesada mientras bebe 500 ml y realiza una secuencia de actividades: caminar, subir escaleras, sentarse y levantarse, toser, correr en el sitio y lavarse las manos. Una ganancia de peso superior a 1 gramo se considera positiva, ya que hasta 1 gramo entra en el margen de error por sudor o flujo vaginal. Por eso cualquier ganancia mínima no es diagnóstica, y exigir 10 o 20 gramos dejaría sin detectar incontinencias leves. La cantidad perdida permite además graduar la gravedad."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395ce") }, {"Pregunta": "La Escala de Conflicto Decisional (DCS - Decisional Conflict Scale). ¿Para qué se utiliza en la práctica enfermera avanzada?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439539") }, {"Pregunta": "El NUTRISCORE (Arribas et al., Institut Català d'Oncologia) es una herramienta de cribado del riesgo de desnutrición. ¿Cuándo se aplica y para qué tipo de paciente?", "Justificacion": "El NUTRISCORE es una herramienta de cribado nutricional desarrollada y validada en España específicamente para pacientes oncológicos ambulatorios. Combina la pérdida de peso, la ingesta reducida, la localización del tumor y el tratamiento oncológico que recibe el paciente, de modo que permite identificar precozmente, al inicio y durante la quimioterapia o radioterapia, a quién derivar para valoración e intervención nutricional. La desnutrición en cáncer es frecuente y aumenta la toxicidad y empeora la supervivencia. No es una herramienta para cualquier paciente hospitalizado, ni se limita a enfermos terminales ni al postoperatorio de cirugía digestiva.", "Fuente": "Arribas L et al. NUTRISCORE: a new nutritional screening tool for oncological outpatients. Nutrition. 2017;33:297-303."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439544") }, {"Pregunta": "El King's Health Questionnaire (KHQ) frente al ICIQ-SF en la incontinencia urinaria. ¿Cuál es la principal diferencia?", "Respuesta_1": "El KHQ tiene más ítems y evalúa el impacto físico, emocional, social y en las relaciones personales de la incontinencia; el ICIQ-SF es más breve y de cribado y seguimiento", "Respuesta_2": "El KHQ es para hombres y el ICIQ-SF solo para mujeres", "Respuesta_4": "El KHQ evalúa la incontinencia fecal; el ICIQ-SF solo la urinaria", "Justificacion": "El King's Health Questionnaire es un cuestionario específico de calidad de vida en incontinencia urinaria, validado en español, con unos 21 ítems agrupados en dominios como percepción de salud, impacto de la incontinencia, limitación de actividades, limitaciones físicas y sociales, relaciones personales, emociones, sueño y gravedad. El ICIQ-SF tiene solo tres ítems puntuables (frecuencia, cantidad e impacto) y sirve para cribado y seguimiento rápido. Ambos se aplican a hombres y mujeres, se centran en la incontinencia urinaria y no son equivalentes, ya que el KHQ ofrece una evaluación mucho más amplia del impacto en la calidad de vida.", "Fuente": "Kelleher CJ et al. A new questionnaire to assess the quality of life of urinary incontinent women. BJOG. 1997; Espuña M et al. ICIQ-SF. Med Clin (Barc). 2004."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43954d") }, {"Pregunta": "El IBFAT (Infant Breastfeeding Assessment Tool). ¿Para qué se utiliza específicamente?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439559") }, {"Justificacion": "El CoPsoQ-istas21 es la adaptación española del Copenhagen Psychosocial Questionnaire y el método de evaluación de riesgos psicosociales más utilizado en España. En sus versiones actuales mide alrededor de 20 dimensiones psicosociales (la versión inicial identificaba 21, de ahí su nombre), agrupadas en cinco grandes áreas: exigencias psicológicas, trabajo activo y posibilidades de desarrollo, apoyo social y calidad de liderazgo, compensaciones y doble presencia. Las opciones de 3, 5 u 8 dimensiones se quedan cortas: la de tres dimensiones corresponde más bien al modelo demanda-control-apoyo de Karasek y Johnson, que es una de las bases teóricas del cuestionario."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439571") }, {"Justificacion": "La Chedoke-McMaster Stroke Assessment se desarrolló en Canadá para personas que han sufrido un ictus. Consta de un Inventario de Deterioro, con seis dimensiones (dolor de hombro, control postural, brazo, mano, pierna y pie) clasificadas en siete estadios de recuperación motora basados en Brunnstrom, y de un Inventario de Actividad, que valora la función motora gruesa y la marcha con una puntuación de 1 a 7 por ítem. Permite planificar objetivos y medir la recuperación en rehabilitación del ictus. No se diseñó para esclerosis múltiple, traumatismo craneoencefálico ni parálisis cerebral infantil, aunque se haya aplicado ocasionalmente en otras poblaciones."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43958e") }, {"Justificacion": "El DTSQ, desarrollado por Clare Bradley, mide la satisfacción del paciente con su tratamiento de la diabetes, sea dieta, antidiabéticos orales o insulina. Tiene 8 ítems: seis forman la puntuación de satisfacción (satisfacción con el tratamiento actual, conveniencia, flexibilidad, satisfacción con la comprensión de su diabetes, disposición a recomendar el tratamiento y deseo de continuar con él), con un rango de 0 a 36, y otros dos valoran la frecuencia percibida de hiperglucemias e hipoglucemias. Es muy utilizado en ensayos clínicos. No estima el riesgo de complicaciones, no clasifica el tipo de diabetes y no mide directamente la adherencia terapéutica."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43957a") }, {"Justificacion": "El DET score, desarrollado por un grupo internacional de estomaterapeutas y dermatólogos (Ostomy Skin Tool), evalúa tres categorías de la piel periestomal: decoloración, erosión y crecimiento tisular (hiperplasia). En cada categoría se puntúa el área afectada (0-3) y la gravedad (1-2), de modo que cada dominio alcanza 5 puntos y el total oscila entre 0 y 15. Permite cuantificar el daño cutáneo de forma objetiva, monitorizar su evolución y valorar la eficacia de los cuidados. No tiene cinco ni dos categorías, no se limita a ileostomías ni a complicaciones infecciosas, y no incluye la hernia paraestomal, que es una complicación del estoma y no de la piel."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43959c") }, {"Pregunta": "Los criterios FIGO para clasificar el registro cardiotocográfico (CTG). Además de la línea de base y la variabilidad, ¿qué otros parámetros evalúan?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e0") }, {"Pregunta": "Recién nacido a término. Al minuto de vida: FC 110 lpm, llanto fuerte, tono muscular bueno con movimientos activos, responde con estornudo al aspirado nasal, color completamente rosado. ¿Cuál es el Apgar al minuto y qué actuación corresponde?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439530") }, {"Pregunta": "Encefalopatía hepática graduada según la escala de West Haven. ¿Qué papel tiene en la indicación de trasplante hepático urgente en el fallo hepático agudo?", "Respuesta_1": "La encefalopatía hepática grado 3-4 (West Haven) forma parte de los criterios de trasplante urgente en el fallo hepático agudo, como los del King's College, junto con el INR, la bilirrubina, la creatinina y el pH", "Justificacion": "La escala de West Haven gradúa la encefalopatía hepática de 0 a 4, desde alteraciones mínimas hasta el coma. En el fallo hepático agudo, la encefalopatía de grado 3-4 es un marcador de gravedad que forma parte de los criterios del King's College (junto con INR, bilirrubina, creatinina, pH o edad según la etiología) y de los de Clichy para indicar trasplante urgente. Por tanto, no es cierto que nunca influya, ni que solo cuente el coma de grado 4; el grado 2 aislado no es criterio de trasplante urgente. En la cirrosis, la prioridad en lista depende fundamentalmente del MELD."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439550") }, {"Justificacion": "La escala DAN (Douleur Aiguë du Nouveau-né), de Carbajal y colaboradores, valora el dolor agudo de procedimientos en recién nacidos a término y prematuros mediante tres componentes conductuales: respuesta facial (0-4), movimientos de los miembros (0-3) y expresión vocal (0-3), con un total de 0 a 10. En el neonato intubado la expresión vocal se valora mediante signos faciales de llanto. No incluye parámetros fisiológicos como la frecuencia cardíaca o la saturación, por lo que las opciones de cuatro o cinco componentes son incorrectas, y tampoco se limita a dos componentes facial y corporal, ya que la vocalización es un elemento propio de la escala."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439583") }, {"Justificacion": "Las escalas de Conners disponen de versiones para padres (síntomas en el hogar), para profesores (síntomas en el aula) y de autoinforme, tanto para adolescentes como para adultos (CAARS, a partir de 18 años). Existen formas largas y abreviadas, y la última revisión es la Conners 3. Comparar la información de padres y profesores es clave para el diagnóstico de TDAH, ya que los síntomas deben estar presentes en dos o más contextos según el DSM-5. Por ello son falsas las opciones que limitan la escala a padres, a la versión clínica Conners 3 o a profesores de niños menores de 8 años."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439593") }, {"Pregunta": "El Kansas City Cardiomyopathy Questionnaire (KCCQ) en la insuficiencia cardíaca. ¿Qué evalúa y cuántos ítems tiene?", "Respuesta_1": "23 ítems; evalúa exclusivamente la tolerancia al esfuerzo medida en la ergometría", "Justificacion": "El KCCQ (Green y colaboradores, 2000) es un cuestionario autoadministrado de 23 ítems específico de la insuficiencia cardíaca. Valora limitación física, síntomas (frecuencia, gravedad y estabilidad de disnea, fatiga y edemas), limitación social, autoeficacia y conocimiento, y calidad de vida, con puntuaciones de 0 a 100 en las que mayor puntuación indica mejor estado de salud. Un cambio de unos 5 puntos se considera clínicamente relevante. No es una prueba de esfuerzo, no reproduce la clase NYHA con 12 ítems y no se limita a la disnea, por lo que la única opción completa es la que recoge sus múltiples dominios."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439594") }, {"Justificacion": "En rehabilitación cardíaca, la intensidad de entrenamiento aeróbico moderada, en torno al 60-80% de la frecuencia cardíaca máxima, se corresponde con una percepción de esfuerzo de 4 a 6 en la escala de Borg modificada de 0 a 10 (algo intenso a intenso), equivalente a 12-15 en la escala original de 6 a 20. Es una zona segura y eficaz para pacientes tras infarto, revascularización o con insuficiencia cardíaca estable. Valores de 1 a 3 corresponden a esfuerzos muy ligeros o ligeros, insuficientes para el entrenamiento, mientras que 7-8 indican un esfuerzo muy intenso que no se recomienda sin supervisión específica."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395a6") }, {"Respuesta_2": "10 ítems (escala Likert 1-4, total 10-40); baja autoestima <25 puntos", "Justificacion": "La escala de Rosenberg consta de 10 ítems, cinco formulados en positivo y cinco en negativo, puntuados de 1 a 4 en escala Likert, con un total de 10 a 40 tras invertir los ítems negativos. La interpretación habitual en España es: 30-40 autoestima elevada, 26-29 autoestima media y menos de 25 autoestima baja. Es la escala de autoestima global más utilizada en salud y se aplica en enfermería comunitaria, escolar, de salud mental y oncológica. No tiene 20 ítems, no se puntúa de 0 a 3 por ítem y los umbrales de 15 o 20 puntos no corresponden a su interpretación."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395a8") }, {"Respuesta_1": "NEWS2 incorpora una escala alternativa de SpO2 (escala 2) para pacientes con insuficiencia respiratoria hipercápnica con objetivo de saturación 88-92%, y añade la confusión de nueva aparición al nivel de consciencia (ACVPU)", "Justificacion": "El NEWS2 (Royal College of Physicians, 2017) mantiene los siete parámetros del NEWS: frecuencia respiratoria, SpO2, uso de oxígeno suplementario, tensión arterial sistólica, frecuencia cardíaca, nivel de consciencia y temperatura. Sus novedades son una segunda escala de SpO2 para pacientes con insuficiencia respiratoria hipercápnica y objetivo de saturación del 88-92%, y la inclusión de la confusión de nueva aparición en el nivel de consciencia (ACVPU), que puntúa 3. No incluye temperatura rectal ni glucemia capilar, y no se restringe a la UCI: está diseñado para detectar el deterioro clínico en adultos hospitalizados y en la atención prehospitalaria."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395d7") }, {"Pregunta": "¿Cuál de los siguientes factores anatómicos perineales se asocia a MAYOR riesgo de desgarro perineal de grado III-IV durante el parto?", "Justificacion": "Una longitud corta del cuerpo perineal o de la distancia anogenital (en torno a menos de 2,5 cm) se asocia a mayor riesgo de lesión obstétrica del esfínter anal, porque el periné tiene menos tejido que distender antes de que la laceración alcance el esfínter; un tejido rígido o poco distensible aumenta también ese riesgo. Por el contrario, una distancia anogenital larga con tejido elástico es protectora. La multiparidad se asocia a menor riesgo que la nuliparidad, y la presentación en occipitoanterior es la más favorable; las variedades posteriores son las que aumentan el riesgo de desgarros graves.", "Fuente": "Deering SH et al. Perineal body length and lacerations at delivery. J Reprod Med. 2004;49(4):306-10; RCOG Green-top Guideline No. 29. 2015."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395db") }, {"Respuesta_2": "Mejor calidad de vida relacionada con el estreñimiento, ya que las respuestas próximas a \"nunca\" obtienen más puntos", "Respuesta_3": "Peor calidad de vida relacionada con el estreñimiento; indica intervención terapéutica urgente", "Justificacion": "En el CVE-20 cada uno de los 20 ítems se responde con cinco opciones puntuadas de 0 (siempre) a 4 (nunca), de modo que las respuestas cercanas a nunca reflejan menos preocupaciones y molestias. Por tanto, una puntuación total elevada indica mejor calidad de vida relacionada con el estreñimiento, no un mayor deterioro. El cuestionario no tiene puntos de corte de gravedad y se usa sobre todo para el seguimiento: un cambio de unos 17 puntos se considera clínicamente relevante. No valora el tránsito acelerado ni la diarrea, y no se limita a síntomas físicos, ya que incluye las dimensiones emocional y social."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439543") }, {"Pregunta": "La Escala de Oxford para la valoración de la fuerza de la musculatura del suelo pélvico. ¿Cuántos grados tiene y qué grado corresponde a una contracción débil, no sostenida y sin resistencia frente al dedo del examinador?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395de") }, {"Justificacion": "Aplicando la puntuación de Bishop: dilatación de 2 cm = 1 punto (1-2 cm), borramiento del 60% = 2 (60-70%), consistencia blanda = 2, posición anterior = 2 y presentación en plano 0 = 2, lo que suma 9 puntos. Una puntuación de 8 o más indica un cérvix favorable, con alta probabilidad de éxito de la inducción mediante oxitocina, sin necesidad de maduración cervical previa. Las opciones de 7 y 5 puntos son errores de cálculo, y un Bishop de 11 no se corresponde con esta exploración; además, un cérvix maduro no contraindica la amniorrexis, que de hecho suele asociarse a la oxitocina en la inducción."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439548") }, {"Respuesta_3": "7 tipos; tipo 1 = ideal", "Justificacion": "La escala de heces de Bristol describe siete tipos según su forma y consistencia: el tipo 1 son bolitas duras separadas y el tipo 2 una salchicha grumosa, ambos propios del estreñimiento; el tipo 3 es una salchicha con grietas en la superficie y el tipo 4 una salchicha lisa y blanda, que se consideran normales (el 4 es el ideal); el tipo 5 son trozos blandos de bordes definidos, el tipo 6 trozos pastosos de bordes irregulares y el tipo 7 heces líquidas, que indican tránsito acelerado o diarrea. No tiene cinco ni seis tipos, y el tipo 1 corresponde a estreñimiento, no a heces ideales."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439585") }, {"Respuesta_2": "6 subtipos: ansiedad de separación, fobia social, trastorno obsesivo-compulsivo, pánico/agorafobia, ansiedad generalizada y miedo al daño físico"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43958a") }, {"Respuesta_4": "ABPI >1,3", "Justificacion": "El índice tobillo-brazo se interpreta así: entre 0,9 y 1,3 es normal; entre 0,7 y 0,9 indica enfermedad arterial leve; entre 0,5 y 0,7, moderada; y por debajo de 0,5, isquemia grave o crítica, con alto riesgo de pérdida de la extremidad. Un valor inferior a 0,9 ya es diagnóstico de enfermedad arterial periférica, pero no de isquemia crítica, y un valor menor de 0,7 indica afectación moderada. Un índice superior a 1,3 sugiere arterias calcificadas no compresibles, frecuente en diabetes, y no es interpretable. En úlceras de pierna es imprescindible medirlo antes de aplicar terapia compresiva."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395b2") }, {"Pregunta": "La Escala de Wood-Downes original para la valoración de la crisis asmática en pediatría. ¿Qué parámetros evalúa?", "Respuesta_2": "Sibilancias, uso de musculatura accesoria (tiraje), entrada de aire, cianosis y nivel de consciencia", "Justificacion": "La escala de Wood-Downes original valora cinco parámetros clínicos: sibilancias, tiraje o uso de musculatura accesoria, entrada de aire, cianosis y nivel de consciencia, cada uno puntuado de 0 a 2. Permite estimar la gravedad de la crisis y la posible insuficiencia respiratoria en el niño. La modificación de Ferrés, muy utilizada en España, sustituye el nivel de consciencia por la frecuencia respiratoria y la frecuencia cardíaca. Ninguna versión se limita a la oximetría y la frecuencia respiratoria, ni a la saturación, cianosis y frecuencia cardíaca, y no reproduce sin más los ítems de la escala de Downes para el distrés neonatal."});
rm('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395dc") });
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e3") }, {"Respuesta_1": "30 ítems: 7 positivos, 7 negativos y 16 de psicopatología general; cada ítem puntúa de 1 a 7", "Justificacion": "La PANSS (Kay, Fiszbein y Opler, 1987) consta de 30 ítems: la subescala positiva tiene 7 ítems (delirios, alucinaciones, desorganización conceptual, etc.), la negativa 7 (embotamiento afectivo, retraimiento social, alogia, etc.) y la de psicopatología general 16. Cada ítem se puntúa de 1 (ausente) a 7 (extremo), por lo que el total oscila entre 30 y 210. Se desarrolló a partir de la BPRS. Las demás opciones son incorrectas: no tiene 20, 15 ni 40 ítems, no se puntúa de 0 a 4 o de 0 a 5 y sí incluye una subescala de psicopatología general."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439538") }, {"Pregunta": "La escala EHRA de síntomas de la fibrilación auricular (European Heart Rhythm Association). ¿Cuántos niveles tiene y qué diferencia el nivel EHRA 2a del 2b?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43956b") }, {"Respuesta_3": "50 ítems motores (33 de extremidad superior y 17 de extremidad inferior); extremidad superior máximo 66 puntos", "Justificacion": "La evaluación de Fugl-Meyer valora la recuperación sensitivomotora tras el ictus. Su componente motor tiene 50 ítems puntuados de 0 a 2: 33 de extremidad superior, con un máximo de 66 puntos, y 17 de extremidad inferior, con un máximo de 34, de modo que la puntuación motora total es 100. La escala completa añade equilibrio (14 puntos), sensibilidad (24) y movilidad articular pasiva y dolor (44 y 44), hasta 226 puntos. Por eso es falso que la extremidad superior tenga un máximo de 33 o de 50 puntos, y el componente motor no tiene 66 ni 100 ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439591") }, {"Pregunta": "La Escala de Miedo a la Hipoglucemia (HFS - Hypoglycemia Fear Survey). ¿Para qué se usa en el seguimiento del paciente diabético?", "Justificacion": "El Hypoglycemia Fear Survey (HFS-II) y su versión abreviada FH-15 evalúan el miedo a la hipoglucemia mediante una subescala de preocupación (temor a perder el control, a tener una hipoglucemia conduciendo o durmiendo) y otra de conductas (evitar el ejercicio o quedarse solo, comer de más o mantener glucemias altas como medida preventiva). Este miedo es una barrera importante para el buen control glucémico en personas con DM1 y DM2 insulinizadas. No mide la glucemia durante el episodio, no clasifica su gravedad, que se hace por niveles clínicos y analíticos, ni sirve para calcular la dosis de glucagón."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e1") }, {"Respuesta_2": "Apgar 2 — depresión grave; ventilación con presión positiva (VPP) inmediata; si tras 30 segundos de ventilación efectiva la FC es <60 lpm, iniciar masaje cardíaco"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439570") }, {"Pregunta": "¿Qué escala se utiliza para clasificar la capacidad de marcha funcional (grado de ayuda necesaria para deambular) en pacientes post-ictus o con lesión medular?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395d8") }, {"Respuesta_2": "Apneas (pausas respiratorias de más de 15 segundos), extremidades frías y livideces", "Justificacion": "La escala de Menten recoge ocho signos de situación de últimos días: nariz fría o pálida, extremidades frías, livideces, cianosis labial, estertores premortem, apneas de más de 15 segundos por minuto, oliguria (menos de 300 ml en 24 horas) y somnolencia de más de 15 horas al día. La presencia de cuatro o más criterios indica una alta probabilidad de fallecimiento en los días siguientes, lo que ayuda a adecuar los cuidados y preparar a la familia. La fiebre con escalofríos, la agitación con aumento del apetito o la hipertensión con bradicardia no forman parte de la escala ni son signos de agonía."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e2") }, {"Justificacion": "La puntuación total es la suma de las tres subescalas: 12 + 24 + 38 = 74. Como las subescalas positiva y negativa tienen el mismo número de ítems (7 cada una, rango 7-49), pueden compararse directamente: la negativa (24) duplica a la positiva (12), lo que indica predominio de síntomas negativos como embotamiento afectivo, retraimiento social, apatía o alogia. Un total en torno a 75 equivale aproximadamente a una enfermedad moderada. Por ello el plan de cuidados debe centrarse en la activación, el autocuidado, las habilidades sociales y la rehabilitación funcional. No hay predominio positivo, la suma no es 50 y sí existe un predominio claro."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43952f") }, {"Respuesta_1": "PA ≥40 puntos indica baja realización personal", "Respuesta_2": "PA ≤33 puntos indica baja realización personal, ya que en esta subescala la dirección está invertida: a menor puntuación, mayor componente de burnout", "Justificacion": "En el MBI-HSS la subescala de realización personal (8 ítems, 0-48 puntos) tiene una dirección inversa a las otras dos: cuanto menor es la puntuación, mayor es el componente de burnout. Con los puntos de corte habituales en España, una puntuación ≤33 indica baja realización personal, mientras que el agotamiento emocional se considera alto con ≥27 y la despersonalización con ≥10. Por ello es incorrecto interpretar puntuaciones altas, como 40 o más, como baja realización, decir que la escala no está invertida o fijar el umbral en menos de 20 puntos. Esta inversión es una fuente frecuente de errores en la interpretación."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439546") }, {"Justificacion": "El Incontinence Severity Index de Sandvik consta de solo dos preguntas: frecuencia de las pérdidas (1-4) y cantidad (1-3). Su producto, de 1 a 12, clasifica la gravedad en cuatro categorías: leve (1-2), moderada (3-6), grave (8-9) y muy grave (12). Su brevedad lo hace muy útil en epidemiología, cribado y seguimiento, y es comparable a la medición con compresas. No clasifica el tipo de incontinencia (esfuerzo, urgencia o mixta), no tiene 20 ítems de calidad de vida y no es una versión antigua del ICIQ-SF, que incluye además el impacto en la calidad de vida."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439561") }, {"Respuesta_1": "30 ítems; 3 escalas funcionales, 5 escalas de síntomas y 1 escala global", "Justificacion": "El EORTC QLQ-C30 (versión 3.0) tiene 30 ítems: cinco escalas funcionales (física, de rol, cognitiva, emocional y social), tres escalas de síntomas (fatiga, náuseas y vómitos, y dolor), seis ítems individuales (disnea, insomnio, pérdida de apetito, estreñimiento, diarrea y dificultades económicas) y dos ítems de estado de salud y calidad de vida global, puntuados de 1 a 7. Todas las puntuaciones se transforman a 0-100. Es el instrumento de calidad de vida más usado en oncología. No tiene tres escalas funcionales y cinco de síntomas, no produce una única puntuación global y no tiene 60 ítems."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e439569") }, {"Justificacion": "En personas mayores, un IMC bajo se asocia a peor pronóstico con valores más altos que en adultos jóvenes, por la pérdida de masa muscular y los cambios de composición corporal ligados a la edad. Por ello muchos protocolos geriátricos y los criterios GLIM consideran bajo peso un IMC inferior a 22 kg/m² a partir de los 70 años, frente al 18,5 de la clasificación general del adulto. El MNA también puntúa como riesgo los valores inferiores a 23. Un IMC de 25 marca el límite superior de la normalidad, y el umbral de 20 se aplica en GLIM a adultos menores de 70 años."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43959f") }, {"Justificacion": "En la artritis reumatoide la escala visual analógica se usa para valorar varias dimensiones: el dolor, la actividad global de la enfermedad percibida por el paciente, la fatiga y, en algunos protocolos, la rigidez matutina; el médico también registra su propia valoración global. La valoración global del paciente forma parte del DAS28, y el dolor y las valoraciones globales del paciente y del médico se incluyen en los criterios de respuesta del ACR. La fatiga, aunque no entre en esos índices, es muy incapacitante y suele infravalorarse. Por tanto, la EVA no se limita al dolor ni a la actividad global, y es ampliamente utilizada en reumatología."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395ac") }, {"Pregunta": "El Fenotipo de Fragilidad de Fried. ¿Cuántos criterios tiene y cuántos son necesarios para el diagnóstico de fragilidad?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395b0") }, {"Respuesta_1": "≥4 cm se considera normal y predice intubación fácil"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395dd") }, {"Respuesta_2": "Paridad, duración del trabajo de parto, duración de las contracciones, intervalo entre contracciones y estado de la bolsa amniótica", "Justificacion": "La puntuación de Malinas se diseñó para estimar el tiempo que queda hasta el nacimiento y decidir si es posible trasladar a la gestante. Valora cinco variables, cada una de 0 a 2 puntos: paridad, duración del trabajo de parto, duración de las contracciones, intervalo entre contracciones y rotura de la bolsa amniótica. Las puntuaciones altas indican un parto próximo. No incluye la exploración cervical, por lo que la dilatación y el índice de Bishop no forman parte de ella. Tampoco valora la frecuencia cardíaca o el pH fetal, ni constantes maternas como tensión arterial, temperatura, frecuencia respiratoria o saturación."});
rm('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e6") });
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43953a") }, {"Pregunta": "El Test Conductual de Memoria de Rivermead (RBMT - Rivermead Behavioural Memory Test). ¿Qué tipo de memoria evalúa y en qué se diferencia de las escalas de memoria estándar?"});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43956c") }, {"Pregunta": "La Escala de Equilibrio de Berg. ¿Cuántos ítems tiene y por debajo de qué puntuación se considera clásicamente que aumenta el riesgo de caídas?", "Respuesta_Correcta": "B", "Justificacion": "La escala de Berg consta de 14 ítems que valoran el equilibrio estático y dinámico en tareas funcionales como levantarse, transferirse, girar o mantenerse sobre un pie, puntuados de 0 a 4, con un máximo de 56. Una puntuación inferior a 45 es el punto de corte clásico de Berg para identificar un riesgo aumentado de caídas en personas mayores. En la interpretación habitual, 41-56 indica bajo riesgo, 21-40 riesgo moderado con marcha asistida y 0-20 alto riesgo con necesidad de silla de ruedas. La escala no tiene 20 ítems, y los valores de 40 o 30 corresponden a grados de afectación mayores, no al umbral clásico."});
rm('preguntas_escalas', { _id: ObjectId("6a031569a955de751e43957b") });
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395c6") }, {"Pregunta": "La Escala Expandida del Estado de Discapacidad de Kurtzke (EDSS) en la esclerosis múltiple. ¿Cómo se puntúa y desde qué nivel indica dependencia de silla de ruedas?", "Respuesta_2": "De 0 a 10 en intervalos de 0,5; silla de ruedas desde EDSS 5", "Respuesta_3": "De 0 a 10 en intervalos de 0,5; necesidad de silla de ruedas desde EDSS 7 (incapaz de caminar más de 5 metros incluso con ayuda)", "Justificacion": "La EDSS de Kurtzke puntúa la discapacidad en la esclerosis múltiple de 0 (exploración normal) a 10 (muerte por la enfermedad) en intervalos de 0,5 a partir de 1. Hasta 4,5 el paciente camina sin ayuda; en 5-5,5 la distancia de marcha sin ayuda se reduce; en 6 necesita ayuda unilateral y en 6,5 bilateral; en 7 es incapaz de caminar más de 5 metros incluso con ayuda y depende de la silla de ruedas, aunque se traslada solo; de 8 en adelante queda limitado a la cama o la silla. Por tanto, la dependencia de silla de ruedas se inicia en 7, no en 4, 5 ni 6."});
fix('preguntas_escalas', { _id: ObjectId("6a031569a955de751e4395e8") }, {"Respuesta_2": "Bishop 4 — contraindicación absoluta de inducción", "Respuesta_3": "Bishop 0 — cérvix muy desfavorable; maduración cervical con misoprostol vaginal (25 mcg cada 4-6 h) o dinoprostona como paso previo a la oxitocina", "Justificacion": "Con la puntuación de Bishop: dilatación 0 cm = 0, borramiento 0-30% = 0, consistencia dura = 0, posición posterior = 0 y altura de la presentación en -3 = 0, lo que suma 0 puntos. Un Bishop bajo (≤6 en la mayoría de protocolos) indica cérvix desfavorable, por lo que, si está indicada la inducción, debe realizarse antes maduración cervical con prostaglandinas (misoprostol vaginal 25 mcg cada 4-6 horas o dinoprostona) o métodos mecánicos como la sonda de Foley, y después oxitocina si es necesaria. Un Bishop bajo no contraindica la inducción, y no estaría indicado iniciar directamente oxitocina ni hacer amniorrexis con este cérvix."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064f") }, {"question": "¿Cómo se llama la cánula que aparece en la imagen?:", "option_1": "Cánula de Guedel.", "option_2": "Cánula de Berman.", "option_3": "Cánula nasofaríngea de Wendl.", "option_4": "Mascarilla laríngea.", "answer": 2, "long_answer": "La imagen muestra varias cánulas orofaríngeas de colores (distintos tamaños) cuyo cuerpo no es un tubo cerrado sino una pieza plana con canales laterales abiertos y perforaciones, rasgo característico de la cánula de Berman. Su función, como la de cualquier cánula orofaríngea, es evitar que la lengua obstruya la vía aérea en el paciente inconsciente, y su diseño abierto permite además el paso de una sonda de aspiración o guiar una intubación. La cánula de Guedel es tubular, con una luz central cerrada y bloque de mordida reforzado. La cánula de Wendl es nasofaríngea, blanda y con forma de tubo recto, y la mascarilla laríngea es un dispositivo supraglótico con un manguito hinchable, nada parecido a lo que se ve."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400650") }, {"option_3": "Tejido cartilaginoso hialino.", "long_answer": "La imagen histológica muestra células grandes, poligonales y de aspecto vacío (ópticamente claras), separadas por finos tabiques y con el núcleo aplanado y desplazado a la periferia, lo que da el típico aspecto en «anillo de sello». Son adipocitos uniloculares cuya gota lipídica se ha disuelto al procesar la muestra, por lo que se trata de tejido adiposo blanco. El músculo liso mostraría células fusiformes con núcleo central alargado, el músculo estriado fibras largas con estriaciones transversales y núcleos periféricos múltiples, y el cartílago hialino condrocitos alojados en lagunas dentro de una matriz homogénea, imágenes que no corresponden con la mostrada."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400653") }, {"option_1": "Aspirar secreciones de la vía aérea.", "option_2": "Realizar lavados óticos.", "option_3": "Administrar oxígeno.", "option_4": "Instilar medicación tópica en la herida quirúrgica.", "answer": 1, "long_answer": "La imagen muestra un aspirador manual portátil de secreciones: un mango tipo pistola con gatillo que, al accionarlo repetidamente, genera presión negativa, conectado a un recipiente colector y a una cánula o sonda rígida de aspiración. Se utiliza para aspirar secreciones, sangre o vómito de la vía aérea en situaciones de emergencia o transporte, donde no se dispone de vacío de pared. No sirve para administrar oxígeno, que requiere una fuente de gas y dispositivos como gafas nasales o mascarillas, ni para realizar lavados óticos, que se hacen con jeringa o irrigador, ni para instilar medicación sobre una herida."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400657") }, {"long_answer": "En la imagen se observa la cara fetal de la placenta con el cordón umbilical insertado fuera del disco placentario, sobre las membranas, desde donde los vasos umbilicales discurren desnudos, sin la protección de la gelatina de Wharton, hasta alcanzar la placa corial. Esto define la inserción velamentosa del cordón, que aumenta el riesgo de vasa previa, rotura vascular y hemorragia fetal. La placenta acreta es una adherencia anómala al miometrio que no se aprecia examinando la placenta, la placenta previa se define por su localización sobre el orificio cervical interno y la placenta bilobulada presenta dos lóbulos separados, hallazgos que no se ven aquí."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400658") }, {"long_answer": "La imagen muestra la ventilación con bolsa autoinflable y mascarilla facial en un recién nacido. La afirmación incorrecta es colocar la cabeza en hiperextensión: en el neonato, por su occipucio prominente, la cabeza debe quedar en posición neutra (posición de olfateo), ya que la hiperextensión o la flexión colapsan la vía aérea. El reanimador se sitúa a la cabeza del recién nacido, la mascarilla debe cubrir boca y nariz sin sobrepasar el mentón ni comprimir los ojos, y la frecuencia de ventilación recomendada es de 30 a 60 respiraciones por minuto, por lo que el resto de opciones son correctas."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400659") }, {"long_answer": "La imagen muestra una mesa de instrumental quirúrgico y el montaje de la hoja de bisturí con ayuda de un instrumento, no con los dedos. Es correcto que el instrumental se ordene habitualmente de izquierda a derecha según el orden previsto de uso durante la intervención, lo que agiliza la instrumentación. La hoja del bisturí debe montarse y retirarse siempre con un portaagujas o pinza, nunca con los dedos, para evitar cortes. Un cobertor mojado se considera contaminado, porque la humedad permite el paso de microorganismos por capilaridad, y los bordes de la mesa no se consideran estériles, por lo que nada debe colocarse en ellos ni sobresalir."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065a") }, {"subject": "INVESTIGACIÓN", "long_answer": "La imagen es un diagrama de caja y bigotes. La opción incorrecta es la que asigna la línea azul a la media: la línea situada dentro de la caja representa la mediana (percentil 50), ya que este gráfico se construye con medidas de posición y no muestra la media. El borde superior de la caja (línea roja) corresponde al tercer cuartil o Q3 y el borde inferior (línea rosa) al primer cuartil o Q1, de modo que la altura de la caja es el rango intercuartílico. El círculo señalado con la flecha, situado más allá del bigote superior, representa un valor atípico o extremo de la variable estudiada."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065b") }, {"subject": "ENFERMERÍA FAMILIAR Y COMUNITARIA", "long_answer": "La imagen representa a una familia rodeada por un círculo que delimita el núcleo familiar, desde el que salen líneas hacia círculos externos (amigos, vecindario, familia extensa, religión, trabajo, salud). El tipo de línea indica la naturaleza de cada vínculo: líneas múltiples para relaciones fuertes, línea simple para relaciones débiles y líneas cortadas para relaciones conflictivas o estresantes. Esto corresponde al ecomapa, que muestra las relaciones de la familia con sus sistemas externos y sus recursos. El genograma se limita a la estructura familiar intergeneracional, el Apgar familiar es un cuestionario de percepción de la función familiar y la ficha familiar es un registro de datos."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400663") }, {"long_answer": "La imagen muestra una figura humana en posición anatómica atravesada por tres planos. La flecha señala el plano vertical que discurre en sentido anteroposterior y divide el cuerpo en una mitad derecha y otra izquierda, es decir, el plano sagital. El plano transversal es el horizontal, que separa una parte superior de otra inferior, y no es el señalado. Las opciones de eje latero-lateral y eje craneocaudal no son planos sino líneas imaginarias alrededor de las cuales se producen los movimientos, por lo que no responden a lo que se pregunta."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400664") }, {"long_answer": "En la imagen se ve una placenta ya alumbrada sobre un campo y unas manos enguantadas extrayendo sangre con una jeringa de un segmento del cordón umbilical. Esta técnica corresponde a la toma de muestra para gasometría y determinación del pH de sangre de cordón (arterial y venosa), que se realiza tras pinzar doblemente un segmento para valorar el estado ácido-base del recién nacido en el momento del parto. La donación de sangre de cordón se recoge en bolsa específica con sistema cerrado, la glucemia capilar se obtiene por punción del talón del neonato y la biopsia corial se realiza durante la gestación, no sobre la placenta alumbrada."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400666") }, {"option_1": "En las teorías y la práctica de este modelo se buscan soluciones positivas basadas en la capacidad, la habilidad y el talento de los individuos, las familias y las comunidades, que fortalezcan su autoestima para resolver los retos del entorno.", "long_answer": "La pirámide de la imagen sitúa en la base el problema, por encima el recurso profesional y en el vértice el hospital y la dependencia. Representa el modelo del déficit, centrado en identificar problemas y necesidades de la población para que sean resueltos por los profesionales y los servicios, lo que genera dependencia de los recursos sanitarios. Las opciones que hablan de capacidades, habilidades, talento y recursos de individuos y comunidades describen el modelo de activos en salud, que es justamente el contrapuesto, vinculado a la salutogénesis de Antonovsky y desarrollado por autores como Morgan y Ziglio, no por Dubos en 1959."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400673") }, {"long_answer": "La imagen muestra la salida de la cabeza fetal en el expulsivo con la cara visible: se distinguen nariz, boca y mentón, y la mano de la matrona sostiene el mentón, que queda orientado hacia delante bajo la sínfisis. Se trata de una presentación de cara en variedad mento-anterior o mentopúbica, la única presentación de cara que permite un parto vaginal, ya que el mentón se apoya bajo el pubis y la cabeza se desprende por flexión. La mento-posterior o sacra no progresa por vía vaginal a término. Las presentaciones de frente se refieren a la deflexión intermedia y no se describen con la nomenclatura occipito anterior o posterior, propia de la presentación de vértice."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400675") }, {"long_answer": "La espirometría basal muestra un cociente FEV1/FVC de 68,73 %, inferior a 70 %, con FEV1 del 81 % del teórico, lo que indica una obstrucción leve. Tras 400 µg de salbutamol el FEV1 aumenta 530 ml y un 26 %, superando ampliamente los criterios de 200 ml y 12 %, por lo que la prueba broncodilatadora es positiva y la obstrucción es reversible. Además, el FEV1/FVC posbroncodilatación sube a 75,76 %, normalizándose. Por ello la opción incorrecta es la que afirma compatibilidad con EPOC, ya que su diagnóstico exige un FEV1/FVC posbroncodilatador inferior a 0,7 y una obstrucción no totalmente reversible; el patrón orienta más a asma."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400676") }, {"subject": "GINECOLOGIA-OBSTETRICIA", "long_answer": "La imagen muestra un dispositivo de un solo uso formado por una empuñadura con bomba manual de vacío integrada y un indicador de presión con zonas de colores (verde, amarilla y roja), conectada mediante un tubo flexible a una copa de succión. Corresponde a la ventosa obstétrica tipo Kiwi, utilizada para el parto instrumental: la copa se aplica sobre el punto de flexión de la cabeza fetal y la tracción se acompaña de la contracción. No es un sistema de hemostasia en cavidades, ni la unidad de terapia de presión negativa para heridas, que lleva apósito de espuma, tubuladura y un aparato con contenedor, ni una ventosa terapéutica muscular."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067a") }, {"long_answer": "La curva de presión de la vía aérea muestra ondas cuadradas, con una presión inspiratoria que se alcanza rápidamente y se mantiene constante en meseta, mientras que la curva de flujo inspiratorio es decelerada, con un pico inicial que desciende progresivamente. Este patrón es característico de una modalidad controlada por presión. En la ventilación por volumen el flujo suele ser constante (onda cuadrada) y la presión ascendente. No se observan deflexiones negativas previas a cada ciclo que indiquen esfuerzo del paciente para activar el trigger, el flujo es decelerado y no acelerado, y la presencia de secreciones produciría oscilaciones en dientes de sierra en las curvas, que aquí no aparecen."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067d") }, {"subject": "MÉDICO-QUIRÚRGICA", "long_answer": "En la imagen, A y B señalan los pulmones, C el hígado y D el estómago. La percusión produce matidez sobre órganos macizos o sin aire, como el hígado, por lo que el punto C, en el hipocondrio derecho, es donde se espera un sonido mate. Sobre el parénquima pulmonar normal (A y B), lleno de aire, se obtiene un sonido resonante o claro pulmonar, y sobre el estómago (D), víscera hueca con gas, el sonido característico es timpánico, como ocurre en el espacio semilunar de Traube."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067e") }, {"subject": "CARDIOLOGÍA", "long_answer": "El trazado muestra un ritmo de base sinusal en el que aparecen latidos adelantados con complejo QRS estrecho, de morfología similar a los sinusales y precedidos de una onda P de distinta morfología, seguidos de una pausa. Esto corresponde a contracciones auriculares prematuras o extrasístoles auriculares. Además, el pulso detectado por pulsioximetría es inferior a la frecuencia del ECG porque algunos latidos prematuros apenas generan onda de pulso. La extrasístole ventricular tendría un QRS ancho y aberrante sin P previa, el bloqueo auriculoventricular de primer grado solo alarga el PR de forma constante sin latidos prematuros, y la fibrilación auricular presenta ausencia de ondas P y un ritmo irregularmente irregular."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400684") }, {"subject": "MÉDICO-QUIRÚRGICA", "long_answer": "La imagen muestra una gastrectomía parcial distal en la que el muñón gástrico remanente se anastomosa directamente con el duodeno, que mantiene su trayecto natural hacia el intestino. Esta reconstrucción gastroduodenal término-terminal corresponde a la técnica de Billroth I. En la Billroth II el duodeno se cierra y el estómago se une a un asa de yeyuno (gastroyeyunostomía), en la Y de Roux se anastomosa el estómago a un asa yeyunal desfuncionalizada en forma de Y, y la manga gástrica consiste en resecar longitudinalmente la curvatura mayor dejando un estómago tubular sin anastomosis intestinal."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400685") }, {"subject": "TÉCNICAS DE ENFERMERÍA", "long_answer": "En la imagen se ven dos puntos con el nudo situado a un lado de la incisión, mientras que en el lado contrario solo se aprecia un pequeño segmento de hilo dispuesto en paralelo a la herida, que corresponde a la doble pasada de cada punto. Este patrón es el del punto colchonero horizontal, en el que la aguja atraviesa ambos bordes, avanza paralela a la herida y vuelve a cruzar en sentido contrario, favoreciendo la eversión de los bordes. El colchonero vertical tiene sus cuatro pasos alineados perpendiculares a la herida, el punto simple muestra solo una entrada y una salida a cada lado y el continuo bloqueante es una sutura de un único hilo sin nudos individuales."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064b") }, {"long_answer": "La imagen muestra el signo de Trousseau: tras inflar el manguito del esfigmomanómetro unos 20 mmHg por encima de la presión sistólica durante 2-3 minutos, aparece un espasmo carpopedal con flexión de la muñeca y de las articulaciones metacarpofalángicas y extensión de los dedos (mano de comadrón). Este signo indica hipocalcemia, es decir, un calcio sérico total inferior a 2,15 mmol/L (aproximadamente 8,6 mg/dl). Las opciones que hablan de calcio superior a 2,15 o a 2,75 mmol/L describirían normo o hipercalcemia, que no produce tetania, y la cifra de 1,10 mmol/L corresponde al límite del calcio iónico, no del total, además de indicar 40 mmHg."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064e") }, {"long_answer": "La imagen muestra a la exploradora con ambas manos colocadas sobre el fondo uterino, rodeándolo con las palmas y los dedos, lo que corresponde a la primera maniobra de Leopold. Su objetivo es identificar qué polo fetal ocupa el fondo (habitualmente las nalgas, blandas e irregulares) y determinar así la situación y la presentación. La segunda maniobra se realiza con las manos a ambos lados del abdomen para localizar el dorso fetal; la tercera (maniobra de Pawlik) palpa el polo inferior sobre la sínfisis con una sola mano, y la cuarta se realiza mirando hacia los pies de la gestante, con ambas manos dirigidas hacia la pelvis para valorar el grado de encajamiento."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400651") }, {"answer": 2, "long_answer": "En la ecografía 1 se observan las estructuras anecoicas A y B (y C, compatible con nervio). Al ejercer presión con la sonda, en la ecografía 2 solo persiste la cavidad B: la estructura A ha desaparecido porque se ha colapsado. La compresibilidad es el signo ecográfico básico para diferenciar vasos: las venas, de pared fina y baja presión, se colapsan con facilidad, mientras que las arterias, de pared gruesa, muscular y con flujo a presión y pulsátil, no se comprimen. Por tanto, A es una vena y B una arteria. Las demás combinaciones no se ajustan a lo observado, ya que si B fuera vena también se habría colapsado al presionar sobre su trayecto."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400652") }, {"option_2": "También se conoce como reflejo del esgrimista.", "option_3": "Habitualmente desaparece hacia los 4-6 meses de vida.", "option_4": "Su persistencia más allá del primer año de vida se considera un hallazgo normal.", "answer": 4, "long_answer": "La afirmación incorrecta es que su persistencia más allá del año sea normal: la persistencia del reflejo tónico cervical asimétrico pasados los 6 meses es un signo de alarma de lesión neurológica, como la parálisis cerebral. La imagen muestra a un lactante en supino con la cabeza girada hacia un lado, el brazo de ese lado extendido y el contralateral flexionado, la postura típica del esgrimista. Es cierto que se presenta en el recién nacido al rotar la cabeza en supino con extensión de las extremidades del lado facial, que se conoce como reflejo del esgrimista y que desaparece hacia los 4-6 meses, al madurar el control cortical."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400656") }, {"long_answer": "La imagen muestra a la madre sentada con el bebé colocado bajo su brazo, a un lado de su cuerpo, con las piernas del lactante dirigidas hacia atrás y apoyado sobre una almohada, mientras ella sujeta la cabeza y la espalda con la mano. Es la posición de balón de rugby (o en pelota de fútbol americano), útil tras una cesárea, con mamas grandes, gemelos o prematuros. En el acunado clásico el bebé está en el regazo, tumbado de lado y con su abdomen contra el de la madre; en la posición de caballito el lactante se sienta a horcajadas sobre el muslo materno, y en la reclinada la madre está recostada con el bebé sobre su pecho."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066e") }, {"long_answer": "La figura 4 muestra el montaje correcto: la aguja se sujeta con la punta del portaagujas, perpendicular a sus ramas y en la unión del tercio posterior con los dos tercios anteriores, cerca de la zona de engarce del hilo pero sin pinzarla. Así se consigue estabilidad, se evita que la aguja gire o se doble y se protege el engarce, que es la parte más frágil. En la figura 1 la aguja está pinzada casi por su extremo y en paralelo al instrumento; en la figura 2 queda sujeta de forma inestable y en la figura 3 se pinza por la mitad de la curvatura, lo que facilita que se deforme o rote al atravesar los tejidos."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066f") }, {"long_answer": "La imagen muestra un recipiente rígido y transparente que contiene en su interior un balón o reservorio elástico, del que sale un sistema de infusión con pinza y conexión luer. Es una bomba elastomérica: un dispositivo desechable y no eléctrico que administra la medicación (analgesia, quimioterapia, antibióticos) a flujo continuo gracias a la presión que ejerce la membrana elástica al contraerse, con un regulador de flujo fijo. No es un drenaje: el redón es un sistema de vacío con tubo multiperforado y frasco con fuelle o indicador de vacío, y el Jackson-Pratt tiene una pera de silicona compresible. La bomba volumétrica es un aparato electrónico programable que necesita conexión eléctrica o batería."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400671") }, {"long_answer": "El esquema muestra el ventrículo izquierdo dilatado, con una flecha gruesa que entra en él desde la raíz aórtica a través de una válvula aórtica que no cierra, además del flujo normal procedente de la aurícula izquierda a través de la mitral. Este reflujo diastólico desde la aorta al ventrículo define la insuficiencia aórtica, que produce sobrecarga de volumen, dilatación e hipertrofia excéntrica del ventrículo izquierdo. En la estenosis mitral la alteración estaría en la válvula mitral, con aurícula izquierda dilatada y dificultad de llenado ventricular; la pericarditis afectaría a la envoltura pericárdica, y la isquemia aguda no se representaría como un flujo regurgitante desde la aorta."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067c") }, {"subject": "TÉCNICAS DE ENFERMERÍA", "long_answer": "En la imagen Doppler se ven dos vasos, uno codificado en azul y otro en rojo. El color depende de la dirección del flujo respecto al transductor; con la sonda orientada en sentido caudocraneal, el flujo venoso de retorno hacia el corazón se dirige hacia la sonda y se codifica en rojo, mientras que el flujo arterial, que se aleja hacia la periferia, aparece en azul. Por tanto, el vaso rojo es la vena a canalizar. En la segunda imagen la vena mide 0,44 cm. La relación catéter-vena recomendada en el PICC es de 1/3 del diámetro venoso, es decir, unos 1,4-1,5 mm, y como 1 Fr equivale a 0,33 mm, el calibre máximo es 4 Fr. Las opciones con 5 o 6 Fr superan esa relación, y ningún vaso con flujo Doppler puede ser un nervio."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067f") }, {"subject": "MÉDICO-QUIRÚRGICA", "long_answer": "La imagen muestra una herida quirúrgica abdominal lineal cuyos bordes se han separado, dejando a la vista el tejido subcutáneo y el lecho de la herida, con las marcas de las grapas o puntos retirados a ambos lados. Esta apertura de la incisión tras el cierre primario es una dehiscencia, que puede ser superficial o afectar a planos profundos. El seroma es una acumulación de líquido seroso bajo una herida que permanece cerrada, y se ve como una tumefacción fluctuante. El queloide y la cicatriz hipertrófica son alteraciones de la cicatrización por exceso de colágeno que aparecen sobre una herida ya cerrada; el queloide sobrepasa los límites de la incisión y la hipertrófica no."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400683") }, {"subject": "GINECOLOGIA-OBSTETRICIA", "long_answer": "La imagen muestra un feto en presentación podálica con las nalgas encajadas en la pelvis, las caderas flexionadas y las rodillas extendidas, de modo que los pies quedan a la altura de la cabeza. Esta es la presentación de nalgas puras o francas, la más frecuente de las podálicas. En las nalgas completas el feto tiene las caderas y las rodillas flexionadas, en posición de sastre, y los pies se palpan junto a las nalgas. En las nalgas incompletas uno o ambos pies o rodillas se presentan por debajo de las nalgas (variedades de pies o de rodillas). La denominación «nalgas complejas» no es una variedad de la clasificación de la presentación podálica."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064c") }, {"option_2": "Cuantitativa discreta.", "option_4": "Dos variables cuantitativas relacionadas entre sí.", "long_answer": "La imagen es un diagrama de sectores (gráfico de tarta), en el que cada sector representa la proporción de una categoría, en este caso cada trimestre, sobre el total. Este gráfico se utiliza para variables cualitativas, sobre todo nominales, ya que solo muestra frecuencias relativas de categorías y no un orden ni una magnitud numérica. Las variables cuantitativas continuas se representan con histogramas o polígonos de frecuencias, y las cuantitativas discretas con diagramas de barras. Para mostrar la relación entre dos variables cuantitativas se emplea el diagrama de dispersión o nube de puntos, nunca un diagrama de sectores."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065d") }, {"long_answer": "El trazado muestra ciclos en los que la inspiración asciende hasta una meseta prolongada, ya que el paciente mantiene el aire en inspiración máxima, seguida de una espiración y una pausa espiratoria. Esta inspiración prolongada con pausa al final es la respiración apnéustica, típica de lesiones protuberanciales. La respiración atáxica, o de Biot, es completamente irregular en ritmo y profundidad, con pausas de apnea impredecibles. La de Kussmaul consiste en respiraciones profundas, rápidas y regulares, propias de la acidosis metabólica. La de Cheyne-Stokes alterna ciclos de amplitud creciente y decreciente con periodos de apnea, en patrón de crescendo-decrescendo."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065f") }, {"long_answer": "En la imagen se ven cinco electrodos: uno en la parte alta del esternón (amarillo, S), otro en el extremo inferior del esternón a nivel del quinto espacio intercostal (blanco, E), dos en la línea medioaxilar derecha e izquierda a la misma altura (rojo, I, y verde, A) y uno de tierra en el abdomen (negro). Esta disposición corresponde al sistema EASI, que permite derivar un ECG de 12 derivaciones con solo cinco electrodos. MCL-1 es una derivación torácica modificada con tres electrodos, la derivación de Lewis coloca los electrodos sobre el esternón para ver mejor la onda P, y Mason-Likar lleva los electrodos de los miembros al tronco, junto a las seis precordiales."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400660") }, {"long_answer": "La imagen muestra el cordón umbilical seccionado y sujeto con una cinta en su base, con sus tres vasos y un catéter introducido en uno de ellos: es la canalización de vasos umbilicales. La vena umbilical es la vía de elección para administrar fármacos y fluidos durante la reanimación neonatal en sala de partos, por su accesibilidad y su rapidez. Es falso que haya dos venas y una arteria, porque el cordón normal contiene dos arterias y una vena. La arteria umbilical se reserva para la monitorización de la presión arterial y las extracciones de gasometría, no para administrar medicación ni hemoderivados. La vena puede canalizarse incluso pasadas las primeras 24 horas de vida, durante los primeros días."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400661") }, {"long_answer": "El diagrama de Venn muestra dos conjuntos con solo la zona de intersección sombreada, es decir, los registros que contienen a la vez ambos términos de búsqueda. Esto corresponde al operador booleano AND, que restringe la búsqueda y aumenta su especificidad. El operador OR sombrearía la superficie completa de ambos círculos, ya que recupera los documentos que contienen cualquiera de los términos (suma de conjuntos), y se usa para sinónimos. NOT sombrearía uno de los círculos excluyendo la intersección, al eliminar los registros que contienen el segundo término. El asterisco no es un operador booleano, sino un truncamiento que recupera las variantes de una raíz."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400669") }, {"long_answer": "La fotografía 1 muestra el lavado quirúrgico correcto: las manos se mantienen elevadas por encima del nivel de los codos mientras se frotan el antebrazo y el codo, de manera que el agua y el jabón escurran desde la zona más limpia (las manos) hacia la menos limpia (los codos) y no vuelvan a contaminar las manos. En las demás fotografías se aprecian errores, como mantener las manos horizontales o por debajo del codo, manipular de forma incorrecta el dispensador o el cepillo, o realizar un aclarado que permite que el agua retorne desde el antebrazo hacia los dedos, lo que compromete la asepsia del procedimiento."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066a") }, {"long_answer": "La imagen muestra un anzuelo con muerte o lengüeta (barba) introducido bajo la piel, con la punta y la barba alojadas en el tejido subcutáneo. Al tener la barba, no puede extraerse tirando hacia atrás sin desgarrar el tejido. La técnica tradicional, de empuje y corte, consiste en anestesiar la zona, hacer avanzar el anzuelo siguiendo su curvatura hasta que la punta y la barba salgan por la piel, cortar la barba y retirar el anzuelo en sentido inverso a su entrada. La tracción perpendicular o la rotación con tracción no liberan la barba y provocan más daño, y doblar el ojal no permite atravesar el trayecto con seguridad."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400674") }, {"long_answer": "La imagen muestra un vendaje de emergencia tipo israelí, con una almohadilla de gasa y un aplicador o barra de presión de plástico. Para usarlo, se coloca la almohadilla sobre la herida y se da una vuelta; en la segunda vuelta se pasa la venda por dentro del aplicador, se invierte el sentido del giro y se continúa enrollando con presión firme sobre la herida en las vueltas restantes, lo que permite comprimir el foco hemorrágico. Es falso que no pueda aplicarse sobre articulaciones, y es una cobertura inicial indicada en heridas por arma de fuego. Colocarlo lo más alto posible dejando espacio para un segundo dispositivo es una recomendación propia del torniquete, no de este vendaje."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400678") }, {"long_answer": "La radiografía anteroposterior de fémur derecho muestra una línea de fractura transversal en el tercio medio-proximal del hueso, con desplazamiento y cabalgamiento de los fragmentos, situada en la porción tubular central del hueso largo. Esta localización corresponde a la diáfisis, por lo que es una fractura diafisaria de fémur. Las fracturas metafisarias afectan a la zona ensanchada de transición próxima a los extremos (proximal o supracondílea), las epifisarias a los extremos articulares (cabeza, cuello o cóndilos), y las fisarias al cartílago de crecimiento, que solo existe en niños y adolescentes y no se ve en la imagen."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400679") }, {"option_2": "IIIB.", "long_answer": "La imagen muestra una pierna con una herida lacerada de varios centímetros en la cara anterior, sin gran pérdida de partes blandas, sin exposición ósea extensa, sin contaminación masiva ni lesión vascular aparente. Según la clasificación de Gustilo-Anderson, corresponde a una fractura abierta tipo II: herida de entre 1 y 10 cm con daño moderado de partes blandas. El tipo I tiene una herida menor de 1 cm y limpia. El tipo IIIA presenta un daño extenso de partes blandas o un traumatismo de alta energía, aunque con cobertura ósea adecuada, y el IIIB añade pérdida de partes blandas con exposición ósea que requiere colgajo."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400649") }, {"option_2": "Aplicar presión negativa de forma controlada sobre el lecho de la herida para favorecer su cicatrización.", "long_answer": "La imagen muestra una unidad portátil de terapia de presión negativa (VAC): pantalla con modo de terapia continuo o intermitente, valor de presión programado en 125 mmHg y un depósito transparente para recoger el exudado. Su objetivo principal es aplicar una presión subatmosférica controlada sobre el lecho de la herida, lo que retira exudado, reduce el edema, mejora la perfusión local, estimula el tejido de granulación y aproxima los bordes, favoreciendo la cicatrización. No es una bomba de infusión de fármacos, ya que no tiene línea de perfusión, ni un concentrador de oxígeno ni un pulsioxímetro, que carecerían de reservorio para exudado y de un valor de presión en mmHg."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064a") }, {"option_1": "Fijar bien al suelo las alfombras del pasillo y del dormitorio mediante cinta adhesiva antideslizante.", "option_4": "No se observan riesgos en este domicilio, ya que la disposición de la casa, incluido el pasillo junto al mueble del televisor, no obstaculiza el paso.", "long_answer": "En el plano del domicilio se aprecian alfombras sueltas en el pasillo, el salón y junto a la cama del dormitorio, uno de los factores extrínsecos de caída más frecuentes en personas mayores. La recomendación adecuada es retirarlas o fijarlas al suelo con cinta antideslizante para evitar tropiezos y resbalones. La alfombrilla antideslizante del plato de ducha, en cambio, es una medida protectora y debe mantenerse. Los objetos de uso frecuente deben colocarse a una altura accesible, entre la cintura y los hombros, nunca en estanterías altas que obliguen a subirse o estirarse. Afirmar que no existen riesgos es incorrecto, pues las alfombras y el mobiliario del salón suponen obstáculos evidentes."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40064d") }, {"option_1": "Puede utilizarla en quirófano como mascarilla quirúrgica durante un periodo no superior a 2 horas.", "option_2": "Puede reutilizarla en espacios cerrados tras lavarla, ya que es lavable y ofrece la máxima protección en lugares con poca ventilación.", "long_answer": "La mascarilla de la imagen presenta un marcado contradictorio e incompatible: aparece a la vez como N95 (norma estadounidense NIOSH), KN95 (norma china), con sello FDA, marcado CE, norma europea EN 149:2001+A1:2009 y clasificación FFP3 NR D, sin número de organismo notificado junto al CE. Una mascarilla filtrante certificada se ajusta a una sola norma, y esta mezcla es característica de productos falsificados, por lo que no cumple la normativa vigente y no debe utilizarse. No es una mascarilla quirúrgica de uso en quirófano, la indicación NR significa no reutilizable (no lavable) y tampoco es un dispositivo de uso exclusivo para pacientes con COVID-19."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065c") }, {"long_answer": "En la imagen se observa un único hilo que avanza de forma continua a lo largo de la herida, realizando pases horizontales paralelos a los bordes (trazados discontinuos, que representan el recorrido por la dermis) y cruzando de un borde a otro alternativamente, sin nudos intermedios. Este patrón corresponde a la sutura continua intradérmica, que queda oculta bajo la piel y ofrece un excelente resultado estético. El punto simple con nudo enterrado y el colchonero horizontal semienterrado son puntos sueltos e independientes, cada uno con su propio nudo. Pfannenstiel no es un tipo de sutura, sino una incisión suprapúbica transversal utilizada, por ejemplo, en la cesárea."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40065e") }, {"option_2": "Síndrome de Wolff-Parkinson-White.", "long_answer": "El trazado muestra una actividad auricular continua en forma de dientes de sierra (ondas F) regulares, sin línea isoeléctrica entre ellas, a unos 300 lpm, con complejos QRS estrechos que aparecen de forma regular cada cuatro ondas F (conducción 4:1). Este patrón es característico del flutter auricular. En la fibrilación auricular las ondas f son irregulares y el ritmo ventricular es irregularmente irregular. El Wolff-Parkinson-White se caracteriza por PR corto y onda delta, ausentes aquí, y la taquicardia supraventricular presenta QRS estrechos rápidos sin ondas auriculares en dientes de sierra."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400662") }, {"question": "Indique el ritmo cardíaco, teniendo en cuenta en el ECG una velocidad de 25 mm/s y un voltaje de 0,1 mV/mm:", "long_answer": "En el trazado las ondas P son regulares, pero los complejos QRS aparecen agrupados: tras varios latidos conducidos aparece una onda P que no va seguida de QRS, con una pausa, y el ciclo se repite. El intervalo PR se alarga progresivamente hasta el latido bloqueado y el primero tras la pausa tiene el PR más corto, lo que define el bloqueo auriculoventricular de segundo grado tipo I (Mobitz I o Wenckebach). No es un ritmo sinusal normal porque hay ondas P no conducidas. En el Mobitz II el PR es constante antes del bloqueo, y en el bloqueo completo existe disociación auriculoventricular sin relación entre P y QRS."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400665") }, {"option_3": "No contempla el sexo como factor determinante de la salud.", "long_answer": "La imagen reproduce el modelo de determinantes sociales de la salud de Dahlgren y Whitehead (1991), representado en capas concéntricas: en el centro (1) los factores individuales como edad, sexo y factores constitucionales; después (2) los estilos de vida del individuo; la capa 3 corresponde a las redes sociales y comunitarias; la 4 a las condiciones de vida y de trabajo (agua y saneamiento, vivienda, educación, servicios sanitarios), y la 5 a las condiciones socioeconómicas, culturales y ambientales generales. El informe de Lalonde es de 1974 y propone cuatro grandes determinantes, no capas. Este modelo sí incluye el sexo y los factores constitucionales en su núcleo."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400667") }, {"option_1": "Cuneiforme medial.", "long_answer": "La radiografía anteroposterior del pie izquierdo señala con la letra A un hueso del tarso situado en la cara medial del mediopié, inmediatamente distal a la cabeza del astrágalo y proximal a los tres cuneiformes: es el navicular o escafoides del pie. El astrágalo queda más proximal, articulado con la tibia y por debajo del navicular en la imagen. El cuboides se encuentra en el borde lateral del pie, articulado con los metatarsianos cuarto y quinto, y los cuneiformes están distales al navicular, en contacto con las bases de los tres primeros metatarsianos."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400668") }, {"long_answer": "La señal es un triángulo de advertencia con borde negro y fondo amarillo, conforme al Real Decreto 485/1997 de señalización de seguridad en el trabajo, que contiene el pictograma internacional de riesgo biológico: tres círculos abiertos entrelazados alrededor de un círculo central. Advierte de la presencia de agentes biológicos capaces de causar infección, por ejemplo en laboratorios o zonas de residuos sanitarios. Las radiaciones ionizantes y los materiales radiactivos se señalizan con el trébol radiactivo, formado por un círculo central y tres aspas, y la radiación atómica no corresponde a ninguna señal normalizada."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066b") }, {"long_answer": "La imagen muestra una cruz verde rodeada por una flecha circular, que es el logotipo de SIGRE, el sistema integrado de gestión y recogida de envases y restos de medicamentos del sector farmacéutico en España. Aparece en los envases de medicamentos para indicar que, una vez usados o caducados, deben depositarse en el punto SIGRE de la farmacia para su correcta gestión ambiental. El símbolo de la farmacia es una cruz verde (o la copa con la serpiente) sin flecha circular, y no existe un símbolo con este diseño para insecticidas ni para fitoterápicos."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066c") }, {"long_answer": "Según la codificación de colores de las botellas de gases medicinales (norma UNE-EN 1089-3), la ojiva identifica el gas y el cuerpo de las botellas medicinales es blanco. La botella 1, con ojiva totalmente blanca, contiene oxígeno. La botella 2, con ojiva blanca y negra (anillo o cuarteles), corresponde al aire medicinal. La botella 3, con ojiva y cuerpo azul, corresponde al óxido nitroso. El argón se identifica con verde oscuro, el dióxido de carbono con gris y el helio con marrón, colores que no aparecen en la imagen."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40066d") }, {"long_answer": "En el ECG de 12 derivaciones destacan ondas T altas, picudas, estrechas y simétricas, sobre todo en derivaciones precordiales (V2-V4) y en II, III y aVF, con ritmo regular y frecuencia normal. Las ondas T en tienda de campaña son el signo electrocardiográfico más precoz de la hiperpotasemia. No es una bradicardia sinusal, ya que la frecuencia no es inferior a 60 lpm, ni un ritmo de la unión, porque existen ondas P antes de cada QRS. La impregnación digitálica produce descenso del ST en cubeta y ondas T aplanadas o invertidas, no T picudas."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400670") }, {"long_answer": "La flecha señala un empastamiento inicial de la rama ascendente del QRS que acorta el intervalo PR y ensancha el complejo. Es la onda delta, típica de la preexcitación ventricular del síndrome de Wolff-Parkinson-White, en la que una vía accesoria (haz de Kent) activa precozmente parte del ventrículo antes que el sistema de conducción normal. La onda P prima corresponde a una P de origen ectópico, la onda F es la actividad auricular en dientes de sierra del flutter y la onda alfa no es una onda descrita en el ECG."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400672") }, {"long_answer": "El ciclo de la acción comunitaria descrito en las guías del Ministerio de Sanidad (Acción comunitaria para ganar salud) parte de una fase 0 transversal de trabajo en red y alianzas, y continúa con un ciclo de fases: 1, comenzar u organizarse como grupo motor; 2, explorar la comunidad y sus activos; 3, analizar y priorizar los problemas y necesidades; 4, planificar; 5, actuar; y 6, evaluar, que retroalimenta el ciclo. Por tanto, el número 3 corresponde a analizar y priorizar. Explorar la comunidad es la fase previa (2), mientras que actuar y evaluar son las fases 5 y 6."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400677") }, {"long_answer": "En el envase de sutura aparece la aguja HS23 (1/2 círculo, 23 mm) y la flecha señala un triángulo negro junto a la palabra Cutting. Este símbolo representa la sección y el tipo de punta de la aguja: triangular cortante, con filo en su borde, indicada para tejidos resistentes como la piel. Las agujas cilíndricas o atraumáticas se representan con un círculo. La forma del cuerpo (curvatura) se expresa con la fracción de círculo, en este caso 1/2 c, el ensamble se indica aparte y el hilo se define por su material y calibre, no por este triángulo."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d40067b") }, {"long_answer": "La imagen muestra un dispositivo azul con boquilla y una cámara con orificios de salida en la que se lee Shaker: es un dispositivo de presión espiratoria positiva oscilante, del mismo tipo que el Flutter. Contiene una bola metálica que vibra al espirar a su través, generando presión positiva y oscilaciones en la vía aérea que despegan las secreciones y facilitan su expectoración, por lo que se utiliza en fisioterapia respiratoria (fibrosis quística, bronquiectasias, EPOC). No es un irrigador ginecológico, un medidor de flujo urinario ni un agitador bucal."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400680") }, {"subject": "SEGURIDAD", "long_answer": "La imagen muestra una mascarilla quirúrgica desechable. Aunque esté manchada de secreciones buconasales, si procede de un paciente sin enfermedad infecciosa de declaración especial se clasifica como residuo sanitario no específico (grupo o clase II, asimilable a urbano), ya que este tipo de material no se considera de riesgo. Se deposita en el contenedor o bolsa de color negro (o gris según el plan de residuos de cada comunidad autónoma). El contenedor amarillo se reserva para residuos biosanitarios especiales o de riesgo (clase III), como material de pacientes con infecciones transmisibles o cortopunzantes, mientras que el azul y el rojo se utilizan para residuos químicos o citostáticos según la normativa autonómica."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400681") }, {"subject": "SEGURIDAD", "long_answer": "La imagen muestra dosímetros de muñeca del Centro Nacional de Dosimetría, en forma de pulsera, con una lámina que contiene detectores termoluminiscentes (TLD). La afirmación incorrecta es la del recambio semanal: los dosímetros personales se recambian y se envían a lectura con periodicidad mensual, que es el periodo de control dosimétrico habitual. El resto son correctas: contienen cuatro detectores termoluminiscentes, no deben someterse a procesos de esterilización con temperaturas superiores a 80 ºC porque se alteraría la lectura de los detectores, y cuando se usan guantes el dosímetro de muñeca se coloca por debajo de ellos para protegerlo de la contaminación."});
fix('examen_fotos', { _id: ObjectId("68235a23f759e9793d400682") }, {"subject": "PEDIATRÍA", "long_answer": "En la imagen se observa la cara inferior de la lengua de un niño con un frenillo lingual corto y engrosado que se inserta cerca de la punta, de modo que al elevarla la lengua adopta forma de corazón o V. Es la anquiloglosia, que puede limitar la movilidad lingual y dificultar la lactancia y, más adelante, la articulación del habla. El diastema es una separación entre dientes, la fibromatosis gingival es un sobrecrecimiento fibroso de las encías y la ránula es un quiste mucoso de retención en el suelo de la boca, de aspecto azulado y translúcido, ausentes en la imagen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ecf") }, {"long_answer": "La respuesta correcta es la toma rutinaria de cinco o más medicamentos, que es el criterio operativo más aceptado para definir la polifarmacia en los documentos de uso seguro del medicamento del SNS. Este umbral se asocia a un aumento de interacciones, reacciones adversas, errores de administración, caídas y falta de adherencia, sobre todo en personas mayores. El uso simultáneo de múltiples medicamentos es una descripción vaga que no fija ningún umbral. La toma de fármacos prescritos y no prescritos alude a la automedicación, y el uso de medicamentos para tratar varias enfermedades describe la multimorbilidad, no la polifarmacia en sí."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed2") }, {"long_answer": "La Meta 6 de las Metas Internacionales de Seguridad del Paciente se centra en reducir el riesgo de daño al paciente por causa de caídas. Exige valorar el riesgo de caída de cada paciente al ingreso y cuando cambia su situación clínica o su tratamiento, y aplicar medidas preventivas adaptadas a ese riesgo. Las demás opciones corresponden a otras metas: la identificación inequívoca del paciente es la Meta 1, la mejora de la seguridad de los medicamentos de alto riesgo es la Meta 3 y garantizar la cirugía en el lugar correcto, con el procedimiento correcto y al paciente correcto es la Meta 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976edc") }, {"long_answer": "Las pérdidas materiales y humanas son uno de los principales riesgos para la salud mental y el bienestar psicosocial en una catástrofe. La muerte de seres queridos, la destrucción de la vivienda o del medio de vida y la ruptura de las redes sociales generan duelo, estrés agudo, ansiedad, depresión y, en algunos casos, trastorno de estrés postraumático. El aumento de la solidaridad comunitaria es un factor protector, no un riesgo, ya que la red de apoyo favorece la recuperación. La estabilidad emocional y el optimismo ante el futuro también son recursos que protegen frente al malestar psicológico, así que no pueden considerarse riesgos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976edd") }, {"long_answer": "La pobreza y la discriminación aumentan la vulnerabilidad de determinados grupos en situaciones de crisis porque limitan el acceso a recursos, información, vivienda segura y servicios sanitarios, y suelen acompañarse de exclusión social y de peores condiciones de salud previas. Por eso las personas en situación de pobreza, migrantes, minorías o personas aisladas sufren con más intensidad las consecuencias de una catástrofe. El aumento de la cooperación entre vecinos, la disminución de la exclusión social y el mayor acceso a recursos básicos son factores protectores que reducen la vulnerabilidad, no la aumentan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eea") }, {"long_answer": "Los servicios especializados de salud mental deben mantener la coordinación con los demás niveles de apoyo (atención primaria, servicios sociales, equipos comunitarios y recursos de emergencia) para que la atención sea continua y escalonada y cada persona reciba el nivel de ayuda que necesita. Esta coordinación permite derivar a las personas con reacciones graves y evitar duplicidades. Alejarse de las comunidades afectadas va en contra del principio de proximidad. No detectar ni cubrir las necesidades emergentes y no desarrollar programas de capacitación en comunicación son omisiones contrarias a sus funciones, ya que deben identificar necesidades nuevas y formar a otros intervinientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eee") }, {"option_4": "Tuberculosis", "long_answer": "La leptospirosis es una enfermedad bacteriana causada por Leptospira que se transmite por contacto de la piel lesionada o las mucosas con agua o tierra húmeda contaminadas con orina de animales infectados, sobre todo roedores. Por eso es uno de los riesgos infecciosos característicos tras las inundaciones y durante las tareas de limpieza. La hepatitis A es una infección vírica de transmisión fecal-oral, no bacteriana. La legionelosis se adquiere al inhalar aerosoles de agua contaminada, no por contacto. La tuberculosis se transmite por vía aérea entre personas y no guarda relación con el contacto con aguas de inundación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eef") }, {"long_answer": "Durante la limpieza tras una inundación aumenta la exposición a productos químicos y sustancias tóxicas, como combustibles, pesticidas, productos de limpieza, lejía mezclada con otros compuestos o monóxido de carbono de generadores y bombas de achique. Por eso se recomienda usar equipos de protección, ventilar bien y no mezclar productos. Las demás opciones son incorrectas porque describen lo contrario de lo que ocurre: el riesgo de lesiones y heridas aumenta por escombros y objetos punzantes, los sistemas de saneamiento suelen quedar dañados y el riesgo de enfermedades de transmisión alimentaria crece por la contaminación de agua y alimentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef0") }, {"option_1": "7-10 días", "answer": 1, "long_answer": "Según el protocolo del Ministerio de Sanidad para la detección precoz de mpox, el periodo de incubación puede oscilar entre 5 y 21 días, pero el promedio observado en las series de casos de España y otros países es de 7 a 10 días. Este dato justifica que el seguimiento de los contactos se prolongue 21 días, que es el máximo posible. Los intervalos de 10-14 días y de 15-21 días quedan por encima del promedio y describen solo una parte del rango. El de 21-30 días supera el periodo máximo de incubación descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef6") }, {"long_answer": "Según su patogenicidad en las aves, los virus de la gripe aviar se clasifican en virus de influenza aviar de baja patogenicidad (IABP), que suelen causar infecciones leves o asintomáticas, y virus de influenza aviar de alta patogenicidad (IAAP), que provocan una enfermedad grave con elevada mortalidad en las aves de corral. Los tipos A y B son una clasificación de los virus gripales en general, y la gripe aviar pertenece al tipo A. Los tipos C y D tampoco clasifican la patogenicidad aviar. H5 y H7 son subtipos de hemaglutinina, que pueden incluir cepas tanto de alta como de baja patogenicidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef7") }, {"long_answer": "La neuraminidasa es una enzima de la superficie del virus gripal que rompe los residuos de ácido siálico y permite liberar los nuevos viriones de la célula infectada, lo que facilita la propagación del virus hacia células no infectadas. Es la diana de los inhibidores de la neuraminidasa, como el oseltamivir. La unión del virus a las células del hospedador depende de la hemaglutinina, no de la neuraminidasa. La replicación del genoma la realiza el complejo de la polimerasa viral. Por tanto, «todas las anteriores» no puede ser correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef9") }, {"long_answer": "Los estudios recogidos por el Ministerio de Sanidad indican que el tratamiento térmico de la leche, como la pasteurización, es altamente eficaz para inactivar el virus A(H5N1), mientras que la leche cruda de animales infectados puede contener cargas virales elevadas. Por eso se desaconseja consumir leche cruda o productos elaborados con ella en zonas donde hay ganado afectado. Afirmar que el tratamiento es ineficaz o que no tiene efecto demostrado contradice la evidencia disponible. Calificarlo de moderadamente efectivo infravalora la gran reducción de la carga viral que consigue el calentamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0b") }, {"long_answer": "La mpox está causada por el virus de la viruela del mono (MPXV), un virus ADN del género Orthopoxvirus, familia Poxviridae, que pertenece al mismo género que el virus de la viruela. Se distinguen dos clados principales, I y II, con distinta gravedad y patrón de transmisión. Es una zoonosis que también se transmite entre personas por contacto estrecho con lesiones, fluidos o material contaminado. Mycobacterium es un género bacteriano responsable de la tuberculosis y la lepra. Plasmodium es el parásito causante del paludismo y Candida albicans es un hongo que produce candidiasis; ninguno causa mpox."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0f") }, {"question": "Según el protocolo del Ministerio de Sanidad, ¿cuál de los siguientes es un criterio epidemiológico de caso de mpox?", "option_1": "Haber recibido la vacuna triple vírica en los 21 días previos", "option_3": "Haber viajado a cualquier país europeo en el último año", "option_4": "Haber padecido una infección respiratoria en los 6 meses previos", "long_answer": "El protocolo de mpox considera criterio epidemiológico haber viajado, en los 21 días previos al inicio de los síntomas, a zonas de África occidental o central donde se ha identificado circulación del virus. Junto a este, también son criterios epidemiológicos el contacto estrecho con un caso probable o confirmado y las relaciones sexuales en contextos de riesgo. Haber recibido la triple vírica no guarda relación con la exposición al MPXV. Un viaje a cualquier país europeo en el último año no se ajusta ni a las zonas ni al plazo de 21 días. Una infección respiratoria previa tampoco es un antecedente de exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f11") }, {"long_answer": "Según el protocolo de mpox, un caso probable es el que cumple el criterio clínico (un cuadro altamente sugestivo, con baja sospecha de otras patologías) y además un criterio epidemiológico, como el contacto estrecho con un caso, las relaciones sexuales en contextos de riesgo o un viaje a zonas con circulación del virus. Cumplir solo el criterio clínico corresponde a un caso sospechoso. Cumplir el criterio de laboratorio define el caso confirmado. El caso descartado es el sospechoso o probable con resultado negativo de laboratorio, así que no es una forma de clasificar un caso probable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f12") }, {"long_answer": "El protocolo de mpox establece que los contactos estrechos de un caso no hacen cuarentena, pero deben extremar las precauciones y reducir sus interacciones sociales durante los 21 días posteriores a la última exposición, abstenerse de mantener relaciones sexuales y vigilar la aparición de síntomas. Si presentan fiebre u otro síntoma compatible, deben seguir las recomendaciones de los casos y contactar con salud pública. La cuarentena obligatoria no está indicada. Tampoco se espera a la confirmación para actuar: la identificación de contactos empieza ante un caso probable. Mantener interacciones sociales normales ignora el riesgo durante el periodo de incubación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f17") }, {"question": "¿Qué medida se recomienda para el control de los casos no hospitalizados de mpox de clado I o II?", "option_1": "Minimizar las interacciones sociales, cubrir las lesiones y evitar el contacto físico y sexual hasta su completa cicatrización", "long_answer": "El protocolo del Ministerio de Sanidad establece para los casos no hospitalizados, de clado I o II, que el aislamiento domiciliario no es obligatorio salvo que haya muchas lesiones que no puedan cubrirse. Lo que se recomienda es minimizar las interacciones sociales, mantener las lesiones cubiertas y evitar el contacto físico y las relaciones sexuales hasta que las lesiones cicatricen por completo. También se aconseja usar utensilios propios, extremar la higiene de manos y usar mascarilla si hay síntomas respiratorios. La cuarentena en centros especializados no está contemplada. Mantener las interacciones habituales o no aplicar ninguna medida favorecería la transmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1b") }, {"long_answer": "Las personas asintomáticas que han tenido contacto estrecho con un caso de mpox no hacen cuarentena, pero deben extremar las precauciones y reducir sus interacciones sociales durante los 21 días posteriores a la exposición, que es el periodo máximo de incubación. Esto incluye evitar las relaciones sexuales y vigilar la aparición de fiebre, adenopatías o lesiones cutáneas. La cuarentena obligatoria no se recomienda en el protocolo. Mantener las interacciones habituales o no tomar ninguna medida no tiene en cuenta que el contacto puede estar incubando la enfermedad y transmitirla en cuanto aparezcan los primeros síntomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f20") }, {"long_answer": "La Estrategia en Enfermedades Neurodegenerativas del SNS propone que las personas con sospecha de demencia derivadas desde atención primaria sean atendidas por neurología en primera consulta en un plazo máximo de 2 meses. Con ello se busca un diagnóstico precoz que permita iniciar el tratamiento, planificar los cuidados y apoyar a la familia cuanto antes. Un mes sería un plazo más exigente que el establecido en la Estrategia. Los plazos de 3 y 4 meses superan el máximo fijado y retrasarían el diagnóstico y la intervención, que son clave en el pronóstico funcional de estas personas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f28") }, {"long_answer": "Según los datos que recoge la Estrategia en Diabetes del SNS, la tasa de amputaciones en España, referida a la población con diabetes de la Encuesta Nacional de Salud, se sitúa entre 1,96 y 1,18 por mil, con tendencia descendente en el periodo analizado. La amputación es la complicación más grave del pie diabético y muestra la importancia del cribado periódico del pie, la educación del paciente y el abordaje multidisciplinar. Las cifras de 4,58-3,89‰ y 3,89-4,52‰ superan claramente los valores descritos. El intervalo de 1,79-1,58‰ no coincide con el rango publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2b") }, {"answer": 4, "long_answer": "La bradicinesia, es decir, la lentitud en el inicio y la ejecución de los movimientos con disminución progresiva de su amplitud, es el signo cardinal de la enfermedad de Parkinson y de todos los parkinsonismos. Es imprescindible para el diagnóstico clínico de síndrome parkinsoniano, al que se suma al menos uno de los otros signos. El temblor de reposo es muy característico, pero falta en una parte de los pacientes. La rigidez muscular acompaña con frecuencia a la bradicinesia, pero no es obligatoria. La inestabilidad postural suele aparecer en fases avanzadas, así que no puede ser el signo cardinal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f30") }, {"long_answer": "En la enfermedad de Parkinson (EP), la alteración de los reflejos posturales forma parte de los signos motores que orientan el diagnóstico clínico, junto con la bradicinesia, la rigidez y el temblor de reposo. El diagnóstico de la EP se basa en estos signos motores. La hipotensión ortostática, la disfunción eréctil y la disfunción urogenital son síntomas autonómicos que pueden aparecer en la EP, pero no guían su diagnóstico. Además, cuando son precoces e intensos, sugieren otros parkinsonismos atípicos, como la atrofia multisistémica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f32") }, {"answer": 4, "long_answer": "El diagnóstico de la enfermedad de Parkinson es fundamentalmente clínico. Se basa en la anamnesis y el examen neurológico, que identifican la bradicinesia junto con el temblor de reposo o la rigidez, y en la buena respuesta a la levodopa. Ninguna prueba es diagnóstica por sí sola. Los análisis de sangre sirven para descartar otras causas, pero no confirman la enfermedad. Las pruebas de imagen, como la RM o el DaTSCAN, son complementarias y se reservan para casos dudosos o para el diagnóstico diferencial. La biopsia de tejido cerebral no se realiza en la práctica clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f34") }, {"option_1": "Cuidados Centrados en el Desarrollo y la Familia", "option_2": "Cuidados Centrados en la Tecnología", "long_answer": "Las recomendaciones del Ministerio de Sanidad para las unidades neonatales se basan en los Cuidados Centrados en el Desarrollo y la Familia (CCDF). Este modelo busca favorecer el desarrollo neurosensorial y emocional del recién nacido controlando el macroambiente (luz y ruido) y el microambiente (postura, manipulación y dolor), y reconoce a los padres como cuidadores principales, con presencia continua en la unidad, método canguro y lactancia materna. Unos cuidados centrados en la tecnología se oponen a este enfoque, que da prioridad a la persona y no al aparataje. Centrarse en la salud o en la educación no son modelos de cuidado neonatal reconocidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3c") }, {"long_answer": "El Método Madre Canguro consiste en el contacto piel con piel prolongado entre la madre o el padre y su recién nacido, colocado en posición vertical sobre el pecho del progenitor, y se asocia a la lactancia materna. Favorece la termorregulación, la estabilidad de las constantes, el sueño profundo, el vínculo y la duración de la lactancia, y reduce la ansiedad de los padres. No consiste en cuidados en incubadora, porque precisamente sustituye o complementa la incubadora con el cuerpo de los padres. Tampoco implica alimentación exclusiva con fórmula, ya que promueve la lactancia materna. No es un programa de ejercicios de estimulación temprana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3d") }, {"long_answer": "El Método Madre Canguro nació en 1978 en Bogotá, Colombia, en el Instituto Materno Infantil, de la mano de los doctores Edgar Rey Sanabria y Héctor Martínez. Surgió como alternativa a la falta de incubadoras y a las altas tasas de infección y abandono de los prematuros: las madres mantenían a sus hijos en contacto piel con piel. Su eficacia lo ha extendido después por todo el mundo, incluidos los países con altos recursos. México, España y Argentina han incorporado el método a sus unidades neonatales, pero no es allí donde se originó."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f42") }, {"option_3": "Vista, oído, tacto, gusto", "long_answer": "Los sentidos se desarrollan en un orden secuencial: primero el tacto, después el sistema vestibular, luego el gusto y el olfato, más tarde el oído y, por último, la vista, que es el sentido más inmaduro al nacer y el que más tarda en completar su desarrollo. Este orden explica por qué el prematuro es especialmente vulnerable a la luz y al ruido de las unidades neonatales. Las opciones que empiezan por el olfato o por la vista invierten la secuencia, porque la vista es el último sentido en desarrollarse y el tacto el primero."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f44") }, {"long_answer": "Según el documento de cuidados desde el nacimiento del Ministerio de Sanidad, hacia las 28 semanas de gestación el feto ya presenta movimientos oculares en respuesta a los sonidos, lo que muestra que el sistema auditivo empieza a ser funcional. Por eso el ruido de las unidades neonatales afecta a los grandes prematuros y conviene controlarlo. A las 24 y 26 semanas la vía auditiva todavía no está lo bastante madura para producir esta respuesta de forma constante. A las 30 semanas la respuesta ya existe, pero no es el momento en que aparece."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f45") }, {"long_answer": "Reducir el ruido en la UCIN mejora la autorregulación del sistema nervioso autónomo, que en el prematuro es inmaduro. Así se estabilizan la frecuencia cardiaca, la respiración, la tensión arterial y la saturación de oxígeno, y se favorecen el sueño y la ganancia de peso. El aumento del ritmo cardiaco es precisamente un efecto del exceso de ruido, no de su reducción. Una disminución del ritmo respiratorio no es el beneficio buscado, porque lo deseable es la estabilidad y no la depresión respiratoria. La influencia negativa sobre el sueño se debe al ruido elevado, mientras que el silencio lo protege."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f49") }, {"long_answer": "Las recomendaciones sobre el cuidado del prematuro aconsejan reducir la intensidad de la luz en la unidad neonatal, pero advierten que, cuando el niño permanece en un ambiente con baja luminosidad, hay que proporcionar una monitorización y una vigilancia muy cuidadosas para detectar a tiempo cambios de coloración, apneas o signos de deterioro que serían más difíciles de ver. Reducir la monitorización iría en contra de la seguridad del paciente. Aumentar la intensidad de la luz anularía el beneficio de la penumbra sobre el sueño y la estabilidad. Afirmar que no hace falta ninguna acción ignora el riesgo de una observación clínica más difícil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4b") }, {"long_answer": "Para proteger al prematuro de estímulos lumínicos perjudiciales se recomienda evitar la exposición directa a la luz. Para ello se cubren las incubadoras, se usa iluminación individual y regulable para los procedimientos, se protegen los ojos del niño y se reduce la intensidad lumínica de la unidad, lo que favorece el sueño y la estabilidad fisiológica. La luz indirecta puede utilizarse, pero no basta como medida de protección. Afirmar que no se necesita ninguna medida ignora la inmadurez visual del prematuro. Aumentar la intensidad lumínica no fortalece la visión, sino que resulta un estímulo estresante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4e") }, {"long_answer": "Entre las recomendaciones para reducir el ruido en las UCIN está colocar sonómetros visibles en las paredes de las salas. Avisan visualmente al personal cuando se superan los niveles recomendados y ayudan a modificar conductas como hablar en voz alta, golpear la incubadora o tardar en atender las alarmas. Mantener los niveles por encima de 65 dB es justo lo contrario de lo recomendado, ya que la Academia Americana de Pediatría aconseja no superar los 45 dB de forma continuada. No seguir esas recomendaciones y colocar aparatos cerca de la incubadora aumentan la exposición del niño al ruido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4f") }, {"long_answer": "La vista es el último sentido en desarrollarse y el más inmaduro en el momento del nacimiento. Su maduración continúa después del parto y finaliza alrededor de los 3 años de edad, cuando se consolidan la agudeza visual y la visión binocular. Por eso el recién nacido, y sobre todo el prematuro, es especialmente sensible a la luz intensa. Al nacer la visión está lejos de ser completa. A los 6 meses se han producido avances importantes, pero el desarrollo aún no ha terminado. Afirmar que nunca finaliza es incorrecto, porque la maduración visual se completa en la primera infancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f50") }, {"long_answer": "Reducir la intensidad de la luz en las UCIN mejora el patrón de sueño del recién nacido: aumenta el tiempo de sueño, sobre todo de sueño profundo, y favorece la organización de los ritmos circadianos, lo que se asocia a una mayor estabilidad fisiológica y a una mejor ganancia de peso. El aumento de la frecuencia cardiaca y del estrés son efectos de la luz intensa, no de su reducción. La mayor actividad motora también se asocia a la sobreestimulación lumínica, mientras que la penumbra favorece el reposo y la conservación de energía en el prematuro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f52") }, {"long_answer": "El contacto piel con piel precoz consiste en colocar al recién nacido desnudo, en decúbito prono, sobre el abdomen de la madre inmediatamente después del parto, cubierto por la espalda con una manta precalentada. Desde ahí, guiado sobre todo por el olfato, el niño se desplaza poco a poco hasta el pecho e inicia la primera toma. Favorece la termorregulación, la estabilidad cardiorrespiratoria, el vínculo y la lactancia materna. Iniciarlo una hora o un día después del parto no es contacto precoz, porque se pierde el periodo sensible inicial. El contacto piel con piel antes del parto es imposible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f55") }, {"long_answer": "El olfato es el sentido que orienta al recién nacido hacia el pecho materno. El olor de la areola y del calostro, parecido al del líquido amniótico, guía al niño durante el contacto piel con piel precoz hasta que se agarra al pecho por sí mismo. Por eso se recomienda no lavar el pecho materno ni al recién nacido antes de esa primera toma. El gusto interviene una vez iniciada la succión, pero no guía el desplazamiento. La vista está muy poco desarrollada al nacer, y el oído permite reconocer la voz materna, pero no orienta hacia el pecho."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f56") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad indican que, para poner en marcha el contacto piel con piel tras el parto, la maternidad debe disponer de un protocolo escrito. El protocolo unifica la actuación de todos los profesionales, garantiza la seguridad del recién nacido durante el contacto (vigilancia, postura y prevención del colapso posnatal) y facilita que se aplique de forma sistemática. No hace falta un informe médico individual para realizarlo en recién nacidos sanos. Un equipo de cirugía no tiene relación con este cuidado y un plan de alimentación no es un requisito para iniciarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f5c") }, {"long_answer": "La administración de vitamina K intramuscular a todos los recién nacidos después del nacimiento tiene una fuerza de recomendación A, porque se apoya en evidencia de alta calidad que demuestra que previene eficazmente la enfermedad hemorrágica del recién nacido, tanto la clásica como la tardía. La dosis habitual en el recién nacido a término es de 1 mg por vía intramuscular. Los grados B, C y D corresponden a recomendaciones apoyadas por evidencia de menor calidad o por opinión de expertos, lo que no se ajusta a la solidez de la evidencia disponible sobre la vitamina K intramuscular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f64") }, {"long_answer": "En países como Dinamarca, Suecia y Reino Unido se suspendió la profilaxis ocular sistemática del recién nacido, y solo se observó un aumento leve de la incidencia de oftalmia neonatal. Estos países tienen una baja prevalencia de infecciones de transmisión sexual y buenos programas de cribado prenatal, y su experiencia se usa para debatir la necesidad de la profilaxis universal. En Europa Oriental, el Sudeste asiático y los países en desarrollo la oftalmia neonatal sigue siendo un problema importante, con mayor riesgo de ceguera, por lo que no se ha planteado suspender la profilaxis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f67") }, {"long_answer": "La Academia Americana de Pediatría recomienda como profilaxis ocular neonatal aplicar nitrato de plata, pomada de eritromicina o pomada de tetraciclina, para prevenir la oftalmia neonatal por gonococo y, en parte, por clamidia. Hay que fijarse en que la recomendación ofrece alternativas («o»), no una combinación de productos. Las opciones que incluyen suero salino fisiológico son incorrectas, porque el suero no tiene acción antimicrobiana. Las que incluyen povidona yodada corresponden a otras recomendaciones, como la de la OMS, y no a la de la Academia Americana de Pediatría."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6d") }, {"long_answer": "En los recién nacidos con factores de riesgo de hipoacusia, como antecedentes familiares, infecciones congénitas, prematuridad extrema, hiperbilirrubinemia grave, fármacos ototóxicos o ingreso prolongado en la UCIN, la prevalencia de hipoacusia es de 15 a 20 veces superior a la de la población general. Por eso el cribado auditivo debe ser universal y, además, estos niños requieren un seguimiento audiológico específico aunque superen la prueba inicial. Los rangos de 2 a 5, de 5 a 10 y de 10 a 15 veces superior infravaloran el aumento de riesgo que recoge el documento del Ministerio de Sanidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6e") }, {"long_answer": "El implante coclear está indicado en niños con hipoacusia neurosensorial grave o profunda bilateral que no obtienen beneficio suficiente con los audífonos. Es un dispositivo electrónico que estimula directamente el nervio auditivo, y su eficacia para el desarrollo del lenguaje es mayor cuanto antes se coloque. Por eso es tan importante el diagnóstico precoz mediante el cribado neonatal. Los audífonos son el primer escalón terapéutico, pero en estos niños ya han resultado insuficientes. Las ayudas táctiles y los dispositivos acústicos tradicionales no consiguen una estimulación auditiva comparable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f77") }, {"long_answer": "Ante la aparición de disnea durante un episodio de hemólisis aguda en hemodiálisis, la enfermera debe avisar de inmediato al médico y al resto del equipo, porque es una complicación potencialmente letal que exige una actuación coordinada. En paralelo, debe parar la bomba de sangre, administrar oxígeno y aplicar el tratamiento prescrito. Administrar medicación sin indicación médica no se ajusta al protocolo. Dejar que el paciente se recupere solo supone una omisión grave del cuidado. Retirar el oxígeno empeoraría la hipoxemia y la disnea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f79") }, {"long_answer": "Ante la sospecha de hemólisis aguda durante la hemodiálisis hay que parar la diálisis de inmediato: detener la bomba de sangre, pinzar las líneas y no retornar al paciente la sangre del circuito, porque está hemolizada y rica en potasio, lo que podría causar una hiperpotasemia grave. Después se avisa al médico y se busca la causa. Administrar más líquidos no corrige el problema. Aumentar la velocidad de la bomba incrementaría el daño mecánico sobre los hematíes. Cambiar el líquido de diálisis sin detener el procedimiento seguiría exponiendo al paciente a la hemólisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f85") }, {"long_answer": "En España la vacunación frente a la hepatitis A se recomienda en las personas en situaciones de mayor riesgo de infección o de complicaciones: viajeros a zonas de alta o moderada endemicidad, hombres que tienen sexo con hombres, personas con hepatopatía crónica, contactos de casos, ciertos colectivos laborales y personas con conductas de riesgo, entre otras. No se recomienda de forma sistemática a personas sanas sin factores de riesgo. Ser menor de 50 años no constituye un criterio de vacunación. Viajar al extranjero solo es indicación cuando el destino es una zona endémica, no en cualquier viaje."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f87") }, {"long_answer": "Entre las recomendaciones de salud pública ante los brotes de hepatitis A está promover la equidad y prevenir el estigma y la discriminación hacia cualquier persona o grupo que pueda verse afectado, como los hombres que tienen sexo con hombres o determinados colectivos vulnerables. El estigma dificulta que estas personas consulten, se vacunen o colaboren en el estudio de contactos. Informar a la población sobre la prevención, reforzar la vigilancia epidemiológica y mantener contacto con las instituciones internacionales son medidas útiles para controlar los brotes, pero no se dirigen específicamente a prevenir el estigma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f99") }, {"long_answer": "El Código Europeo contra el Cáncer no menciona el uso de mascarilla. Sus recomendaciones se centran en no fumar, evitar el humo ajeno, mantener un peso saludable, hacer actividad física, seguir una dieta saludable, limitar el alcohol, protegerse del sol, evitar los carcinógenos laborales y el radón, la lactancia materna, la vacunación frente al VHB y el VPH, y la participación en los programas de cribado. Por tanto, no recomienda la mascarilla en interiores ni solo en espacios abiertos, y tampoco desaconseja su uso, ya que simplemente no la incluye entre sus medidas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f9e") }, {"question": "¿Qué se recomienda en el lugar de inyección tras administrar la vacuna frente a la COVID-19?", "long_answer": "Las guías técnicas de vacunación frente a la COVID-19 indican que la vacuna se administra por vía intramuscular, habitualmente en el deltoides. Al retirar la aguja se recomienda hacer una presión suave en el lugar de inyección con una gasa o un algodón, sin frotar ni masajear la zona. La vía intravenosa está contraindicada y no se utiliza en ningún caso. No se emplea una aguja gruesa, sino la de calibre y longitud adecuados para la vía intramuscular. Frotar el lugar de inyección no se recomienda, porque puede aumentar las reacciones locales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa4") }, {"long_answer": "Cualquier acontecimiento adverso tras la vacunación debe notificarse a los responsables del programa de vacunación y al Sistema Español de Farmacovigilancia, por ejemplo mediante la tarjeta amarilla o la web notificaRAM. Así se vigila de forma continua la seguridad de las vacunas y se detectan señales nuevas. Llamar a emergencias solo está indicado ante una reacción grave que necesite atención inmediata, pero eso no sustituye a la notificación. Guardar silencio impide la farmacovigilancia. Consultar con un médico puede ser necesario para la atención clínica, pero no equivale a notificar el acontecimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa6") }, {"long_answer": "Ante una enfermedad aguda grave, aunque no se sospeche COVID-19, se recomienda posponer la vacunación hasta que la persona se recupere. Así se evita confundir los síntomas de la enfermedad con posibles efectos adversos de la vacuna y se protege a una persona clínicamente inestable. Las enfermedades leves, como un catarro sin fiebre alta, no obligan a retrasarla. Administrar la vacuna con normalidad no tiene en cuenta esta precaución. Realizar una prueba diagnóstica no es un requisito para vacunar. No hacer nada no es una recomendación, ya que la vacunación debe reprogramarse cuando la persona se haya recuperado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fab") }, {"long_answer": "La acción de una campaña nacional de concienciación sobre el envejecimiento y la fragilidad, recogida en el documento de consenso sobre prevención de la fragilidad del SNS, persigue combatir el edadismo y la fragilidad. Busca cambiar la imagen negativa y estereotipada de la vejez y dar a conocer que la fragilidad puede detectarse, prevenirse e incluso revertirse. Promover el envejecimiento saludable es la finalidad general del documento, no el objetivo concreto de la campaña. Conseguir que todas las partes compartan una visión común y mejorar la prevención de la fragilidad corresponden a otras acciones del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fad") }, {"long_answer": "La acción de convertir la fragilidad en una prioridad de salud pública tiene como objetivo conseguir que todas las partes implicadas (administraciones, profesionales, sociedades científicas, asociaciones y la propia población) consideren el envejecimiento y el abordaje de la fragilidad como una prioridad, de modo que se le asignen recursos y se incluya en la planificación sanitaria y social. Promover el envejecimiento saludable es el fin último del documento. Fomentar la coordinación entre ámbitos de atención e impulsar la monitorización de la prevalencia de fragilidad corresponden a otras acciones específicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fbe") }, {"long_answer": "Ante el brote de enfermedad por virus de Marburgo en Ruanda, el Ministerio de Sanidad recomienda que las personas que vayan a viajar al país acudan a un Centro de Vacunación Internacional. Allí personal cualificado evalúa de forma individualizada el riesgo del viaje y da consejos preventivos, como evitar el contacto con enfermos, fluidos corporales, murciélagos y cuevas. Evitar cualquier contacto con la población local es una medida desproporcionada. No existe una prohibición general de viajar a Ruanda. Haber cumplido el calendario vacunal no protege, porque no hay vacuna autorizada frente a Marburgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc0") }, {"long_answer": "La enfermedad por virus de Marburgo se transmite de persona a persona por contacto directo con la sangre, las secreciones u otros fluidos corporales de una persona sintomática o fallecida, o con materiales contaminados con ellos. Por eso el riesgo es mayor para los cuidadores, el personal sanitario sin protección adecuada y quienes participan en ritos funerarios. No se transmite a través del aire en condiciones habituales. Las superficies contaminadas con fluidos pueden intervenir, pero no son la vía principal entre personas. La ingesta de alimentos contaminados no es una vía de transmisión interhumana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc1") }, {"long_answer": "Actualmente no existe ningún tratamiento específico aprobado para la enfermedad por virus de Marburgo. El manejo se basa en un tratamiento de soporte precoz: rehidratación, corrección de electrolitos, control de la fiebre y del dolor, y soporte hemodinámico y respiratorio, lo que mejora la supervivencia. Algunos anticuerpos monoclonales y antivirales se usan solo en ensayos clínicos o de forma compasiva. Los antibióticos de amplio espectro no actúan sobre los virus. No hay ninguna terapia antiviral oral aprobada y la inmunoterapia sigue en fase experimental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc8") }, {"long_answer": "La enfermedad meningocócica invasiva está causada por la bacteria Neisseria meningitidis, un diplococo gramnegativo que puede producir meningitis, sepsis o ambas, con una evolución rápida y una letalidad elevada. Los serogrupos responsables de la mayoría de los casos son A, B, C, W e Y, y frente a ellos existen vacunas específicas. La enfermedad no está causada por un virus, aunque algunas meningitis víricas tengan una clínica parecida. Tampoco la producen hongos ni parásitos, que son causas excepcionales de infección del sistema nervioso central, sobre todo en inmunodeprimidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fcb") }, {"long_answer": "La enfermedad meningocócica invasiva se previene combinando medidas generales de control que eviten la transmisión respiratoria, como la higiene respiratoria, la quimioprofilaxis de los contactos cercanos y la vigilancia epidemiológica, con la vacunación frente a los serogrupos incluidos en el calendario. La higiene dental no influye en la transmisión del meningococo. Los antibióticos solo se usan como quimioprofilaxis en contactos de un caso, no como medida general de prevención en la población. Una alimentación equilibrada es saludable, pero no previene esta infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fce") }, {"long_answer": "En España las vacunas tetravalentes conjugadas frente a los meningococos A, C, W e Y (MenACWY) disponibles son Menveo y Nimenrix, entre otras, y se utilizan en el calendario a los 12 años y en grupos de riesgo. Menjugate y NeisVac-C son vacunas monovalentes frente al meningococo C. Bexsero y Trumenba son vacunas frente al meningococo B, no tetravalentes. La afirmación de que solo hay vacunas tetravalentes para adultos es falsa, porque las vacunas MenACWY se usan también en lactantes y adolescentes según la ficha técnica.", "option_3": "Bexsero y Trumenba"});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fcf") }, {"long_answer": "Las vacunas conjugadas MenACWY son seguras y efectivas. Generan una respuesta inmunitaria protectora frente a los serogrupos A, C, W e Y y, además, reducen el estado de portador nasofaríngeo, con lo que contribuyen a la inmunidad de grupo, sobre todo cuando se vacuna a adolescentes. Sus efectos adversos más habituales son leves y transitorios: dolor y enrojecimiento en el lugar de la inyección, cefalea, malestar o febrícula. Por tanto, no es cierto que tengan muchos efectos secundarios, ni que sean seguras pero poco efectivas, ni efectivas pero poco seguras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd0") }, {"long_answer": "Según las preguntas y respuestas del Ministerio de Sanidad sobre la vacunación frente al meningococo, a un adolescente que ha recibido recientemente la vacuna MenC se le recomienda también la vacuna MenACWY. La MenC solo protege frente al serogrupo C, mientras que la tetravalente amplía la protección a los serogrupos A, W e Y, que han aumentado en Europa. Es falso que la MenC proteja frente a todos los serogrupos. No es necesario esperar un año desde la dosis de MenC para administrar la tetravalente. Existe información suficiente para hacer esta recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd1") }, {"answer": 3, "long_answer": "Que un adolescente necesite otra dosis depende de la edad a la que recibió la dosis previa de MenACWY. Según el Ministerio de Sanidad, si la recibió a partir de los 10 años no hace falta administrar otra en la adolescencia. Si la recibió antes, por ejemplo en la primera infancia, se recomienda vacunarle a los 12 años, porque la protección disminuye con el tiempo. No siempre es necesaria una dosis adicional. Tampoco es cierto que solo se aplique una dosis en la vida, porque existen pautas de lactante, adolescente y refuerzos en grupos de riesgo. Por tanto, decir que nunca es necesaria otra dosis es falso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fdc") }, {"answer": 1, "long_answer": "Según el protocolo del Ministerio de Sanidad, el periodo de transmisibilidad de la mpox comienza en general con la aparición de los primeros síntomas prodrómicos, como fiebre, cefalea, mialgias o adenopatías. Si la enfermedad debuta directamente con exantema, se considera contagiosa desde el día anterior a su aparición. La transmisibilidad dura hasta que las lesiones cicatrizan, las costras se caen y se forma piel nueva. Situar el inicio en el exantema o cinco días después lo retrasa. Las vesículas son muy contagiosas, porque contienen una gran carga viral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fdd") }, {"option_1": "Detectar, evaluar y dar una respuesta rápida a posibles eventos de salud pública de importancia nacional o internacional", "option_2": "Gestionar la prestación farmacéutica del Sistema Nacional de Salud", "option_3": "Coordinar el trasplante de órganos entre comunidades autónomas", "option_4": "Autorizar la comercialización de nuevos medicamentos", "long_answer": "El Sistema de Alerta Precoz y Respuesta Rápida (SIAPR) tiene como propósito detectar precozmente, evaluar de forma rápida y dar respuesta a los eventos que pueden suponer una amenaza de salud pública de importancia nacional o internacional, coordinando a las comunidades autónomas, el Ministerio de Sanidad y los organismos internacionales. Lo coordina el Centro de Coordinación de Alertas y Emergencias Sanitarias (CCAES). La gestión de la prestación farmacéutica y la autorización de medicamentos corresponden a otras estructuras del Ministerio y a la Agencia Española de Medicamentos. La coordinación de trasplantes es competencia de la Organización Nacional de Trasplantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fde") }, {"question": "¿Cuál de las siguientes es una función del Centro de Enlace Nacional del SIAPR?", "option_2": "Autorizar la comercialización de medicamentos", "option_3": "Gestionar las listas de espera quirúrgicas del SNS", "option_4": "Expedir certificados internacionales de vacunación a los viajeros", "long_answer": "El Centro de Enlace Nacional del SIAPR, función que ejerce el Centro de Coordinación de Alertas y Emergencias Sanitarias, se encarga de identificar y notificar los posibles eventos de salud pública de importancia nacional o internacional y de comunicarse con la OMS y la Unión Europea, conforme al Reglamento Sanitario Internacional. La autorización de medicamentos corresponde a la Agencia Española de Medicamentos y Productos Sanitarios. La gestión de las listas de espera quirúrgicas es una tarea de los servicios de salud autonómicos. Los certificados internacionales de vacunación los expiden los Centros de Vacunación Internacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe0") }, {"option_2": "Un caso aislado de gripe estacional en un paciente vacunado", "option_3": "El aumento esperado de bronquiolitis en invierno dentro de los umbrales habituales", "option_4": "Un accidente de tráfico con un herido leve", "long_answer": "Una de las situaciones que obliga a notificar al Sistema Nacional de Alerta Precoz y Respuesta Rápida es un aumento repentino o inesperado de la incidencia o la gravedad de una enfermedad con riesgo de extenderse a nivel nacional o internacional, ya sea en un grupo de población o en la población general. También lo son los agentes nuevos, las cepas más virulentas o cualquier situación aguda de importancia para la salud pública. Un caso aislado de gripe estacional y el aumento estacional de bronquiolitis dentro de lo esperado no son eventos inusuales. Un accidente de tráfico con un herido leve no tiene repercusión en la salud pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee4") }, {"long_answer": "En las emergencias, los trabajadores de salud mental no solo atienden a las personas afectadas: también capacitan a otros intervinientes, por ejemplo con programas de formación en comunicación y primeros auxilios psicológicos. Así, voluntarios, personal sanitario y líderes comunitarios pueden ofrecer un apoyo básico adecuado y detectar a quienes necesitan derivación. Mantenerse al margen de las tareas de primera necesidad, no colaborar con otros equipos y no supervisar el bienestar de los trabajadores y cuidadores son actitudes contrarias a las guías, que piden integración, coordinación y cuidado de quienes cuidan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee5") }, {"long_answer": "Una vez garantizados los servicios básicos (seguridad, agua, alimentos, refugio y atención sanitaria), las guías de salud mental en catástrofes recomiendan organizar la asistencia en el duelo. Incluye facilitar ritos culturales y religiosos, ceremonias de despedida y apoyo a las familias que han perdido a seres queridos, lo que favorece una elaboración saludable de la pérdida. El rastreo de víctimas forma parte de la respuesta inmediata, no es una acción posterior. La capacitación de líderes locales es útil, pero no es lo que se señala en este momento. La construcción de viviendas nuevas corresponde a la reconstrucción material, no al apoyo psicosocial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee7") }, {"long_answer": "El nivel de servicios especializados es el vértice de la pirámide de intervención en salud mental y apoyo psicosocial en catástrofes. Se dirige a un grupo pequeño de personas con sufrimiento intenso o trastornos mentales graves, previos o desencadenados, que necesitan atención continuada por profesionales especializados. Ofrecer ayuda a corto plazo es más propio de los niveles básicos. Además, los servicios especializados sí deben coordinar y apoyar a los nuevos equipos comunitarios y gestionar las urgencias y emergencias psiquiátricas, así que las dos últimas opciones describen lo contrario de su función."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee8") }, {"long_answer": "Es importante reforzar una red de profesionales de salud mental en las catástrofes para atender a las personas cuya respuesta sea especialmente grave o que presenten trastornos mentales previos o nuevos que necesiten intervención especializada. Esta red debe trabajar cerca de la comunidad, mediante visitas domiciliarias y actividades grupales, y coordinarse con los centros de salud mental de la zona. Por eso las demás opciones son incorrectas: alejarse de las comunidades, no coordinarse con los recursos existentes y no hacer visitas domiciliarias ni actividades grupales describen justo lo contrario de lo que se recomienda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eed") }, {"long_answer": "Las inundaciones aumentan la probabilidad de exposición a productos químicos, porque el agua arrastra combustibles, pesticidas, aguas residuales industriales y productos domésticos, y las tareas de limpieza implican usar desinfectantes y otros compuestos. Por eso se recomienda usar equipos de protección y no mezclar productos. Las demás opciones son falsas: tras una inundación el acceso a la asistencia sanitaria suele empeorar, el agua estancada favorece la proliferación de mosquitos y otros vectores, y el estrés, las pérdidas y el desplazamiento aumentan el riesgo de trastornos de salud mental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef1") }, {"long_answer": "La infección por MPXV suele empezar con un periodo prodrómico de fiebre, cefalea, mialgias, astenia y linfadenopatías, estas últimas muy características y útiles para distinguirla de la varicela y la viruela. Uno a tres días después aparece el exantema vesiculopustuloso. La tos y la dificultad respiratoria no son las manifestaciones iniciales típicas, aunque pueda haber odinofagia. La diarrea, los vómitos y el malestar gástrico no forman parte del cuadro prodrómico habitual. La pérdida de apetito y la fatiga extrema por sí solas no definen el inicio de la enfermedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef4") }, {"option_3": "Vacunación preexposición en grupos de mayor riesgo y profilaxis posexposición en contactos estrechos", "long_answer": "En España la vacunación frente a mpox se recomienda de forma dirigida. Como preexposición se vacuna a las personas de mayor riesgo, como las que mantienen prácticas sexuales de riesgo o tienen exposición laboral, y algunos viajeros a zonas afectadas con prácticas de riesgo. Como profilaxis posexposición se vacuna a los contactos estrechos, preferiblemente en los cuatro días siguientes a la exposición y hasta un máximo de 14. No es una vacunación anual para todas las edades ni obligatoria para la población adulta. La afirmación de que no existe vacuna es falsa, porque se utiliza la vacuna MVA-BN (Imvanex/Jynneos)."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef8") }, {"long_answer": "La gripe aviar puede pasar de las aves a los humanos por varias vías complementarias: la inhalación directa de partículas o polvo contaminado, la inoculación en las mucosas de las vías respiratorias superiores y los ojos (por ejemplo, al tocarse con las manos contaminadas) y el contacto con aves o animales infectados, vivos o muertos, o con sus secreciones y heces. Por eso las medidas de prevención combinan los equipos de protección respiratoria y ocular, la higiene de manos y la limitación del contacto con animales enfermos. Como las tres vías son correctas, la respuesta es «todas las anteriores»."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976efb") }, {"long_answer": "Los criterios diagnósticos de la ELA exigen signos de afectación de la neurona motora superior e inferior y que el trastorno progrese dentro de una región o se extienda a otras regiones (bulbar, cervical, torácica o lumbosacra), una vez descartadas otras causas. La progresión es un requisito esencial. Los signos de enfermedad de Parkinson y los trastornos visuales no forman parte de la ELA y orientan a otros diagnósticos. Los trastornos esfinterianos suelen respetarse en la ELA y su presencia es, de hecho, un criterio de exclusión que obliga a buscar otras enfermedades.", "option_4": "Trastornos esfinterianos"});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976efc") }, {"option_3": "Exclusión de la familia en la toma de decisiones", "option_4": "Derivación sistemática a un centro residencial", "long_answer": "El Plan Individualizado de Atención para las personas con ELA debe incluir la valoración del riesgo social y la elaboración de un itinerario social, junto con la valoración clínica, funcional y de cuidados. Así se pueden anticipar las necesidades de apoyo, las prestaciones de dependencia, la adaptación del domicilio y los recursos sociosanitarios a medida que avanza la enfermedad. El tratamiento farmacológico exclusivo es insuficiente para una enfermedad que necesita un abordaje integral. Excluir a la familia de la toma de decisiones y derivar sistemáticamente a un centro residencial contradicen la atención centrada en la persona y en su entorno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976efe") }, {"option_1": "Reducir la atención domiciliaria", "option_3": "Centralizar toda la atención en hospitales de tercer nivel", "option_4": "Limitar la información que se da a las familias", "long_answer": "La Estrategia en Enfermedades Neurodegenerativas del SNS incluye entre sus objetivos para las personas con ELA garantizar el apoyo social y la rehabilitación, con acceso a fisioterapia, logopedia, terapia ocupacional, ayudas técnicas y recursos sociales que preserven la autonomía y la calidad de vida durante toda la enfermedad. Reducir la atención domiciliaria iría en contra de las necesidades de unos pacientes con dependencia progresiva. Centralizar toda la atención en hospitales de tercer nivel contradice el modelo de atención coordinada y cercana. Limitar la información a las familias contradice los principios de autonomía y participación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f01") }, {"option_4": "Programas de formación para cuidadores", "long_answer": "La línea estratégica 4 de la Estrategia en Enfermedades Neurodegenerativas, dedicada a la coordinación sanitaria y social, incluye la gestión de casos como herramienta clave. Un profesional de referencia coordina los recursos sanitarios y sociales, garantiza la continuidad asistencial y simplifica el recorrido de la persona y su familia. La normativa para simplificar los visados y la del acompañamiento en urgencias corresponden a otros aspectos de la Estrategia, relacionados con la autonomía y los derechos del paciente. Los programas de formación para cuidadores pertenecen a las líneas de atención a la persona cuidadora y de formación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f02") }, {"option_3": "Gestión de casos", "option_4": "Proyectos financiados por el FIS", "long_answer": "La línea estratégica 6 de la Estrategia en Enfermedades Neurodegenerativas, dedicada a la participación ciudadana, incluye las campañas de concienciación dirigidas a la población. Su objetivo es dar a conocer estas enfermedades, reducir el estigma y favorecer la implicación social. Los programas formativos para cuidadores formales e informales pertenecen a la línea de formación. La gestión de casos forma parte de la línea de coordinación sanitaria y social. Los proyectos financiados por el FIS son indicadores de la línea de fomento de la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f05") }, {"long_answer": "La línea estratégica 7 de la Estrategia en Enfermedades Neurodegenerativas, sobre formación continuada, incluye los programas de formación para cuidadores, además de la formación de los profesionales sanitarios y sociales. La formación mejora la calidad de los cuidados y previene la sobrecarga de quienes atienden a estas personas. Las campañas de concienciación de la población, el informe sobre contactos con los medios de comunicación y la participación de las asociaciones de pacientes y familiares son aspectos de la línea 6, de participación ciudadana, y no de la línea de formación continuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f08") }, {"option_1": "Se desconoce en la mayoría de los casos (formas esporádicas)", "long_answer": "En la mayoría de los casos de esclerosis lateral amiotrófica, alrededor del 90-95 %, la causa es desconocida y se habla de ELA esporádica. Se cree que en ella intervienen varios factores genéticos de susceptibilidad y ambientales. Solo un 5-10 % de los casos son formas familiares con una mutación genética identificable, como las de los genes C9orf72 o SOD1, así que los factores genéticos no son la causa principal. La exposición a metales pesados y la actividad física intensa se han estudiado como posibles factores de riesgo sin una relación causal demostrada. La radiación electromagnética no se ha asociado a la ELA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0d") }, {"long_answer": "La infección por MPXV se caracteriza por la aparición de lesiones cutáneas vesiculares o pustulosas, a menudo umbilicadas, que evolucionan de forma sincrónica a costra. Suelen ir precedidas de síntomas prodrómicos como fiebre, cefalea, mialgias y adenopatías. Las lesiones no se limitan a las extremidades: pueden aparecer en la cara, el tronco, las palmas, las plantas, la zona genital, la perianal y las mucosas. La fiebre suele ser breve, no persistente durante dos semanas. En los casos graves sí pueden aparecer complicaciones, como sobreinfección bacteriana, neumonía, encefalitis o afectación ocular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f13") }, {"long_answer": "El protocolo de detección precoz de mpox tiene como objetivo detectar de forma precoz los casos para adoptar las medidas de control adecuadas y evitar casos secundarios: el aislamiento o las precauciones del caso, la identificación y el seguimiento de los contactos y la vacunación posexposición cuando esté indicada. Evitar la propagación internacional es un efecto indirecto, pero no el objetivo del protocolo nacional. Hacer un seguimiento detallado de todos los casos es una actividad que ayuda a cumplir el objetivo, no el objetivo en sí. La erradicación completa del virus no es una meta realista, porque es una zoonosis con reservorio animal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1c") }, {"long_answer": "Ante un caso sospechoso o probable de mpox, la prueba diagnóstica indicada es la PCR de una muestra de lesión cutánea: el exudado o el raspado de una vesícula o pústula, o el techo o la costra de las lesiones, que es la muestra con mayor carga viral. Si no hay lesiones accesibles se pueden tomar muestras de otras localizaciones, como un exudado faríngeo o anal. La orina no es la muestra de elección. El hemograma no permite el diagnóstico etiológico. Siempre debe hacerse una prueba de laboratorio para confirmar el caso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f23") }, {"long_answer": "En el plan de atención individualizada de las personas con enfermedad de Alzheimer y otras demencias se hace un seguimiento especial de la prevención de caídas y lesiones. El deterioro cognitivo, las alteraciones de la marcha, los fármacos psicoactivos y la desorientación aumentan mucho el riesgo de caídas y sus consecuencias. La prevención de la obesidad, de las enfermedades cardiacas y de las fracturas óseas puede formar parte de la atención general de cualquier persona mayor, pero no son los aspectos que la Estrategia señala para el seguimiento específico de estas personas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f24") }, {"long_answer": "Para reducir el estigma asociado a la enfermedad de Alzheimer, la Estrategia en Enfermedades Neurodegenerativas recomienda intervenir con los medios de comunicación. Llegan a toda la sociedad y pueden ofrecer una imagen realista y respetuosa de la enfermedad, desmontar estereotipos y difundir que es posible vivir con dignidad tras el diagnóstico. Las intervenciones con psicólogos, terapeutas ocupacionales y médicos especialistas forman parte de la atención clínica y rehabilitadora de la persona y su familia, pero no se dirigen a cambiar la percepción social de la enfermedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2a") }, {"long_answer": "Al comparar la Estrategia en Diabetes del SNS con la estrategia del NHS del Reino Unido, una de las líneas coincidentes en la atención al pie diabético es incorporar al podólogo al equipo asistencial. Su participación es clave en la prevención, el cuidado de las lesiones y la reducción de amputaciones. La importancia del cribado del pie, la naturaleza multidisciplinar de la atención y las unidades multidisciplinarias de pie diabético son aspectos relevantes, pero en el documento de referencia no figuran como la línea estratégica común que se destaca entre ambos sistemas sanitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2c") }, {"long_answer": "La enfermedad de Parkinson es el segundo trastorno neurodegenerativo más prevalente en la actualidad, solo superado por la enfermedad de Alzheimer. Su prevalencia aumenta con la edad y crece por el envejecimiento de la población. La demencia no es una enfermedad concreta, sino un síndrome con varias causas, la más frecuente de ellas el Alzheimer. La enfermedad de Alzheimer es el trastorno neurodegenerativo más prevalente, es decir, el primero y no el segundo. La esclerosis lateral amiotrófica es mucho menos frecuente que ambas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f2e") }, {"long_answer": "La edad es el factor de riesgo no modificable más importante para padecer la enfermedad de Parkinson: su incidencia y prevalencia aumentan claramente a partir de los 60 años. El sexo también es un factor no modificable, y la enfermedad es algo más frecuente en hombres, pero su peso es mucho menor que el de la edad. El consumo de café y de alcohol son factores modificables, así que no pueden ser la respuesta. De hecho, el consumo de café se ha asociado en los estudios epidemiológicos a un menor riesgo de enfermedad de Parkinson."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f31") }, {"option_1": "Demencia establecida", "answer": 1, "long_answer": "La demencia establecida no es característica de las fases iniciales de la enfermedad de Parkinson: el deterioro cognitivo grave suele aparecer en fases avanzadas. Una demencia precoz, en el primer año, orienta a la demencia con cuerpos de Lewy. En cambio, en las fases iniciales e incluso prodrómicas son frecuentes los síntomas no motores. Los síntomas sensitivos, como el dolor y la hiposmia, son habituales en esta etapa. También lo son los síntomas autonómicos, como el estreñimiento. El trastorno de conducta del sueño REM puede preceder durante años a los síntomas motores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f38") }, {"option_2": "Disminución del grado de ansiedad de los padres", "option_4": "Prolongación de la estancia hospitalaria", "long_answer": "Implicar a los padres en el cuidado de su hijo durante el ingreso neonatal disminuye su grado de ansiedad, porque les da control, seguridad y confianza en sus capacidades como cuidadores. También aumenta su satisfacción, mejora la calidad del vínculo con el niño y favorece la lactancia materna. Por eso son incorrectas las opciones que hablan de menor satisfacción con la experiencia en la unidad o de deterioro del vínculo, ya que ocurre lo contrario. La prolongación de la estancia hospitalaria tampoco es un efecto de esta implicación, que se asocia más bien a altas más tempranas y seguras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3b") }, {"long_answer": "Las recomendaciones basadas en pruebas y buenas prácticas del Ministerio de Sanidad sobre los cuidados desde el nacimiento aconsejan favorecer el contacto físico y la interacción del recién nacido con sus padres. Esto incluye el contacto piel con piel, el método canguro, la participación en los cuidados y la libre presencia en la unidad neonatal las 24 horas, porque mejora la estabilidad del niño, el vínculo y la lactancia. Separar al recién nacido de sus padres, restringir su presencia en la unidad y prohibir las visitas de otros familiares son prácticas que estas recomendaciones desaconsejan expresamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f3f") }, {"long_answer": "Los prematuros cuidados con el Método Madre Canguro tienen periodos de sueño más largos y un sueño más profundo, además de una mayor estabilidad de las constantes vitales, una mejor termorregulación y menos episodios de dolor y estrés. También se asocia a una mayor duración de la lactancia materna y a una reducción de las infecciones nosocomiales. Por eso son incorrectas las opciones que hablan de menor estabilidad de las constantes, de menor duración de la lactancia o de más infecciones nosocomiales, ya que describen lo contrario de lo que demuestra la evidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f40") }, {"option_1": "Realizarlos en método canguro siempre que sea posible", "long_answer": "Se recomienda realizar los procedimientos dolorosos, como la punción del talón o la venopunción, con el niño en método canguro siempre que sea posible. El contacto piel con piel reduce la respuesta al dolor (llanto, frecuencia cardiaca y puntuaciones en las escalas) y ayuda al niño a recuperarse antes, y puede combinarse con la succión no nutritiva o la lactancia materna. Evitarlos en canguro desaprovecha este efecto analgésico. Hacer los procedimientos solo si son estrictamente necesarios es un principio general, pero no es la recomendación específica sobre el método canguro. Sí existe una recomendación al respecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f41") }, {"option_4": "50-70 dB", "long_answer": "En las unidades neonatales se recomienda mantener el ruido ambiental entre 10 y 45 dB. La Academia Americana de Pediatría fija en 45 dB el límite máximo continuado, y solo de forma transitoria se toleran picos de hasta 65-70 dB. Así se protege la audición y la estabilidad fisiológica del prematuro y se favorece el sueño. Los rangos de 20-60 dB y de 30-50 dB permiten superar los 45 dB de forma continuada. El rango de 50-70 dB queda por completo por encima del nivel aconsejado y solo sería admisible como pico puntual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f46") }, {"long_answer": "La Academia Americana de Pediatría propone mantener el ruido en las UCIN por debajo de 45 dB de forma continuada, con un máximo transitorio de 65-70 dB. Por encima de estos niveles el ruido altera la estabilidad fisiológica del prematuro, interrumpe el sueño y puede dañar la audición. Mantenerlo por debajo de 55 dB permite un nivel de fondo superior al recomendado. Fijar 65 dB como límite transitorio sin establecer el nivel continuo es incompleto. No superar los 70 dB en ningún momento confunde el pico máximo tolerado con el nivel de ruido habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f4c") }, {"option_3": "Aumenta la saturación de oxígeno", "answer": 1, "long_answer": "El ruido de las unidades de cuidados intensivos neonatales actúa como un estímulo estresante que aumenta la presión arterial. Además, produce taquicardia, taquipnea, desaturación, aumento de la presión intracraneal y alteraciones del sueño, que en los prematuros pueden favorecer complicaciones como la hemorragia intraventricular. Por eso no es cierto que disminuya el ritmo cardiaco, que en realidad se acelera. Tampoco aumenta la saturación de oxígeno, sino que favorece la desaturación. La presión intracraneal no disminuye, sino que se eleva, lo que es uno de los principales motivos para controlar el ruido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f51") }, {"long_answer": "Para proteger y facilitar el sueño en las UCIN se recomienda evitar la exposición del niño a la luz directa: cubrir la incubadora, usar luces individuales y regulables solo para los procedimientos, proteger los ojos y crear periodos de penumbra que favorezcan los ritmos circadianos. Exponerlo a la luz directa altera el sueño y supone un estrés para el prematuro. No individualizar la exposición a la luz va en contra de adaptar el entorno a cada niño. No medir la intensidad de la luz impide comprobar que se cumplen los niveles recomendados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f57") }, {"long_answer": "En los recién nacidos sanos y vigorosos se recomienda colocarlos sobre el abdomen o el pecho de la madre justo después del parto y mantenerlos en contacto íntimo piel con piel, sin interrupciones innecesarias, al menos hasta que hagan la primera toma. Este contacto favorece la termorregulación, la estabilidad cardiorrespiratoria y glucémica, el vínculo y el éxito de la lactancia. Por tanto, no es cierto que no se recomiende ningún contacto piel con piel, ni que haya que evitarlo en las primeras horas. El contacto con el padre es una alternativa cuando la madre no puede, no la recomendación preferente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f5a") }, {"option_4": "Mayor dolor en el momento de la administración", "long_answer": "Una desventaja de la vitamina K oral es la dificultad para cumplir la pauta: para que sea eficaz requiere varias dosis repetidas durante las primeras semanas, y si se olvida alguna aumenta el riesgo de enfermedad hemorrágica tardía. Además, su absorción es variable. El riesgo de daño neuromuscular local es un inconveniente de la vía intramuscular, no de la oral. La supuesta relación con la leucemia se planteó con la vía intramuscular y no se ha confirmado. La vía oral no causa más dolor al administrarla, sino que es precisamente la alternativa indolora a la inyección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f5d") }, {"long_answer": "En los prematuros de menos de 32 semanas que pesan más de 1000 g, la dosis recomendada de vitamina K es de 0,5 mg por vía intramuscular o intravenosa, para prevenir la enfermedad hemorrágica del recién nacido. La dosis de 1 mg es la del recién nacido a término o del prematuro de mayor edad gestacional. La pauta oral de 2 mg es una alternativa para recién nacidos a término cuyos padres rechazan la inyección, no para grandes prematuros. La dosis de 0,3 mg se ajusta al peso en los prematuros de menos de 1000 g."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f63") }, {"long_answer": "La oftalmia neonatal sigue siendo un problema importante de morbilidad y ceguera en África y el Sudeste asiático. Allí son más prevalentes las infecciones de transmisión sexual por gonococo y clamidia, el cribado prenatal es limitado y no siempre hay profilaxis ocular ni tratamiento precoz. En Europa, Estados Unidos y, en general, en Norteamérica la incidencia es baja gracias al control de estas infecciones y a la profilaxis, hasta el punto de que algunos países la han suspendido. Oceanía y Asia Oriental no son las regiones que se señalan como más afectadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f65") }, {"long_answer": "Los ensayos clínicos aleatorizados que compararon distintos agentes profilácticos (nitrato de plata, eritromicina, tetraciclina y povidona yodada) para prevenir la oftalmia neonatal no encontraron diferencias estadísticamente significativas entre los grupos de estudio. Por eso puede usarse cualquiera de ellos y la elección depende de la disponibilidad, la tolerancia y el coste. Las opciones que afirman que la eritromicina es más eficaz que la povidona yodada, que la povidona yodada es menos eficaz que el nitrato de plata o que la tetraciclina supera al nitrato de plata no se apoyan en los resultados de estos ensayos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f66") }, {"long_answer": "La OMS recomienda como profilaxis oftálmica del recién nacido aplicar solución de nitrato de plata, pomada de tetraciclina o povidona yodada, para prevenir la oftalmia neonatal por gonococo y clamidia, sobre todo donde la prevalencia de estas infecciones es alta. Son alternativas, no una combinación. La opción con suero salino fisiológico es incorrecta, porque el suero no tiene efecto antimicrobiano. Las opciones que combinan eritromicina con povidona yodada o que se limitan a nitrato de plata, eritromicina o tetraciclina corresponden a otras recomendaciones, como la de la Academia Americana de Pediatría."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f69") }, {"long_answer": "Los potenciales evocados auditivos de tronco cerebral (PEATC), sobre todo en su versión automatizada para el cribado neonatal, tienen una sensibilidad cercana al 97 % para detectar la hipoacusia. Además, exploran toda la vía auditiva hasta el tronco cerebral, así que detectan también la neuropatía auditiva, que las otoemisiones acústicas no identifican. Por eso son la prueba preferente en los recién nacidos con factores de riesgo. Una sensibilidad del 86 % sería demasiado baja para una prueba de cribado de referencia. Las cifras del 96 % y del 100 % no coinciden con el valor que recoge el documento de referencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6a") }, {"option_1": "1 a 3 por cada 1.000 recién nacidos", "option_2": "1 a 3 por cada 100 recién nacidos", "option_3": "10 a 15 por cada 100 recién nacidos", "option_4": "1 a 3 por cada 100.000 recién nacidos", "answer": 1, "long_answer": "La hipoacusia significativa (moderada, grave o profunda) afecta a entre 1 y 3 de cada 1.000 recién nacidos, una cifra que aumenta mucho en los niños con factores de riesgo y en los que ingresan en unidades de cuidados intensivos neonatales. Esta prevalencia, superior a la de otras enfermedades que se criban al nacer, justifica el cribado auditivo neonatal universal. Hablar de 1 a 3 o de 10 a 15 de cada 100 recién nacidos sobrestima la frecuencia real. La cifra de 1 a 3 por cada 100.000 la infravalora y la convertiría en una enfermedad rara."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f74") }, {"long_answer": "En la hemólisis aguda durante la hemodiálisis pueden aparecer hipertensión, dolor torácico, disnea, náuseas y vómitos, dolor abdominal o lumbar y, como signo muy característico, sangre de color rojo oscuro o plasma rosado en la línea venosa, causado por la hemoglobina libre. Es una complicación grave por el riesgo de hiperpotasemia. Las demás combinaciones no son correctas: incluyen elementos sin relación con la hemólisis, como el suero salino, la tos o la pérdida de audición, o colores del plasma que no la caracterizan, como el amarillo, que es el normal, o el morado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f75") }, {"long_answer": "Uno de los objetivos del protocolo de hemólisis aguda durante la hemodiálisis es actuar con rapidez ante un episodio y garantizar la seguridad del paciente. Para ello hay que detener la bomba, pinzar las líneas sin retornar la sangre, avisar al equipo y tratar las complicaciones, porque la hiperpotasemia secundaria puede ser letal. Detectar precozmente los síntomas de la hipertensión no es el objetivo de este protocolo. Administrar oxígeno en exceso no es un objetivo terapéutico. Revisar la presión arterial es un control habitual de la sesión, pero no es el objetivo específico frente a la hemólisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7b") }, {"long_answer": "Para garantizar la seguridad del paciente ante una hemólisis aguda durante la hemodiálisis es importante comprobar rápidamente el circuito extracorpóreo. Hay que revisar si las líneas están acodadas u obstruidas, si la bomba funciona bien y si la temperatura y la composición del líquido de diálisis son correctas, ya que son las causas más frecuentes. Administrar medicación sin supervisión médica no se ajusta al protocolo. No verificar la colocación de las líneas ni las medidas de seguridad del circuito y del monitor impediría identificar y corregir la causa de la hemólisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7c") }, {"long_answer": "Ante las complicaciones de la sesión de hemodiálisis, como la hemólisis aguda, se recomienda administrar oxigenoterapia y la medicación prescrita según la gravedad del cuadro clínico, mientras se vigila estrechamente al paciente. Las demás opciones son incorrectas porque describen omisiones. Hay que verificar el estado clínico del paciente. Hay que extraer sangre para valorar el hematocrito, los electrolitos (sobre todo el potasio) y las enzimas. Y la sesión puede reanudarse con un circuito nuevo cuando se ha identificado y resuelto la causa y el paciente está estable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7d") }, {"long_answer": "Ante una hemólisis aguda durante la hemodiálisis es vital iniciar las medidas rápidamente, porque se trata de una situación potencialmente letal por la hiperpotasemia: los hematíes destruidos liberan potasio, que puede provocar arritmias graves. Por eso no se retorna la sangre del circuito y se controla el potasio sérico. Revisar al paciente cada hora es insuficiente en una situación aguda, que exige una vigilancia continua. Administrar oxígeno solo si el paciente lo pide no se ajusta al protocolo, que lo indica según la clínica. No comprobar la colocación de las líneas impediría detectar una de las causas mecánicas más frecuentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7e") }, {"long_answer": "Según la información del Ministerio de Sanidad, aunque se ha detectado ARN del SARS-CoV-2 en las heces de algunos pacientes, el riesgo de transmisión fecal-oral de la COVID-19 se considera bajo. En pocos casos se ha conseguido aislar virus viable en heces y no se han documentado contagios por esta vía, de modo que la transmisión es sobre todo respiratoria, por gotas y aerosoles. Calificar el riesgo de muy alto o de moderado sobrestima la evidencia disponible. Considerarlo despreciable sería excesivo, porque no se puede descartar del todo y se mantienen las medidas de higiene de manos y de los aseos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f84") }, {"long_answer": "El Consejo Interterritorial del SNS no recomienda la vacunación sistemática frente a la hepatitis A en la población infantil, porque en España la endemicidad es baja. La vacuna se reserva para los grupos de riesgo, como los viajeros a zonas endémicas, las personas con hepatopatía crónica o los contactos de casos. Por eso es incorrecto afirmar que se recomienda la vacunación sistemática. Ceuta, Melilla y Cataluña incluyen la vacuna en sus calendarios infantiles por decisión propia y por su situación epidemiológica, pero esta no es la recomendación del Consejo Interterritorial, y además la vacuna no se recomienda «solo» en esos territorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f88") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad para vacunar a la población desplazada desde Ucrania señalaban como prioritarias la poliomielitis y el sarampión. Ucrania tenía coberturas vacunales bajas, había sufrido brotes recientes de sarampión y casos de polio derivados de la vacuna, y son enfermedades muy transmisibles en situaciones de hacinamiento. La tos ferina y la tuberculosis se tienen en cuenta en la valoración sanitaria, pero no eran las enfermedades inmunoprevenibles prioritarias. Por eso las combinaciones que las incluyen son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f8e") }, {"option_1": "Niños de 5 a 9 años", "option_4": "Lactantes menores de 1 año", "answer": 1, "long_answer": "Según el documento de recomendaciones de vacunación frente a la hepatitis A del Ministerio de Sanidad, los niños de 5 a 9 años suelen ser el grupo más afectado en España. Muchos casos se asocian a viajes a países de alta endemicidad para visitar a familiares. En los niños la infección suele ser leve o asintomática, lo que favorece la transmisión. Los adolescentes de 12 a 17 años no son el grupo con mayor incidencia. Los mayores de 60 años son en su mayoría inmunes por infección natural. Los lactantes menores de 1 año tienen poca exposición y conservan anticuerpos maternos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f8f") }, {"long_answer": "A los viajeros que se desplazan a zonas de alta endemicidad de hepatitis A se les recomienda la vacuna de virus inactivados de la hepatitis A. Es muy inmunógena, protege con una sola dosis desde unas dos semanas después de su administración y una segunda dosis a los 6-12 meses garantiza una protección prolongada. Una doble dosis de la vacuna pediátrica no es la pauta indicada en los adultos. La vacuna combinada A+B se reserva para quienes necesitan protección frente a ambos virus. Las inmunoglobulinas inespecíficas no son una vacuna, sino una inmunización pasiva de uso excepcional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f91") }, {"long_answer": "Según el Ministerio de Sanidad, los estudios de seroprevalencia muestran que más del 80 % de las personas nacidas en España antes de 1960 tienen anticuerpos frente a la hepatitis A. Por eso se las considera mayoritariamente inmunes por haber pasado la infección natural, que era muy frecuente en la infancia cuando las condiciones higiénicas y sanitarias eran peores. Esto permite, por ejemplo, hacer una serología antes de vacunar a los adultos de esa edad. Las cifras de menos del 20 %, entre el 20 y el 40 % y entre el 40 y el 60 % infravaloran la inmunidad natural de estas generaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f9f") }, {"long_answer": "Para la temporada 2024-2025 las recomendaciones del Ministerio de Sanidad contemplaban tres vacunas frente a la COVID-19 adaptadas a las variantes circulantes: dos de ARNm, Comirnaty y Spikevax, y una de proteína recombinante adyuvada, Bimervax, que es una alternativa para quienes no pueden recibir vacunas de ARNm. Hablar de una o dos vacunas no reconoce todas las opciones disponibles esa temporada. Cuatro vacunas superaría el número de productos contemplados en las recomendaciones oficiales para la campaña 2024-2025."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa1") }, {"long_answer": "Si por error se administra una dosis incompleta de vacuna, por ejemplo por una fuga en la jeringa o porque el paciente se mueve, se recomienda extraer una dosis íntegra y administrarla en ese mismo momento. No se tiene en cuenta la fracción ya administrada. Esperar a ver si hay reacciones no resuelve la falta de protección. Realizar un test diagnóstico no está indicado. Notificar el error es una buena práctica de seguridad, pero no sustituye a la administración de la dosis completa, que es la actuación prioritaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa5") }, {"long_answer": "Las personas que han tenido una miocarditis o una pericarditis después de una dosis de vacuna de ARNm frente a la COVID-19 no deben recibir dosis posteriores de vacunas de ARNm, porque el riesgo de recurrencia no está bien establecido y el episodio previo se considera una precaución importante. Si la vacunación está indicada, puede valorarse una vacuna con otra plataforma. Administrar una dosis cada semana no tiene ningún fundamento y aumentaría el riesgo. Realizar un test diagnóstico no es la recomendación. No hacer nada ignora la necesidad de modificar la pauta de vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa7") }, {"long_answer": "Las embarazadas, en cualquier trimestre de gestación, y las mujeres durante el puerperio son uno de los grupos a los que se recomienda tanto la vacuna antigripal como la de la COVID-19, por su mayor riesgo de complicaciones y para proteger al recién nacido. Los niños menores de 5 años, en concreto los de 6 a 59 meses, tienen recomendada la vacuna de la gripe, pero no la de la COVID-19 de forma general. La recomendación por edad en adultos no empieza a los 50 años, sino a edades más avanzadas. Las personas que trabajan en servicios públicos esenciales están incluidas en la recomendación de la gripe, pero no en la de la COVID-19."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa9") }, {"long_answer": "Se recomienda vacunar a las embarazadas frente a la gripe y la COVID-19 en cualquier trimestre de la gestación, porque tienen más riesgo de complicaciones graves y la vacunación protege también al recién nacido durante sus primeros meses gracias al paso de anticuerpos. Estas vacunas han demostrado ser seguras en todas las etapas del embarazo. No vacunar deja sin protección a la madre y al niño. Limitar la vacunación al primer o al tercer trimestre no tiene fundamento y retrasaría la protección durante la temporada de circulación de los virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb5") }, {"long_answer": "El «Manual de políticas sobre el alcohol», traducción de la guía «Alcohol policy playbook», lo elaboró la Oficina Regional de la OMS para Europa. Su objetivo es ayudar a los profesionales de salud pública a responder con evidencia a los argumentos más habituales contra las políticas eficaces sobre el alcohol, como la regulación del precio, de la publicidad y de la disponibilidad. Aunque forma parte de la OMS, la autoría corresponde a la oficina regional europea y no a la sede central. Los CDC y UNICEF no participaron en su elaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fba") }, {"long_answer": "La investigación muestra un vínculo significativo entre la exposición de los jóvenes a la publicidad y el marketing del alcohol y un inicio más temprano del consumo, además de un mayor consumo y más episodios de consumo intensivo. Por eso se recomienda restringir el marketing. Es falso que no haya evidencia de esta influencia. También es falso que la publicidad solo influya en la elección de la marca, porque modifica las actitudes y la conducta de consumo. La autorregulación del sector ha demostrado ser ineficaz para proteger a los menores, que siguen expuestos a contenidos dirigidos a ellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fbc") }, {"option_2": "Realizar controles de alcoholemia aleatorios y frecuentes junto con límites legales bajos de alcoholemia", "long_answer": "Según la evidencia en salud pública que recogen los documentos de la OMS, la estrategia más eficaz para prevenir la conducción bajo los efectos del alcohol es combinar límites legales bajos de alcoholemia con controles aleatorios, frecuentes y visibles, que disuaden a toda la población de conductores. Centrarse solo en quienes beben de forma ocasional deja fuera a gran parte de los conductores de riesgo. Las campañas de conductor designado son populares, pero no han demostrado reducir los accidentes. Promover las bebidas sin alcohol o de baja graduación no es una medida eficaz para prevenir la conducción bajo los efectos del alcohol."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc3") }, {"long_answer": "Según las recomendaciones del Ministerio de Sanidad y de la OMS, el lavado de manos con agua y jabón debe durar entre 40 y 60 segundos en total, y durante ese tiempo hay que frotar todas las superficies de las manos: palmas, dorsos, espacios interdigitales, pulgares y yemas de los dedos. Con ese tiempo se eliminan de forma eficaz la suciedad y los microorganismos. Un lavado de 20-30 o de 30-40 segundos resulta insuficiente para cubrir todos los pasos de la técnica. Más de un minuto no aporta un beneficio adicional significativo y puede irritar la piel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc7") }, {"long_answer": "El documento técnico del Ministerio de Sanidad sobre higiene en el hogar recomienda limpiar y desinfectar los estropajos de cocina lavándolos con lejía diluida y dejándolos secar bien, además de renovarlos con frecuencia. Así se elimina la gran carga de microorganismos que acumulan por la humedad y los restos de comida. La solución hidroalcohólica está pensada para la higiene de las manos y no es el método indicado para los estropajos. El agua y el jabón los limpian, pero no los desinfectan. El documento sí incluye una recomendación concreta al respecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd7") }, {"long_answer": "En las zonas donde se han detectado animales infectados o casos humanos de fiebre del Nilo occidental se recomienda reforzar la vigilancia pasiva y activa del virus en humanos. Esto incluye buscar casos en pacientes con meningitis o encefalitis de causa desconocida, informar a los profesionales sanitarios y aplicar medidas de seguridad en las donaciones de sangre y órganos. El control vectorial debe hacerse de forma continuada durante la temporada de actividad de los mosquitos, no solo al final. El vector principal es el mosquito del género Culex, no Aedes. Los estudios virológicos no son la medida prioritaria en estas zonas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd8") }, {"long_answer": "La enfermedad neuroinvasiva por el virus del Nilo occidental afecta a menos del 1 % de las personas infectadas, sobre todo a las mayores y a las inmunodeprimidas. Engloba tres síndromes: meningitis, encefalitis y parálisis flácida aguda, esta última por afectación de las motoneuronas del asta anterior medular. La fiebre, la cefalea y otros síntomas inespecíficos forman parte de la fiebre del Nilo occidental, que es la forma leve no neuroinvasiva. La diarrea, los vómitos, la fatiga, el dolor muscular, la erupción y el dolor abdominal son síntomas generales que no definen la afectación del sistema nervioso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed5") }, {"long_answer": "La Meta 6 de las Metas Internacionales de Seguridad del Paciente es la reducción del riesgo de daño al paciente por causa de caídas. Para ello se valora el riesgo de caída de todos los pacientes y se aplican medidas preventivas individualizadas, como la adecuación del entorno, la revisión de los fármacos de riesgo y la educación del paciente y la familia. La disminución del riesgo de infecciones asociadas a la atención sanitaria es la Meta 5. La comunicación efectiva es la Meta 2. Asegurar la cirugía en el lugar correcto, con el procedimiento correcto y al paciente correcto es la Meta 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed6") }, {"long_answer": "La primera de las Metas Internacionales de Seguridad del Paciente es la identificación inequívoca del paciente. Exige usar al menos dos identificadores, como el nombre completo y la fecha de nacimiento, y nunca el número de habitación o de cama, antes de administrar medicamentos o hemoderivados, extraer muestras o realizar procedimientos. Es la base de todas las demás prácticas seguras. La comunicación efectiva es la Meta 2. La mejora de la seguridad de los medicamentos de alto riesgo es la Meta 3. Garantizar la cirugía en el lugar correcto, con el procedimiento correcto y al paciente correcto es la Meta 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ed8") }, {"long_answer": "La sexta Meta Internacional de Seguridad del Paciente es la reducción del riesgo de daño al paciente por causa de caídas. Obliga a evaluar el riesgo de caída al ingreso y siempre que cambie la situación del paciente, y a aplicar medidas preventivas adaptadas a ese riesgo. La comunicación efectiva corresponde a la Meta 2, la mejora de la seguridad de los medicamentos de alto riesgo a la Meta 3, y la cirugía y los procedimientos seguros en el lugar correcto y al paciente correcto a la Meta 4. Ninguna de estas tres es la sexta meta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976edf") }, {"long_answer": "Implicar a la comunidad afectada en la respuesta de emergencia es importante para asegurar la efectividad de los apoyos. Las personas afectadas conocen sus necesidades, recursos y costumbres, y su participación activa hace que las intervenciones sean más pertinentes, aceptadas y sostenibles, además de reforzar su sensación de control y su dignidad. Las demás opciones describen justo lo contrario de lo que persiguen las guías de salud mental y apoyo psicosocial en emergencias: infantilizar a la comunidad, disminuir la dignidad de las personas o evitar su participación activa son prácticas que deben evitarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee0") }, {"long_answer": "En emergencias, el principio fundamental en salud mental para no aumentar el sufrimiento de la población afectada es mantener una comunicación respetuosa. Supone ofrecer información clara y veraz, escuchar activamente, respetar la dignidad, la cultura y las decisiones de las personas y evitar las actitudes paternalistas o invasivas. No comunicarse con la población aumenta la incertidumbre y la angustia. Incrementar el sufrimiento emocional es precisamente lo que se quiere evitar. Renunciar a la comprensión y a la escucha activa va en contra de los primeros auxilios psicológicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee1") }, {"long_answer": "Las radios locales y los sistemas de información son recursos de la propia comunidad que favorecen el bienestar emocional tras una catástrofe. Difunden información fiable sobre la situación, las ayudas y la localización de familiares, con lo que reducen la incertidumbre y los rumores, y además refuerzan el sentimiento de comunidad. Los hospitales equipados son necesarios para la atención sanitaria, pero no son el recurso comunitario que se señala para el bienestar emocional. Unos recursos financieros ilimitados no existen en la práctica. Las asociaciones de gobierno no son un recurso propio de la comunidad afectada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee3") }, {"long_answer": "El apoyo en salud mental en catástrofes se organiza en un sistema escalonado o de varios niveles, representado como una pirámide, para atender las distintas necesidades de las personas afectadas. La base incluye los servicios básicos y la seguridad, después vienen el apoyo comunitario y familiar y la atención focalizada no especializada, y en el vértice están los servicios especializados para los casos más graves. Así cada persona recibe la intensidad de ayuda que necesita. Retirarse después de unas semanas, evitar la planificación a largo plazo u ofrecer solo ayuda a corto plazo contradicen la necesidad de una atención continuada y sostenible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee6") }, {"long_answer": "Los programas específicos para niños en duelo en comunidades afectadas por catástrofes permiten identificar a los menores con reacciones de duelo complicado o con otros problemas de salud mental y derivarlos a servicios de mayor especialización cuando lo necesitan, además de ofrecerles un apoyo adaptado a su edad. Afirmar que no tienen importancia es falso, porque los niños son un grupo especialmente vulnerable. Crear espacios saludables de apoyo a la comunidad y realizar ceremonias de reconocimiento de las víctimas son intervenciones comunitarias generales, no la función propia de los programas dirigidos al duelo infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ee9") }, {"long_answer": "Los servicios especializados de salud mental que ya existían antes de la catástrofe tienen la función de proporcionar coordinación y apoyo a los nuevos equipos comunitarios que se crean para la respuesta, gracias a su conocimiento del territorio y de los recursos. Además, siguen atendiendo a los pacientes que ya tenían y a los casos graves. Mantenerse al margen de la atención a las personas afectadas va en contra de su papel. No gestionar las urgencias y emergencias ni cubrir las necesidades emergentes serían omisiones, porque precisamente deben asumir los casos graves y adaptarse a las nuevas demandas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976eeb") }, {"long_answer": "Las inundaciones aumentan la probabilidad de exposición a enfermedades infecciosas. El agua contaminada por aguas residuales y por la orina de animales puede transmitir gastroenteritis, hepatitis A o leptospirosis, el agua estancada favorece los vectores y las heridas se infectan con facilidad. Por eso las demás opciones son falsas. El riesgo de infección de heridas aumenta por el contacto con agua sucia y objetos punzantes. El riesgo de enfermedades de transmisión alimentaria crece porque se contaminan los alimentos y se interrumpe la cadena de frío. La disponibilidad de agua potable disminuye, porque se dañan las redes de abastecimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ef3") }, {"question": "¿Qué medidas de control se recomiendan para los casos no hospitalizados de mpox de clado II?", "option_3": "Reincorporarse a la vida social habitual en cuanto desaparezca la fiebre", "long_answer": "El protocolo del Ministerio de Sanidad recomienda a los casos no hospitalizados de mpox minimizar las interacciones sociales y abstenerse de mantener relaciones sexuales hasta que las lesiones hayan cicatrizado por completo, además de cubrir las lesiones y extremar la higiene. El aislamiento domiciliario no es obligatorio salvo que haya muchas lesiones que no puedan cubrirse. La mascarilla quirúrgica solo se recomienda si hay síntomas respiratorios, no en todo momento. Reincorporarse a la vida social habitual al desaparecer la fiebre es incorrecto, porque la persona sigue siendo contagiosa mientras persistan las lesiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976efa") }, {"long_answer": "Las recomendaciones de salud pública para prevenir la transmisión de la gripe aviar incluyen evitar el contacto con aves y otros animales que puedan estar infectados, reforzar las medidas de bioseguridad en las explotaciones (control de accesos, protección frente a las aves silvestres y uso de equipos de protección individual) y sensibilizar a los responsables de las explotaciones para que detecten y notifiquen precozmente los casos sospechosos. Las tres medidas se complementan y protegen tanto a los animales como a las personas expuestas. Por eso la respuesta correcta es «todas las anteriores son correctas»."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976efd") }, {"option_1": "Prevención de la obesidad", "long_answer": "La Estrategia en Enfermedades Neurodegenerativas establece que el plan de atención individualizada de las personas con ELA debe hacer un seguimiento especial de la prevención de caídas y lesiones. La debilidad muscular progresiva, la espasticidad y las alteraciones de la marcha aumentan mucho el riesgo de caídas y de sus consecuencias. La prevención de la obesidad no es un objetivo en la ELA, en la que es más frecuente la pérdida de peso y la desnutrición. La prevención de los trastornos neurológicos no tiene sentido en una enfermedad que ya lo es. La prevención de las enfermedades cardiacas no es un aspecto específico de su seguimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f00") }, {"option_4": "Proyectos financiados por el FIS", "long_answer": "La línea estratégica 3 de la Estrategia en Enfermedades Neurodegenerativas, dedicada a la atención a la persona cuidadora, incluye los programas de apoyo a las personas cuidadoras. Su objetivo es prevenir la sobrecarga, mejorar su calidad de vida y darles formación, respiro y apoyo psicológico y social. Fomentar la implicación de la población en los cuidados y elaborar un directorio de recursos sanitarios, rehabilitadores y sociales son acciones de otras líneas, relacionadas con la participación ciudadana y la coordinación de recursos. Los proyectos financiados por el FIS pertenecen a la línea de fomento de la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f03") }, {"option_1": "Campañas de concienciación a la población", "option_2": "Gestión de casos", "long_answer": "La línea estratégica 8 de la Estrategia en Enfermedades Neurodegenerativas, sobre el fomento de la investigación, incluye las actividades para potenciar la donación de tejido cerebral a los biobancos. Esa donación es imprescindible para estudiar los mecanismos de estas enfermedades y desarrollar nuevos tratamientos. Las campañas de concienciación a la población corresponden a la línea de participación ciudadana. La gestión de casos pertenece a la línea de coordinación sanitaria y social. El plan de formación forma parte de la línea de formación continuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f06") }, {"long_answer": "La característica clínica principal de la esclerosis lateral amiotrófica es la debilidad muscular progresiva, debida a la degeneración de las motoneuronas superior e inferior. Suele empezar de forma focal en una extremidad o en la musculatura bulbar y se extiende hasta afectar a la deambulación, la deglución, el habla y la respiración. La espasticidad y la hiperreflexia, propias de la motoneurona superior, así como la atrofia, los calambres y las fasciculaciones, propios de la inferior, acompañan a la debilidad, pero no son el rasgo principal. La pérdida de reflejos no es característica, porque suelen estar conservados o exaltados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f07") }, {"long_answer": "La esclerosis lateral amiotrófica suele empezar entre los 50 y los 60 años, que es la franja de inicio más frecuente según la Estrategia en Enfermedades Neurodegenerativas, y su incidencia aumenta con la edad. Aunque hay casos antes de los 40 años, sobre todo en las formas familiares, son minoritarios y no representan la edad media. Las franjas de 70 a 80 años y de más de 80 años quedan por encima de la edad media de inicio, aunque la enfermedad pueda diagnosticarse también en personas mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0a") }, {"long_answer": "La ELA tiene un impacto económico muy elevado que abarca todos los tipos de costes. Los costes directos médicos incluyen las hospitalizaciones, los fármacos, la ventilación mecánica, la gastrostomía y las consultas. Los costes directos no médicos incluyen los cuidados personales, las ayudas técnicas, la adaptación de la vivienda y el transporte. Los costes indirectos se deben a la pérdida de productividad de la persona afectada y de sus cuidadores familiares. Como la enfermedad causa una dependencia progresiva y total, ninguno de estos costes predomina por sí solo, así que la respuesta correcta es «todos los anteriores»."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773cb") }, {"question": "Según el Protocolo común del SNS ante la violencia sexual, ¿cómo se define el matrimonio forzado?", "option_3": "Matrimonio concertado por las familias en el que ambos contrayentes han dado su consentimiento libre y pleno", "long_answer": "El Protocolo común del SNS para la actuación sanitaria ante la violencia sexual define el matrimonio forzado como aquel en el que una o ambas partes no han expresado personalmente su consentimiento pleno y libre a la unión. Se considera una forma de violencia contra las mujeres y una vulneración de derechos humanos, porque anula la autonomía de la persona sobre su vida afectiva y sexual y suele asociarse a violencia sexual dentro de la unión. Las demás opciones describen matrimonios con consentimiento libre de ambas partes, incluido el concertado por las familias cuando los contrayentes lo aceptan libremente, que no constituyen matrimonio forzado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773cc") }, {"question": "¿Cómo se denomina la forma de violencia sexual que consiste en coaccionar a una persona, mediante la amenaza de difundir imágenes o información íntima, para obtener de ella actos sexuales, más material íntimo o dinero?", "long_answer": "La extorsión sexual (también llamada sextorsión) consiste en chantajear a la víctima con la amenaza de difundir imágenes, vídeos o información íntima para obtener de ella actos sexuales, nuevo material o dinero. Es una de las formas de violencia sexual recogidas en el marco internacional y en el Protocolo común del SNS, muy ligada al entorno digital. La distribución de pornografía no consentida es la difusión efectiva del material, sin que exista necesariamente chantaje. El acoso callejero son comentarios o conductas sexuales no deseadas en el espacio público, y los servicios sexuales forzados se relacionan con la explotación sexual y la trata, no con la amenaza de difusión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773cf") }, {"long_answer": "El GREVIO (Grupo de Expertos en la lucha contra la violencia contra las mujeres y la violencia doméstica) es el órgano independiente del Consejo de Europa encargado de supervisar la aplicación del Convenio de Estambul por los Estados Parte, mediante cuestionarios, visitas a los países e informes de evaluación con recomendaciones. La FRA es la Agencia de los Derechos Fundamentales de la Unión Europea, que investiga y asesora pero no supervisa este convenio. El IMLCF es el Instituto de Medicina Legal y Ciencias Forenses, servicio pericial de la Administración de Justicia en España. La COVIGE es la Comisión contra la Violencia de Género del Consejo Interterritorial del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773db") }, {"option_1": "Porque el embarazo actúa como factor protector frente a cualquier forma de violencia", "option_4": "Porque el embarazo puede ser un periodo en el que la violencia, incluida la sexual, se inicia o se intensifica, con riesgo para la mujer y para el feto", "long_answer": "El Protocolo común señala que el embarazo es un periodo de especial vulnerabilidad: la violencia de género, incluida la sexual, puede comenzar o agravarse durante la gestación y tiene consecuencias sobre la salud física, sexual, reproductiva y mental de la mujer y sobre el desarrollo fetal (abortos, bajo peso al nacer, parto prematuro). Por ello se pide a los profesionales que presten atención específica a la posible violencia sexual en las gestantes. Es falso que el embarazo proteja frente a la violencia, que las gestantes no sean vulnerables a la violencia sexual o que la vulnerabilidad del embarazo no guarde relación con ella."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773de") }, {"long_answer": "La OMS considera la violencia de género durante el embarazo especialmente preocupante porque puede tener consecuencias fatales para la mujer, como el homicidio o el suicidio, además de graves efectos sobre su salud física, sexual, reproductiva y mental y sobre el feto (aborto, parto prematuro, bajo peso al nacer). Las demás opciones son incorrectas: no se afirma que las gestantes tengan en general mayor tendencia al suicidio como motivo de la preocupación, sino que el suicidio puede ser un desenlace de la violencia; y es falso que la violencia de género no tenga impacto en la salud de la gestante o que carezca de consecuencias graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e0") }, {"long_answer": "El embarazo se considera un periodo de alto riesgo en el contexto de la violencia de género porque las mujeres gestantes pueden ser más vulnerables a sufrir violencia, incluida la sexual, que con frecuencia se inicia o se intensifica en esta etapa por los cambios en la relación, la mayor dependencia y el control del agresor. Esto obliga a extremar la detección en las consultas de seguimiento del embarazo. Las demás opciones son erróneas: el embarazo no aporta más recursos de protección, no aumenta la protección frente a la violencia de género y no se asocia a una mayor tendencia a abandonar a la pareja que reduzca el riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e2") }, {"question": "Según el Protocolo común del SNS ante la violencia sexual, ¿qué barreras dificultan especialmente que las mujeres con discapacidad identifiquen y denuncien la violencia?", "option_1": "El exceso de información accesible sobre los recursos de apoyo", "option_3": "La mayor credibilidad que se otorga a su testimonio", "option_4": "La ausencia de dependencia de terceras personas para los cuidados", "long_answer": "El Protocolo común identifica como barreras de las mujeres con discapacidad el desconocimiento de sus derechos y de los servicios de apoyo y recursos disponibles, así como el miedo a denunciar, que con frecuencia se relaciona con el temor a perder a la persona cuidadora de la que dependen, a no ser creídas o a sufrir represalias. A ello se suma una menor capacidad para resistirse a la manipulación emocional del agresor. Las demás opciones describen justo lo contrario de su situación: la información sobre recursos suele ser poco accesible, su testimonio tiende a cuestionarse y la dependencia de terceros para los cuidados es un factor de vulnerabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e3") }, {"question": "Según la Macroencuesta de Violencia contra la Mujer 2019, recogida en el Protocolo común del SNS ante la violencia sexual, ¿qué porcentaje de mujeres con discapacidad ha sufrido violencia sexual de alguna pareja?", "option_1": "6,2%", "option_2": "8,9%", "option_3": "14,8%", "option_4": "22,1%", "answer": 3, "long_answer": "Según la Macroencuesta de Violencia contra la Mujer 2019, citada en el Protocolo común del SNS, el 14,8% de las mujeres con discapacidad acreditada ha sufrido violencia sexual de alguna pareja actual o pasada, frente al 8,9% de las mujeres sin discapacidad, lo que refleja su mayor vulnerabilidad. El 8,9% corresponde precisamente a las mujeres sin discapacidad. El 22,1% es la proporción de mujeres con discapacidad afectadas por violencia de alguna expareja, y el 6,2% es la proporción de mujeres sin discapacidad que ha sufrido violencia sexual fuera de la pareja a lo largo de su vida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e4") }, {"option_2": "10,3%", "answer": 2, "long_answer": "Según la Macroencuesta de Violencia contra la Mujer 2019, recogida en el Protocolo común del SNS, el 10,3% de las mujeres con discapacidad acreditada ha sufrido violencia sexual fuera del ámbito de la pareja a lo largo de su vida, frente al 6,2% de las mujeres sin discapacidad. La diferencia evidencia que la discapacidad aumenta la vulnerabilidad frente a la violencia sexual por factores como la dependencia, el aislamiento o las dificultades de comunicación y acceso a recursos. Las cifras del 5%, 15% y 20% no se corresponden con los datos de la encuesta para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e9") }, {"long_answer": "La violencia de género en el medio rural se describe como un fenómeno oculto, invisible y estigmatizado porque la mayoría de los casos no llegan a denunciarse. Influyen el estricto control social de las comunidades pequeñas, donde todo el mundo se conoce, el aislamiento geográfico, la dispersión y la escasez de recursos especializados cercanos, el temor a la estigmatización y la dependencia económica. Las demás opciones son falsas: en el ámbito rural sí existen casos de violencia de género y las mujeres rurales son víctimas como las urbanas; tampoco es cierto que no haya ninguna forma de pedir ayuda, aunque el acceso a los recursos sea más difícil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ea") }, {"option_1": "26,3%", "option_2": "27,6%", "option_3": "33,1%", "option_4": "50%", "answer": 3, "long_answer": "Según la Macroencuesta de Violencia contra la Mujer 2019, citada en el Protocolo común del SNS, el 33,1% de las mujeres que residen en municipios de más de 10.000 habitantes ha sufrido algún tipo de violencia psicológica de alguna pareja. La prevalencia aumenta con el tamaño del municipio: en los de menos de 2.000 habitantes es del 26,3% y en los de 2.000 a 10.000 habitantes del 27,6%. Estas cifras menores en el medio rural no indican necesariamente menos violencia, sino que pueden reflejar mayor dificultad para reconocerla y declararla. El 50% no corresponde a ningún dato de la encuesta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773eb") }, {"long_answer": "Según los datos de la Asociación de Mujeres Víctimas de Agresiones Sexuales recogidos en el Protocolo común del SNS, el 65% de las personas encuestadas considera que en los municipios de menos de 10.000 habitantes las agresiones sexuales no se denuncian nunca o casi nunca. Esta percepción refleja la invisibilidad de la violencia sexual en el medio rural, donde el control social, el miedo al estigma, la falta de anonimato y la lejanía de los recursos dificultan la denuncia. Las cifras del 60%, 70% y 75% no se corresponden con el dato aportado por la asociación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ec") }, {"long_answer": "Según los datos del Ministerio del Interior recogidos en el Protocolo común del SNS, en torno al 50% de los agresores sexuales en el ámbito rural son de nacionalidad española. El dato desmonta el estereotipo de que la violencia sexual en los pueblos se debe principalmente a personas de fuera y recuerda que el agresor suele pertenecer al entorno próximo de la víctima, lo que se suma al control social para dificultar la denuncia. Las cifras del 30%, 40% y 60% no corresponden al dato que recoge el Protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ef") }, {"option_1": "La garantía de confidencialidad absoluta en los servicios de adicciones", "long_answer": "Uno de los factores que más desincentiva la denuncia de la violencia sexual en mujeres con problemas de adicción es el temor a ser juzgadas por su consumo. El doble estigma (ser mujer y consumidora) hace que teman que se las culpabilice de la agresión, que no se las crea o que se cuestione su capacidad como madres, lo que favorece el silencio. La confidencialidad de los servicios es un elemento facilitador, no una barrera. La falta de conciencia sobre la gravedad o la desconfianza en las leyes pueden existir, pero el Protocolo destaca el miedo al juicio por la adicción como factor específico de este colectivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f4") }, {"option_1": "Mejora de la densidad ósea", "option_3": "Disminución del riesgo de caídas", "option_4": "Aumento de la autonomía funcional", "long_answer": "La violencia de género en mujeres mayores puede ocasionar problemas de movilidad, consecuencia de lesiones, fracturas o del agravamiento de patologías previas, lo que reduce su autonomía y aumenta su dependencia del entorno, a veces del propio agresor. También se asocia a dolor crónico, ansiedad, depresión y aislamiento social. Las demás opciones son incorrectas porque describen efectos beneficiosos que la violencia no produce: no mejora la densidad ósea, no reduce el riesgo de caídas (más bien lo incrementa) y no aumenta la autonomía funcional, sino que la deteriora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f5") }, {"option_1": "Un mayor nivel de ingresos", "option_2": "La ausencia de enfermedades crónicas", "option_4": "Disponer de una red de apoyo social amplia", "long_answer": "En las mujeres mayores que sufren violencia sexual, la inestabilidad emocional (ansiedad, síntomas depresivos, miedo, sintomatología de estrés postraumático) es un factor que condiciona de forma importante su calidad de vida. Con la edad, estas secuelas se suman al aislamiento social, la dependencia y la dificultad para pedir ayuda, lo que agrava su impacto. Las demás opciones no son factores que empeoren la calidad de vida: un mayor nivel de ingresos, la ausencia de enfermedades crónicas y una red de apoyo social amplia actúan, al contrario, como factores protectores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f6") }, {"long_answer": "Según los datos del Ministerio de Sanidad (Sistema de Información sobre Nuevos Diagnósticos de VIH), en 2019 las mujeres supusieron el 14,2% de los nuevos diagnósticos de VIH en España, frente al 85,8% en hombres. Aunque son minoría, las mujeres presentan con frecuencia diagnóstico tardío y la transmisión es mayoritariamente heterosexual, por lo que la violencia sexual, que impide negociar prácticas seguras, constituye un factor de riesgo de infección. Por ello el Protocolo común incluye la profilaxis postexposición frente al VIH tras una agresión sexual. Las cifras del 10,5%, 18,6% y 22,8% no corresponden al dato de 2019."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773fc") }, {"question": "¿Cuál de los siguientes es un indicador de sospecha de violencia sexual facilitada por sumisión química en adolescentes?", "option_3": "Recordar con detalle todo lo ocurrido durante la noche", "long_answer": "Despertar al lado de una persona desconocida, en un lugar desconocido, o con la ropa desordenada o ausente sin recordar lo sucedido es un indicador característico de sospecha de violencia sexual facilitada por sumisión química, situación que el Protocolo común obliga a tener presente también en adolescentes. Ante esta sospecha deben recogerse muestras de sangre y orina para análisis toxicológico lo antes posible. Recordar con detalle lo ocurrido va en contra de la sospecha, ya que la amnesia es típica. La falta de lesiones físicas no descarta la agresión y es frecuente, y la presencia de un único indicador aislado no constituye por sí misma un indicador específico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773fd") }, {"answer": 1, "long_answer": "En la datación aproximada de hematomas y equimosis, la coloración negro-azul oscuro se observa entre el primer y el quinto día de evolución, cuando la hemoglobina extravasada se desoxigena. En las lesiones inmediatas, de un día o menos, predomina el color rojo. Hacia los 5-7 días aparece el tono verde, por la formación de biliverdina; entre los 7 y 10 días, el amarillo, por la bilirrubina; y a partir de las dos semanas la lesión suele desaparecer. Es una estimación orientativa, que depende de la profundidad, la localización y las características de la persona, por lo que debe describirse con prudencia en el informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ff") }, {"question": "En la atención sanitaria tras una agresión sexual, ¿cómo se debe actuar respecto a la hepatitis B (VHB)?", "option_1": "No está indicada ninguna actuación frente al VHB", "option_2": "Administrar de forma sistemática un tratamiento antiviral completo", "option_3": "Esperar al resultado de la serología a los 6 meses antes de actuar", "option_4": "Seguir las pautas comunes de profilaxis postexposición establecidas (vacunación y, si procede, inmunoglobulina)", "long_answer": "El Protocolo común indica que, ante una agresión sexual, la actuación frente al VHB debe seguir las pautas comunes de profilaxis postexposición establecidas: se valora el estado vacunal de la víctima y, si no está vacunada o la vacunación es incompleta, se inicia o completa la vacuna y, según el riesgo, se administra inmunoglobulina antihepatitis B, idealmente en las primeras 24 horas. No es correcto omitir la actuación, porque el riesgo de transmisión existe. Tampoco se administra un tratamiento antiviral completo de forma sistemática, y esperar seis meses a la serología haría perder la eficacia de la profilaxis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977410") }, {"long_answer": "Según el Protocolo común, la coordinación con el resto de recursos existentes en el servicio de salud y en la red de atención se realiza después de prestar la atención sanitaria, aportando la copia del Parte de Lesiones o informe al juzgado. Así se garantiza la continuidad asistencial (atención primaria, salud mental, servicios sociales, recursos especializados) sin demorar la atención inmediata, que es prioritaria. No se coordina antes de atender, porque eso retrasaría la asistencia, ni únicamente en situaciones de urgencia. La afirmación de que nunca se realiza coordinación es contraria al enfoque integral y multidisciplinar del Protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977411") }, {"long_answer": "Para acceder a los servicios de atención a víctimas de violencia sexual no es necesario cumplir ningún requisito previo. La asistencia sanitaria y los recursos especializados (como los centros de crisis 24 horas) se prestan con independencia de que la víctima haya denunciado, de su situación económica, administrativa o de su edad, conforme a la Ley Orgánica 10/2022 de garantía integral de la libertad sexual. Exigir una denuncia previa supondría una barrera que favorece la infradeclaración. Tampoco se requieren recursos económicos, y las menores de edad tienen igualmente derecho a la atención, con las garantías específicas de protección de la infancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977416") }, {"long_answer": "En las 72 horas siguientes a una agresión sexual se aplican los primeros auxilios psicológicos, una intervención breve centrada en proporcionar seguridad, calma, escucha activa sin presionar para que relate los hechos, información comprensible y conexión con su red de apoyo y con los recursos disponibles. Su objetivo es reducir el malestar inicial y prevenir la revictimización, no tratar un trastorno. El tratamiento psicológico y la terapia cognitivo-conductual se reservan para fases posteriores, si aparecen síntomas persistentes como el estrés postraumático. La intervención psicológica temprana es una fase posterior y más estructurada que la atención inmediata."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977420") }, {"long_answer": "El dolor, sangrado o secreción genital o anal sin explicación médica es un indicador físico altamente específico de agresión sexual infantil, porque es difícil atribuirlo a otras causas en un niño, niña o adolescente y obliga a una valoración inmediata y a la notificación. El retraimiento social, las fugas del hogar e incluso las conductas sexuales impropias para la edad pueden aparecer en otras situaciones de estrés o maltrato, por lo que se consideran indicadores inespecíficos que deben valorarse en conjunto. Las conductas sexualizadas tienen más peso, pero por sí solas no tienen la especificidad de las manifestaciones genitales o anales inexplicadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977423") }, {"option_3": "Infección de transmisión sexual no explicable por transmisión vertical", "option_4": "Presencia de semen en boca, ano o genitales", "long_answer": "Los trastornos del sueño y del apetito son indicadores inespecíficos de agresión sexual infantil: pueden aparecer en menores que sufren violencia sexual, pero también en muchas otras situaciones de estrés, enfermedad o problemas familiares, por lo que no permiten afirmarla y deben valorarse en conjunto. En cambio, las lesiones en zona genital, anal, perianal o senos, una infección de transmisión sexual no explicable por transmisión vertical y la presencia de semen en boca, ano o genitales son indicadores altamente específicos, que hacen muy probable la agresión y obligan a la notificación y a la actuación inmediata."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977424") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977425") }, {"long_answer": "Los trastornos psicosomáticos, como dolores abdominales recurrentes o cefaleas sin causa orgánica, se consideran indicadores inespecíficos de agresión sexual infantil, porque pueden deberse a muy diversas situaciones de estrés (conflictos familiares, acoso escolar, duelos). Su presencia obliga a explorar el contexto, pero no permite por sí sola establecer la agresión. Por eso no indican una altísima probabilidad de que la agresión haya ocurrido, rasgo propio de los indicadores altamente específicos. Tampoco son un trastorno del sueño o del apetito, y aisladamente no generan la obligación de notificar como sí ocurre ante la sospecha fundada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977427") }, {"option_2": "Que no descarta que los hechos hayan ocurrido", "long_answer": "El Protocolo común insiste en que la ausencia de uno o más de los indicadores altamente específicos no descarta que la agresión sexual haya ocurrido. Muchas agresiones no dejan lesiones físicas, las lesiones genitales cicatrizan rápido y en ocasiones el relato aparece de forma tardía, por lo que deben valorarse el conjunto de indicadores y el testimonio. Las demás opciones son incorrectas: esa ausencia no explica los dolores abdominales recurrentes, no confirma que el menor haya sido objeto de agresión y no define por sí misma un riesgo de desprotección grave, que exige una valoración específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742e") }, {"long_answer": "Según el documento del Proyecto Infección Quirúrgica Zero, el coste directo medio atribuible a cada infección del lugar quirúrgico se sitúa en torno a 17.944 dólares. Las ILQ prolongan la estancia hospitalaria, obligan a reintervenciones, tratamientos antibióticos y reingresos, y aumentan la morbimortalidad, lo que justifica económicamente la implantación de paquetes de medidas preventivas como el del Proyecto IQZ. Las cifras de 10.000, 25.000 y 30.500 dólares no se corresponden con el dato que recoge el Proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977433") }, {"long_answer": "Entre los objetivos específicos del Proyecto Infección Quirúrgica Zero figura mejorar la cultura de seguridad de los pacientes en los servicios quirúrgicos, junto con reducir la incidencia de infección del lugar quirúrgico mediante la aplicación de un paquete de medidas preventivas y crear una red de servicios que apliquen prácticas seguras. Las demás opciones son incorrectas: identificar y documentar toda la infección nosocomial no es su objetivo específico, ya que el proyecto se centra en la ILQ; aumentar la prevalencia de ILQ sería contrario al proyecto; y reducir el número de intervenciones quirúrgicas no forma parte de sus fines."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977436") }, {"long_answer": "En el Proyecto Infección Quirúrgica Zero, la antisepsia de la piel con clorhexidina alcohólica al 2% se recomienda con un nivel de evidencia alto, ya que ensayos clínicos y metaanálisis muestran que reduce la infección del lugar quirúrgico frente a la povidona yodada. Es una de las medidas del paquete básico del proyecto, que debe aplicarse dejando secar completamente el antiséptico antes de la incisión para evitar riesgos y asegurar su eficacia. Los niveles bajo, moderado o muy bajo no reflejan la calidad de la evidencia que el proyecto atribuye a esta medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743c") }, {"long_answer": "El Proyecto IQZ establece como formación mínima que todo el personal sanitario implicado en la atención quirúrgica realice el curso en línea STOP-ILQ, de modo que cirujanos, anestesistas, enfermeras y técnicos conozcan y apliquen de forma homogénea las medidas del paquete preventivo. La prevención de la infección del lugar quirúrgico es una responsabilidad compartida por todo el equipo, por lo que limitar la formación a médicos, a enfermeras o solo a cirujanos dejaría fuera a profesionales clave en la aplicación de medidas como la antisepsia, la normotermia o la profilaxis antibiótica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977441") }, {"long_answer": "En el Proyecto IQZ, la recogida diaria de los listados de verificación individuales consiste en recoger un documento específico por paciente en el que se registra si se han aplicado las medidas preventivas del paquete (profilaxis antibiótica adecuada, antisepsia con clorhexidina alcohólica, eliminación correcta del vello, normotermia y normoglucemia). Sirve para monitorizar el cumplimiento y retroalimentar al equipo. No se trata de recoger recetas, resultados de laboratorio ni historias clínicas completas, que no forman parte de este sistema de verificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977443") }, {"long_answer": "En la fase de post-implantación del Proyecto IQZ, la suspensión de los listados de verificación individuales indica que el protocolo se considera completamente implantado: las medidas del paquete se aplican ya de forma sistemática como parte de la práctica habitual del servicio, por lo que deja de ser necesario el registro paciente a paciente. La suspensión no responde a la existencia de errores en el rellenado de los listados ni tiene como finalidad principal reducir la carga de trabajo, aunque sea una consecuencia. El seguimiento continúa mediante la vigilancia de la tasa de infección del lugar quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977448") }, {"long_answer": "Para mantener la temperatura corporal y evitar la hipotermia perioperatoria inadvertida se propone, como medida de base, aumentar el aislamiento térmico del paciente: cubrirlo con mantas, sábanas o dispositivos aislantes y minimizar la superficie corporal expuesta, medidas pasivas que reducen la pérdida de calor. Si el riesgo es mayor o la temperatura desciende, se añaden medidas de calentamiento activo, como mantas de aire caliente o fluidos calentados. El aislamiento eléctrico no guarda relación con la termorregulación, aumentar la ventilación favorece la pérdida de calor y aumentar la presión arterial no es una intervención para mantener la temperatura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744c") }, {"option_4": "Exposición prolongada de la superficie corporal", "long_answer": "Para mantener o aumentar la temperatura corporal en el periodo perioperatorio se propone aumentar el aislamiento térmico del paciente, cubriéndolo con mantas o dispositivos aislantes y reduciendo la superficie expuesta, combinado si es necesario con calentamiento activo, como mantas de aire caliente o fluidos calentados. Exponer de forma prolongada la superficie corporal favorece la pérdida de calor y la hipotermia. Aumentar la ventilación incrementa la pérdida de calor por convección. Aumentar la presión arterial no es una intervención dirigida a la temperatura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744e") }, {"long_answer": "El ayuno preoperatorio prolongado produce una respuesta metabólica de estrés que favorece la resistencia a la insulina, el aumento de la glucemia (hiperglucemia postoperatoria) y el catabolismo proteico con desgaste muscular, además de deshidratación y malestar. Por ello todas las opciones son efectos adversos del ayuno prolongado, y los programas de recuperación intensificada recomiendan acortarlo: líquidos claros hasta 2 horas antes y sólidos hasta 6 horas antes de la anestesia, con bebidas carbohidratadas cuando estén indicadas. Elegir solo una de las opciones dejaría fuera efectos igualmente documentados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977452") }, {"long_answer": "La administración de bebidas carbohidratadas claras hasta 2 horas antes de la anestesia en adultos que van a cirugía mayor programada atenúa la respuesta metabólica al estrés quirúrgico, reduce la resistencia a la insulina postoperatoria y mejora el bienestar (menos sed, hambre y ansiedad), lo que se asocia a una mejor recuperación y a menos complicaciones postoperatorias. Por eso forma parte de los programas de recuperación intensificada. Las demás opciones son incorrectas: no aumenta la estancia hospitalaria, no aumenta la resistencia a la insulina, sino que la disminuye, y sí tiene efecto en los resultados postoperatorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977453") }, {"option_4": "Aumenta la resistencia a la insulina", "long_answer": "En los programas de recuperación intensificada, la administración preoperatoria de bebidas carbohidratadas (CHO) se asocia a una disminución de la estancia hospitalaria, porque atenúa la respuesta catabólica al estrés quirúrgico, reduce la resistencia a la insulina y favorece la recuperación de la función intestinal y la movilización precoz. Las demás opciones son incorrectas: sí tiene efecto, no aumenta las complicaciones postoperatorias en pacientes correctamente seleccionados y no aumenta la resistencia a la insulina, sino que la reduce, que es precisamente uno de sus beneficios metabólicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977455") }, {"long_answer": "En la cesárea se recomienda extraer la placenta mediante tracción controlada del cordón umbilical en lugar de extracción manual, porque así se reduce la pérdida hemática y el riesgo de endometritis. La extracción manual supone introducir la mano en la cavidad uterina, lo que aumenta la contaminación y el sangrado. La tracción controlada no aumenta el riesgo de endometritis, sino que lo reduce. Tampoco se asocia a más complicaciones de la herida quirúrgica ni a una mayor estancia hospitalaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745b") }, {"long_answer": "El Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores señala que su propagación se ve favorecida por el aumento de los viajes y del comercio internacional, que facilitan la introducción de vectores y patógenos, por el cambio climático, que amplía las zonas y temporadas favorables para los vectores, y por los cambios sociodemográficos y medioambientales, como la urbanización. Las demás opciones incluyen factores incorrectos: el aumento de la vigilancia no favorece la propagación, el comercio internacional no ha disminuido y el descenso de las temperaturas limita, en lugar de favorecer, la actividad de los vectores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745e") }, {"long_answer": "Los mosquitos del género Aedes, especialmente Ae. aegypti y Ae. albopictus, transmiten los virus del dengue, Zika, chikungunya y fiebre amarilla, todos ellos arbovirus. Por eso la respuesta correcta es la que agrupa estas cuatro enfermedades víricas. Las demás opciones incluyen la malaria, que no es una enfermedad vírica sino parasitaria, causada por protozoos del género Plasmodium, y que se transmite por la picadura de hembras de mosquitos del género Anopheles, no por Aedes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977462") }, {"long_answer": "Según el Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores, en España se han citado 24 especies autóctonas del género Aedes, además de las especies invasoras introducidas en las últimas décadas, como Ae. albopictus (mosquito tigre) y Ae. japonicus. Conocer esta diversidad es importante para la vigilancia entomológica, porque no todas las especies tienen la misma capacidad vectorial. Las cifras de 27, 21 y 20 especies no se corresponden con el dato del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977463") }, {"long_answer": "El Real Decreto 630/2013, que regula el Catálogo español de especies exóticas invasoras, incluye a Aedes albopictus, lo que implica la obligación legal de que las administraciones competentes adopten medidas de gestión, control y posible erradicación de esta especie. Esta obligación refuerza las actuaciones de vigilancia entomológica y control vectorial frente al mosquito tigre, vector de dengue, chikungunya y Zika. Las demás opciones son incorrectas: sí existe obligación legal, y esta no se limita a las comunidades autónomas ni excluye a las entidades locales, que tienen un papel clave en el control de criaderos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977465") }, {"option_4": "Sustituir la vigilancia entomológica por la vigilancia exclusiva de casos humanos", "long_answer": "El objetivo específico de la vigilancia entomológica de los mosquitos del género Aedes en el Plan Nacional es identificar su presencia y otros parámetros entomológicos (distribución, abundancia, estacionalidad) para estimar el riesgo de transmisión de enfermedades y orientar las medidas de control. La eliminación completa de los mosquitos no es un objetivo realista ni el fin de la vigilancia. Es falso que no existan objetivos específicos para la vigilancia entomológica. Sustituirla por la vigilancia exclusiva de casos humanos impediría detectar el riesgo antes de que aparezca la transmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977466") }, {"long_answer": "Aedes albopictus, el mosquito tigre, es la especie de Aedes invasora más relevante en Europa por su amplia distribución en el continente, incluida España desde 2004, por su gran capacidad de adaptación a entornos urbanos y por su competencia vectorial para dengue, chikungunya y Zika, responsable de brotes autóctonos europeos. Ae. aegypti tiene mayor capacidad vectorial pero actualmente solo está establecido en zonas muy limitadas de Europa, como Madeira y Chipre. Ae. japonicus y Ae. koreicus son invasoras de distribución más reducida y menor relevancia sanitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746e") }, {"long_answer": "La infección por virus Zika durante el embarazo puede transmitirse al feto y causar el síndrome de Zika congénito, que incluye microcefalia, calcificaciones cerebrales, alteraciones oculares, contracturas articulares y otras anomalías del desarrollo neurológico. Por ello se recomienda a las gestantes evitar viajar a zonas con transmisión activa. Las demás opciones son manifestaciones de la infección aguda en el adulto (cefalea, fiebre moderada y exantema maculopapular), habitualmente leves y autolimitadas, que no constituyen la enfermedad asociada a la microcefalia fetal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977471") }, {"option_4": "Centralizar todas las actuaciones exclusivamente en la Administración General del Estado", "long_answer": "La coordinación en la prevención, vigilancia y control de las enfermedades transmitidas por Ae. albopictus persigue favorecer la participación de todas las administraciones y agentes implicados (salud pública, medio ambiente, entidades locales, sanidad animal, sociedad civil) en la elaboración de los planes, de modo que las actuaciones sean integradas y coherentes. Aumentar la población susceptible es contrario a los fines del plan. La eliminación completa del vector no es un objetivo realista. Centralizar las actuaciones en un único nivel de la Administración contradice el enfoque coordinado y multisectorial que propone el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a8") }, {"long_answer": "La recomendación fuerte en pacientes quirúrgicos es aplicar un método eficaz de prevención de complicaciones trombóticas, tras valorar el riesgo tromboembólico y hemorrágico de cada paciente. Según ese riesgo se elige profilaxis farmacológica (heparinas), mecánica (medias de compresión, compresión neumática intermitente) o ambas. Valorar individualmente las dosis de heparina forma parte de la aplicación de la profilaxis, pero no es la recomendación fuerte en sí. Es incorrecto afirmar que no es necesario valorar el riesgo y que no exista ninguna recomendación, porque la tromboprofilaxis es una práctica segura de evidencia consolidada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773aa") }, {"option_3": "Se recomienda su uso solo en pacientes con trombosis venosa ya diagnosticada", "long_answer": "Para la prevención de la trombosis venosa en pacientes quirúrgicos se recomienda el uso de medias de compresión, preferiblemente graduadas y hasta la cadera o el muslo, ya que ofrecen mayor protección que las que llegan solo a la rodilla. Pueden emplearse solas o combinadas con profilaxis farmacológica, según el riesgo del paciente. Es incorrecto que no se recomienden. Tampoco están indicadas para todos los pacientes, pues existen contraindicaciones, como la arteriopatía periférica grave. Su papel es preventivo, por lo que no se limita a pacientes con trombosis ya diagnosticada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ab") }, {"long_answer": "Los fármacos contemplados clásicamente para la profilaxis de la trombosis venosa en pacientes quirúrgicos son las heparinas no fraccionadas (HNF) y las heparinas de bajo peso molecular (HBPM), estas últimas las más utilizadas hoy por su administración subcutánea una vez al día y su menor riesgo de trombocitopenia. Los antibióticos y los esteroides no tienen efecto antitrombótico. Los antiinflamatorios no esteroideos tampoco son tratamientos de profilaxis tromboembólica, y los anticoagulantes orales no forman parte de la pauta clásica en este contexto, aunque algunos nuevos anticoagulantes se usan en cirugía ortopédica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ac") }, {"long_answer": "El estado nutricional de los pacientes quirúrgicos puede empeorar por tres mecanismos: la propia enfermedad primaria, que con frecuencia reduce la ingesta o aumenta el catabolismo; la cirugía en sí misma, que desencadena una respuesta metabólica al estrés con catabolismo proteico; y los largos periodos de ayuno perioperatorio. Las demás opciones mezclan elementos incorrectos: la reducción del estrés no empeora la nutrición, la preparación intestinal no es un mecanismo general, y la resistencia a la insulina y la hiperglucemia son consecuencias del ayuno y del estrés quirúrgico, no mecanismos de deterioro nutricional en sí."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ad") }, {"long_answer": "El documento señala que el ayuno prolongado tiene como efectos fisiológicos adversos la deshidratación, la resistencia a la insulina y la hiperglucemia postoperatoria, que empeoran la respuesta al estrés quirúrgico y la recuperación. Por eso se recomienda limitar el ayuno a 2 horas para líquidos claros y 6 horas para sólidos. El hambre, la sed, la somnolencia o los mareos son molestias subjetivas, no los efectos fisiológicos destacados. Las hormonas de estrés, los mediadores inflamatorios y el catabolismo forman parte de la respuesta a la propia cirugía, y no son los efectos que se atribuyen específicamente al ayuno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b0") }, {"long_answer": "Las sociedades europeas y americanas de anestesiología recomiendan un ayuno preoperatorio de 2 horas para líquidos claros (agua, zumos sin pulpa, infusiones o bebidas carbohidratadas) y de 6 horas para sólidos o comidas ligeras en pacientes sin factores de riesgo de aspiración. Este ayuno corto es seguro y evita la deshidratación, la resistencia a la insulina y el malestar del ayuno prolongado. El ayuno desde medianoche es una práctica tradicional sin respaldo en la evidencia. Los ayunos de 8 o 12 horas también para los líquidos claros son innecesariamente prolongados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b8") }, {"long_answer": "La ropa específica con la que el paciente acude al quirófano debe permitir el acceso al lugar de la intervención quirúrgica, así como la monitorización y los accesos vasculares, sin necesidad de desvestir completamente al paciente. Esto preserva su intimidad y su temperatura, ayudando a prevenir la hipotermia. No debe ser la ropa habitual del paciente, que puede estar contaminada y dificultar el acceso. Sí es necesaria una ropa específica. No se exige que sea estéril, ya que la esterilidad se garantiza con la preparación de la piel y los campos quirúrgicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ba") }, {"long_answer": "Se recomienda preparar la piel del campo quirúrgico antes de la incisión con clorhexidina, preferentemente en solución alcohólica al 2%, porque reduce la infección del lugar quirúrgico frente a la povidona yodada, gracias a su acción rápida y su efecto residual. Debe dejarse secar completamente antes de aplicar los campos y usar bisturí eléctrico, por el riesgo de incendio. El yodo (povidona yodada) es una alternativa si hay contraindicación a la clorhexidina, pero no es la opción preferente. El agua y el jabón no sustituyen a la antisepsia, y omitir la preparación de la piel aumentaría el riesgo de infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773bd") }, {"long_answer": "Las recomendaciones sobre indumentaria del personal de quirófano establecen que el equipo que participa directamente en el campo quirúrgico debe usar ropa quirúrgica estéril (bata y guantes estériles), junto con gorro y mascarilla, para crear una barrera frente a la contaminación microbiológica de la herida. El resto del personal debe llevar ropa específica de quirófano. Es incorrecto que no sean necesarios el gorro y la mascarilla, que no existan recomendaciones o que cada profesional pueda usar la ropa que desee, ya que todo ello incrementaría el riesgo de infección del lugar quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773bf") }, {"long_answer": "Respecto a la irrigación subcutánea de la herida durante la intervención, la evidencia revisada no ha mostrado diferencias en la incidencia de infección de herida quirúrgica entre la irrigación con suero salino y con antibiótico, por lo que no se recomienda la irrigación con antibiótico, que añade coste y riesgo de resistencias sin beneficio demostrado. No se afirma que el salino esté contraindicado, ni que la irrigación con antibiótico sea más eficaz. Tampoco se ha demostrado que la irrigación aumente la incidencia de infección de herida quirúrgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c7") }, {"option_2": "Cualquier intervención quirúrgica genital realizada por indicación médica", "long_answer": "La OMS define la mutilación genital femenina como todos los procedimientos que implican la ablación parcial o total de los genitales externos femeninos, u otras lesiones de los órganos genitales, por motivos no terapéuticos. Es una violación de los derechos humanos de niñas y mujeres que provoca complicaciones inmediatas y a largo plazo. La extirpación total es solo uno de los tipos. Las intervenciones genitales con indicación médica no son mutilación. La falta de consentimiento no define la MGF, ya que se considera tal aunque la mujer la acepte, al no existir finalidad terapéutica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ce") }, {"option_2": "Violencia física y económica únicamente", "option_3": "Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad", "long_answer": "El artículo 1.3 de la Ley Orgánica 1/2004 establece que la violencia de género comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad, ejercida sobre las mujeres por quienes sean o hayan sido sus cónyuges o hayan estado ligados a ellas por relaciones similares de afectividad. Las demás opciones son incorrectas porque reducen la definición a la violencia física y psicológica sin incluir las agresiones sexuales ni las coacciones, la limitan a la violencia física y económica o la circunscriben solo a la violencia sexual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d3") }, {"long_answer": "El Protocolo común señala que los contextos sociales y culturales confluyen entre sí agudizando los condicionantes de bienestar y aumentando la vulnerabilidad de las mujeres a sufrir violencia de género. Las normas de género, los estereotipos, la discriminación por origen, discapacidad, edad o ruralidad y la desigualdad estructural interactúan desde una perspectiva interseccional. Los contextos económicos y políticos influyen, pero el Protocolo destaca la confluencia social y cultural. Los contextos climáticos y ambientales y los tecnológicos y digitales no se señalan como los ejes que agudizan esa vulnerabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d4") }, {"long_answer": "El Protocolo común de actuación sanitaria ante la violencia de género define la violencia contra las mujeres como un problema estructural y cultural, arraigado en la desigualdad de poder entre hombres y mujeres y en normas sociales que la toleran, no como hechos aislados. Por eso exige un abordaje integral, desde la prevención y la detección precoz hasta la atención y la coordinación intersectorial, en el que los servicios sanitarios tienen un papel clave. Considerarla un problema individual y puntual, un fenómeno aislado o un asunto exclusivamente legal ignora sus raíces sociales y su impacto en la salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d7") }, {"long_answer": "La OMS considera que la violencia de género durante el embarazo puede provocar consecuencias graves para la salud física, sexual, reproductiva y mental de la mujer, además de efectos sobre el feto, como el aborto, el parto prematuro o el bajo peso al nacer, e incluso desenlaces fatales para la madre. Por eso recomienda integrar su detección en el control prenatal. Las demás opciones son falsas: la OMS sí la considera un problema relevante durante la gestación, reconoce su impacto en la salud física y mental y advierte de que puede tener consecuencias fatales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d9") }, {"long_answer": "El Protocolo común señala que es difícil recoger datos sobre la incidencia de la violencia de género durante el embarazo y el puerperio por las dificultades que ofrece su registro en las bases de datos comunes: los sistemas de información no siempre vinculan la violencia con la situación de gestación o puerperio, y los episodios quedan dispersos entre distintos niveles asistenciales. La reticencia a denunciar contribuye a la infradeclaración, pero no es la razón que el Protocolo destaca. Es falso que no existan casos en esta etapa, y la dificultad no se atribuye a la falta de interés de las autoridades sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773dc") }, {"option_1": "21,3% de violencia periembarazo", "long_answer": "El Protocolo común recoge que, en 2014, Velasco et al. señalaron una prevalencia del 21,3% de violencia periembarazo, es decir, de violencia sufrida por la mujer durante la gestación o en el periodo que la rodea. El dato muestra que el embarazo no protege frente a la violencia de género y que esta puede iniciarse o intensificarse en esta etapa, lo que justifica la detección sistemática en el control prenatal y en el puerperio. Las cifras del 40% de violencia física, el 12% de violencia psicológica y el 7,5% de violencia económica no corresponden a los datos de este estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773dd") }, {"option_4": "Entre el 2% y el 13%", "long_answer": "El Protocolo común recoge que diversos estudios sitúan la prevalencia de la violencia de género en mujeres gestantes a nivel mundial entre el 2% y el 13%, con amplia variabilidad según el país, la definición de violencia y el método de recogida de datos. Aunque las cifras puedan parecer bajas, probablemente están infraestimadas por la infradeclaración y las dificultades de registro, y sus consecuencias sobre la madre y el feto son graves. Los rangos del 20-30%, 30-40% y 50-60% no corresponden a la prevalencia que recogen estos estudios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e1") }, {"long_answer": "Durante el embarazo es necesario prestar especial atención a los signos y síntomas derivados de la violencia de género porque las gestantes pueden ser sometidas a violencia, también sexual, que con frecuencia se inicia o se intensifica en esta etapa y que repercute en la salud materna y fetal. Las visitas de control prenatal ofrecen una oportunidad privilegiada para detectarla. Es falso y estigmatizante suponer que las embarazadas exageran sus síntomas. No tienen más probabilidad de denunciar, sino que la dependencia y el miedo suelen dificultarlo. Y la violencia sí tiene un impacto importante en su salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e5") }, {"option_2": "Debido a que disponen de una red de apoyo más amplia que otras mujeres", "option_3": "Debido a su mayor independencia económica respecto a la familia", "option_4": "Debido a que pasan menos tiempo en el entorno doméstico", "long_answer": "El Protocolo común explica que la discapacidad sitúa a las mujeres en mayor vulnerabilidad frente a la violencia en el hogar por cómo se maneja su autonomía y su libertad en los distintos ámbitos vitales: con frecuencia otras personas toman decisiones por ellas, controlan su dinero, su movilidad o su vida afectiva y sexual, y dependen de terceros para los cuidados, lo que facilita el abuso y dificulta su denuncia. Las demás opciones describen situaciones contrarias a la realidad de muchas mujeres con discapacidad, como una amplia red de apoyo, independencia económica o menor permanencia en el hogar, que serían factores protectores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e8") }, {"option_2": "10,5%", "long_answer": "Según la Macroencuesta de Violencia contra la Mujer 2019, recogida en el Protocolo común, el 10,5% de las mujeres que viven en municipios de menos de 2.000 habitantes ha sufrido violencia física y/o sexual de alguna pareja, frente al 12,5% en municipios de 2.000 a 10.000 habitantes y el 14,8% en los de mayor tamaño. Que las cifras sean algo menores en el medio rural no implica necesariamente menos violencia, ya que el control social, el aislamiento y la dispersión dificultan reconocerla y denunciarla. Las cifras del 5%, 15% y 20% no corresponden a este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ed") }, {"long_answer": "La atención y el acompañamiento a las víctimas en el ámbito rural son esenciales para garantizar que puedan salir de su situación de violencia, ya que en estos entornos se enfrentan al control social, el aislamiento, la dispersión geográfica, la falta de anonimato y la lejanía de los recursos especializados. Por eso el Protocolo propone facilitar la denuncia y el seguimiento desde lugares distintos a su lugar de residencia y con estricta confidencialidad. Las opciones sobre beneficios económicos o detención de las víctimas son absurdas. La prevención es un objetivo distinto, previo a la violencia, mientras que el acompañamiento se dirige a quien ya la sufre."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f8") }, {"long_answer": "Según la Macroencuesta de Violencia contra la Mujer 2019, recogida en el Protocolo común, el 5,6% de las mujeres mayores que han sufrido violencia sexual de su pareja ha contraído alguna infección de transmisión sexual como consecuencia. El dato recuerda que en las mujeres mayores también deben valorarse las ITS y ofrecer cribado y profilaxis tras una agresión sexual, sin presuponer que la edad excluye la actividad sexual o el riesgo de infección. Las cifras del 3,4%, 7,8% y 9,2% no corresponden al dato que recoge el Protocolo para este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977402") }, {"long_answer": "El Protocolo común indica que debe registrarse en la historia clínica la información completa sobre las exploraciones y los procedimientos sanitarios realizados para facilitar el seguimiento médico de la víctima, garantizando la continuidad asistencial entre profesionales y niveles (profilaxis, serologías, controles, apoyo psicológico) y evitando repetir exploraciones que la revictimizarían. Las pruebas forenses se documentan en el informe o parte de lesiones y en la cadena de custodia, no son la finalidad de la historia clínica. La confidencialidad es una obligación que debe respetarse en el registro, pero no su objetivo, y la estadística es un uso secundario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977403") }, {"long_answer": "En la atención a una agresión sexual, las medidas profilácticas y terapéuticas (anticoncepción de urgencia, profilaxis de ITS, VIH y hepatitis B, tratamiento de lesiones) se aplican tras la valoración médica, una vez realizadas la anamnesis, la exploración y, si procede, la toma de muestras forenses conjunta. Así no se interfiere con la obtención de pruebas y se indica la profilaxis adecuada según el riesgo, siempre dentro de los plazos de eficacia. No se aplican antes de la exploración, porque se podrían alterar las muestras. Tampoco hay que esperar al ingreso hospitalario o al alta, ya que la mayoría de los casos no requiere ingreso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977405") }, {"question": "En la atención hospitalaria a una persona que ha sufrido una agresión sexual y presenta lesiones que comprometen su estado de salud, ¿cuál es la actuación prioritaria?", "option_1": "Estabilizarla clínicamente antes de cualquier otra actuación", "option_2": "Realizar la toma de muestras forenses antes de tratar las lesiones", "option_3": "Derivarla a la consulta de Ginecología sin valoración previa", "option_4": "Esperar a la llegada del médico forense para iniciar cualquier asistencia", "answer": 1, "long_answer": "Si la persona agredida presenta lesiones que comprometen su salud, la prioridad es su estabilización clínica, antes de cualquier otra actuación. La atención sanitaria urgente prevalece sobre la recogida de pruebas, que se realizará en cuanto la situación lo permita y procurando preservar los indicios. No se debe retrasar el tratamiento para tomar muestras forenses ni esperar al médico forense para iniciar la asistencia, ya que se pondría en riesgo la vida o la salud de la víctima. Derivarla a Ginecología sin una valoración previa también podría pasar por alto lesiones graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977408") }, {"long_answer": "En el seguimiento tras una agresión sexual con profilaxis postexposición, el Protocolo común establece que la segunda visita a Medicina Interna o a la Unidad de Enfermedades Infecciosas se realiza a las 6 semanas de la agresión. En ella se repiten las serologías (VIH, VHB, VHC, sífilis), se valora la tolerancia y adherencia al tratamiento y se revisa la pauta vacunal. Posteriormente se realizan nuevos controles serológicos a los 3 y 6 meses. Al mes, a los 10 días o al año no son los momentos establecidos para esta segunda visita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977413") }, {"long_answer": "Según el Protocolo común, los recursos existentes en cada comunidad autónoma para la acogida de la mujer, como las casas de acogida y los centros de emergencia, se activan después del alta hospitalaria cuando la mujer no dispone de un lugar seguro donde vivir, para evitar que vuelva al entorno del agresor. Se coordinan con los servicios sociales y los recursos especializados en violencia contra las mujeres. No se espera un plazo fijo, como un mes, y no se activan antes de la atención sanitaria, que es prioritaria. Afirmar que nunca se activan contradice el enfoque integral del Protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977414") }, {"long_answer": "Cuando se requiere información más específica sobre recursos, servicios y prestaciones sociales, el Protocolo indica acudir a los servicios especializados de atención a las mujeres víctimas de violencia de género, como los centros de crisis, los centros de la mujer o el teléfono 016, que asesoran sobre ayudas, alojamiento, orientación jurídica y apoyo psicológico. La Policía Nacional se ocupa de la protección y la denuncia, no de informar sobre prestaciones sociales. El Ministerio de Justicia no es un recurso de atención directa. Las Oficinas de Asistencia a las Víctimas de delitos informan sobre el proceso judicial, no sobre el conjunto de recursos sociales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741f") }, {"long_answer": "La violencia sexual en la infancia y la adolescencia se asocia a trastornos mentales, entre los que destaca el trastorno de estrés postraumático, con reexperimentación, evitación e hiperactivación, que puede acompañarse de ansiedad, depresión, conductas autolesivas o consumo de sustancias, a corto y largo plazo. Las demás opciones no son trastornos mentales: la dificultad para andar o sentarse y el dolor, sangrado o secreción genital o anal sin explicación son indicadores físicos de la agresión. La promiscuidad en adolescentes puede ser un indicador conductual inespecífico, no un diagnóstico de salud mental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977429") }, {"long_answer": "El Protocolo común establece que, en niñas, niños y adolescentes, las actuaciones que contribuyen al diagnóstico de la agresión sexual (entrevista, exploración y toma de muestras) se rigen por el criterio de la mínima intervención: deben realizarse una sola vez, de forma conjunta entre profesionales sanitarios y forenses y en un entorno adecuado, para evitar la victimización secundaria. Garantizar la atención integral y multidisciplinar, promover las medidas de atención inmediata y evitar demoras innecesarias son principios generales de la atención, pero no las actuaciones a las que se aplica específicamente el criterio de mínima intervención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742b") }, {"long_answer": "La infección del lugar quirúrgico (ILQ) es la infección relacionada con el procedimiento quirúrgico que aparece en la incisión, superficial o profunda, o en el órgano o espacio manipulado durante la intervención, en los 30 días siguientes, o hasta 90 días si se ha implantado material protésico, según los criterios del ECDC y los CDC. No es cualquier infección adquirida en el hospital, que sería el concepto más amplio de infección nosocomial. Una infección ya presente antes de la intervención no se considera ILQ. Tampoco se define por un agente patógeno concreto, ya que puede deberse a microorganismos muy diversos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977430") }, {"long_answer": "Según la evidencia recogida en el Proyecto Infección Quirúrgica Zero, la antisepsia de la piel con clorhexidina alcohólica (CA) ha demostrado una elevada efectividad preventiva de la infección del lugar quirúrgico en la histerectomía abdominal, superior a la de la povidona yodada (PVI), por su rápida acción y su efecto residual. Por ello forma parte del paquete de medidas del proyecto. La mascarilla quirúrgica y los guantes estériles son medidas generales de asepsia en todo procedimiento, pero no son las que se destacan por su efectividad preventiva específica en este tipo de cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977439") }, {"long_answer": "En el Proyecto Infección Quirúrgica Zero, el mantenimiento de la normoglucemia perioperatoria figura entre las medidas del paquete preventivo y el proyecto le asigna un nivel de evidencia alto, porque la hiperglucemia perioperatoria, tanto en pacientes diabéticos como no diabéticos, se asocia de forma consistente a un mayor riesgo de infección del lugar quirúrgico. Por eso el proyecto recomienda controlar la glucemia y mantenerla por debajo de los umbrales establecidos durante el perioperatorio. Los niveles bajo, moderado y muy bajo no se corresponden con la calificación que el proyecto da a esta medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977445") }, {"option_2": "Disminución del riesgo de infección de la herida quirúrgica", "long_answer": "La hipotermia perioperatoria inadvertida, con temperatura central inferior a 36 ºC, puede provocar coagulopatía, porque el frío altera la función plaquetaria y la actividad de los factores de coagulación, aumentando el sangrado y la necesidad de transfusión. También se asocia a eventos cardíacos, mayor riesgo de infección del lugar quirúrgico, temblor, disconfort y retraso en la recuperación anestésica. No disminuye el riesgo de infección, sino que lo aumenta por la vasoconstricción. Tampoco produce hipertensión arterial como complicación característica, y el frío reduce el metabolismo en lugar de aumentarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977446") }, {"long_answer": "Durante la anestesia general o neuroaxial, la temperatura central se monitoriza mediante sondas térmicas colocadas en el esófago, la nasofaringe, la boca o la vejiga, que reflejan con fiabilidad la temperatura del núcleo corporal y permiten detectar precozmente la hipotermia. Las sondas cutáneas miden la temperatura periférica, influida por el ambiente y la vasoconstricción, por lo que no son fiables como medida central. Una sonda en la nariz sin llegar a la nasofaringe no es una localización válida. El termómetro en el dedo mide la temperatura periférica, no la central."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744a") }, {"option_4": "Por la administración de fluidos intravenosos calentados", "long_answer": "La hipotermia perioperatoria inadvertida se produce porque la anestesia altera la termorregulación y redistribuye el calor del núcleo a la periferia. A ello se suman la exposición del cuerpo en un ambiente frío y la infusión de grandes volúmenes de líquidos intravenosos o de irrigación a temperatura ambiente, que enfrían al paciente. Por eso se recomienda calentar los fluidos cuando se administran volúmenes elevados. Administrar fluidos calentados es una medida preventiva, no una causa. La falta de calefacción o la ropa inadecuada pueden contribuir, pero no son las causas fundamentales que describe la guía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744d") }, {"long_answer": "Se recomienda un ayuno preoperatorio de 2 horas para líquidos claros (agua, infusiones, zumos sin pulpa o bebidas carbohidratadas) y de 6 horas para alimentos sólidos o comidas ligeras en pacientes sin riesgo aumentado de aspiración. Este ayuno es suficiente para el vaciamiento gástrico y evita los efectos adversos del ayuno prolongado, como la deshidratación, la resistencia a la insulina o el malestar. Los esquemas de 6 horas para líquidos y 12 para sólidos, o de 8 y 14 horas, prolongan el ayuno de forma innecesaria. Suprimir el ayuno aumentaría el riesgo de broncoaspiración durante la anestesia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977454") }, {"long_answer": "En la cesárea programada se recomienda administrar bebidas carbohidratadas preoperatorias a las pacientes sin diabetes, al igual que en otros programas de recuperación intensificada, porque reducen la resistencia a la insulina, la sed y la ansiedad y favorecen la recuperación. En las pacientes diabéticas no se recomiendan, por el riesgo de hiperglucemia y por la posibilidad de un vaciamiento gástrico enlentecido. Es incorrecto que no se recomienden en absoluto. La alergia a la penicilina no guarda relación con esta medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977456") }, {"long_answer": "En la cesárea se recomienda extraer la placenta mediante tracción controlada del cordón umbilical en lugar de la extracción manual, porque esta última aumenta la pérdida hemática y el riesgo de endometritis al introducir la mano en la cavidad uterina. Por tanto, la extracción manual no debe hacerse siempre. Afirmar que no se recomienda en absoluto o que no es necesaria es impreciso, ya que la extracción manual puede ser necesaria si la placenta no se desprende, pero la recomendación general es la tracción controlada del cordón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745c") }, {"question": "¿Qué organismos internacionales impulsan conjuntamente el enfoque de «Una Sola Salud» (One Health)?", "option_1": "OMS, FAO, OMSA (antigua OIE) y PNUMA", "option_2": "OMS, UNICEF y OMC", "option_3": "FAO, OCDE y Banco Mundial", "option_4": "OMS, ACNUR y OIT", "answer": 1, "long_answer": "El enfoque de «Una Sola Salud» reconoce que la salud humana, la animal y la de los ecosistemas están interrelacionadas. Lo impulsan conjuntamente la OMS, la FAO, la OMSA (Organización Mundial de Sanidad Animal, antigua OIE) y el PNUMA, que forman la alianza cuatripartita. Es especialmente relevante en las enfermedades transmitidas por vectores y en las zoonosis, que requieren coordinar la vigilancia humana, la veterinaria y la ambiental. UNICEF, la OMC, la OCDE, el Banco Mundial, ACNUR y la OIT no forman parte de esta alianza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745d") }, {"long_answer": "El objetivo general del Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores es reducir la carga y la amenaza que suponen las enfermedades humanas transmitidas por vectores en España. Mejorar la respuesta a nivel estatal, reforzar los mecanismos de coordinación y comunicación entre agentes y administraciones y velar por que las comunidades autónomas desarrollen sus propios planes son objetivos específicos o instrumentos del Plan. Todos ellos están al servicio de ese objetivo general, pero no lo constituyen por sí mismos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977468") }, {"question": "¿Cuál es aproximadamente el periodo de incubación extrínseco del virus del dengue en el mosquito Aedes?", "option_1": "1-2 días", "option_2": "8-12 días", "option_3": "30-40 días", "option_4": "Más de 2 meses", "answer": 2, "long_answer": "El periodo de incubación extrínseco es el tiempo que transcurre desde que el mosquito ingiere sangre infectada hasta que el virus se ha replicado y alcanza las glándulas salivales, de modo que el mosquito puede transmitirlo. En el caso del dengue en mosquitos Aedes es de aproximadamente 8 a 12 días, y se acorta con temperaturas elevadas. A partir de entonces el mosquito puede transmitir el virus durante el resto de su vida. Uno o dos días es demasiado corto para la replicación viral. Los periodos de 30-40 días o de más de dos meses superan la vida media del mosquito adulto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977469") }, {"long_answer": "La principal vía de transmisión del virus del dengue a los humanos es la picadura de hembras de mosquitos Aedes infectadas, sobre todo Ae. aegypti y, en menor medida, Ae. albopictus, presente en España, donde ya se han detectado casos autóctonos. Por eso la prevención se centra en el control del vector y en la protección frente a las picaduras. La transmisión por transfusión sanguínea, la transmisión sexual o el contacto con material infectado, como en accidentes de laboratorio, son posibles pero excepcionales, y no constituyen la vía principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746c") }, {"long_answer": "La fiebre de chikungunya es endémica en zonas de África, del sudeste asiático y del subcontinente indio, y desde 2013 se ha extendido a América y el Caribe. Se transmite por mosquitos Aedes, y Ae. albopictus ha causado brotes autóctonos en Europa (Italia y Francia), lo que justifica la vigilancia en España. Europa no es una región endémica: allí solo se han registrado casos importados y brotes autóctonos puntuales. América del Norte no se considera endémica, y en la Antártida no existen vectores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977472") }, {"option_2": "Restringir la información a los profesionales sanitarios para evitar la alarma social", "option_3": "Sustituir la vigilancia entomológica por campañas informativas", "option_4": "Limitar la comunicación a las situaciones de emergencia declaradas", "long_answer": "En el Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores, la comunicación busca difundir información relevante tanto a los profesionales como a la población general, para que conozcan el riesgo, las medidas de prevención individual y comunitaria (eliminación de criaderos, protección frente a picaduras) y los signos de alarma. Restringir la información a los profesionales iría en contra de la participación ciudadana que promueve el Plan. La comunicación complementa la vigilancia entomológica, no la sustituye. Tampoco debe limitarse a las emergencias, porque la prevención exige una comunicación continuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977473") }, {"long_answer": "Uno de los objetivos de la gestión integrada del vector en el Plan Nacional es contribuir a prevenir, controlar o eliminar el vector de forma eficiente, combinando medidas ambientales (eliminación de criaderos), biológicas, químicas solo cuando sea necesario y de educación comunitaria, con criterios de eficacia y sostenibilidad. Detectar precozmente los casos importados y autóctonos corresponde a la vigilancia epidemiológica. Conocer la presencia del vector y detectar la entrada de especies invasoras corresponde a la vigilancia entomológica. La evaluación del riesgo de transmisión es otra línea del Plan, distinta de la gestión del vector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977478") }, {"long_answer": "Entre las especies de mosquitos invasoras en Europa, Aedes japonicus se considera más rural y selvática que las demás, como Ae. albopictus o Ae. aegypti, que están muy adaptadas a entornos urbanos. Ae. japonicus coloniza zonas boscosas y periurbanas con vegetación, y cría en oquedades de árboles, rocas y recipientes, también en zonas frías y de montaña. Culex pipiens, Cx. modestus y Cx. perexiguus no son especies invasoras sino autóctonas en Europa, y son vectores del virus del Nilo Occidental. Cx. pipiens, además, está muy ligado a los entornos urbanos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97747a") }, {"answer": 3, "long_answer": "El virus del Nilo Occidental se mantiene en la naturaleza en un ciclo enzoótico entre aves, que actúan como reservorio y hospedador amplificador, y mosquitos, principalmente del género Culex. La principal vía de transmisión entre ambos es la picadura: el mosquito se infecta al picar a un ave virémica y transmite el virus a otras aves en picaduras posteriores. Las personas y los caballos se infectan de forma accidental y son hospedadores finales. La transmisión transovárica en el mosquito existe, pero es minoritaria. El contacto directo y la inhalación no son vías relevantes en este ciclo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97747e") }, {"option_1": "Ausencia de humedales en el territorio", "long_answer": "La circulación del virus del Nilo Occidental en España se ve favorecida por la presencia de grandes poblaciones de aves migratorias, que actúan como reservorio y pueden introducir el virus desde África, en humedales como Doñana o las marismas del Guadalquivir, donde además abundan mosquitos Culex competentes. Precisamente la existencia de humedales extensos, y no su ausencia, es la que favorece el ciclo. Los gatos no actúan como reservorio relevante. El clima frío limita la actividad de los mosquitos, mientras que las temperaturas cálidas favorecen la transmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977482") }, {"option_2": "Virus Toscana", "long_answer": "El virus de la fiebre del valle del Rift, un flebovirus, se ha descrito en prácticamente la totalidad del continente africano, además de en Madagascar y en la península arábiga (Arabia Saudí y Yemen). Afecta principalmente al ganado rumiante y puede transmitirse a las personas, de ahí su interés en el Plan Nacional. El virus Usutu circula en África y en Europa, incluida España, sobre todo en aves. El virus Toscana es un flebovirus transmitido por flebotomos en la cuenca mediterránea. El virus Sindbis se distribuye por zonas de África, Europa del norte, Asia y Australia, sin estar descrito en todo el continente africano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977483") }, {"answer": 2, "long_answer": "La mayoría de las infecciones humanas por el virus de la fiebre del valle del Rift se producen por contacto directo o indirecto con sangre, tejidos o fluidos de animales infectados, sobre todo rumiantes, al sacrificarlos, manipular abortos o placentas o realizar tareas veterinarias. Por eso los ganaderos, veterinarios y matarifes son los grupos de mayor riesgo. La picadura de mosquitos infectados, Aedes y Culex, también puede transmitirla, pero es una vía menos frecuente en humanos y resulta fundamental para la transmisión entre animales. No se ha descrito transmisión vertical de persona a persona como vía principal, y la ingestión de carne cruda tampoco es la vía predominante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977484") }, {"option_2": "Promover la importación de rumiantes sin control veterinario", "option_3": "Suspender la vigilancia en las explotaciones ganaderas", "option_4": "Limitar la información dirigida al sector ganadero", "long_answer": "Uno de los objetivos del Plan Nacional frente a la fiebre del valle del Rift, enfermedad todavía no presente en España, es evitar la introducción de animales, mercancías o vectores infectados desde zonas afectadas, mediante controles veterinarios y sanitarios en frontera y en los movimientos de ganado, ya que el ganado rumiante actúa como amplificador. Las demás opciones son contrarias al Plan: importar rumiantes sin control veterinario facilitaría la entrada del virus, suspender la vigilancia en explotaciones impediría la detección precoz y limitar la información al sector ganadero dificultaría la prevención en el colectivo con mayor exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977489") }, {"option_4": "Sustituir las medidas de protección individual frente a las picaduras", "long_answer": "La finalidad de las medidas de gestión de vectores es evitar la proliferación de estos insectos para reducir su densidad, y con ello la incidencia de picaduras y de infecciones por arbovirus en la población, mediante el control de criaderos, el control larvario y, cuando es necesario, el control de adultos. La eliminación total de la población de vectores no es un objetivo realista. Aumentar la densidad del vector sería contrario a la salud pública. Estas medidas complementan la protección individual frente a picaduras, como los repelentes o las mosquiteras, pero no la sustituyen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97748c") }, {"long_answer": "La densidad de población larvaria es el parámetro entomológico que informa de la abundancia de la población de mosquitos en una zona, y se estima mediante muestreos de larvas en los criaderos o recuentos de huevos en trampas de oviposición. Esta información permite valorar el riesgo y orientar las medidas de control. La duración del ciclo gonotrófico indica cada cuánto tiempo pica y pone huevos una hembra. La interacción humano-mosquito se refiere a la frecuencia de contacto con las personas. La capacidad vectorial integra varios parámetros para estimar el potencial de transmisión, pero no mide directamente la abundancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97748e") }, {"long_answer": "Las trampas de oviposición, u ovitrampas, son el método de muestreo de referencia para seguir la presencia de aedinos como Ae. albopictus. Son recipientes oscuros con agua y un soporte en el que las hembras depositan los huevos, que luego se identifican y cuentan. Son baratas, sensibles y permiten detectar precozmente la llegada del mosquito y seguir su evolución estacional. Las trampas para adultos y el recuento de recipientes o el muestreo de larvas y pupas son complementarios, pero menos prácticos para la vigilancia sistemática. Los datos de la ciudadanía, como las notificaciones en aplicaciones, son útiles como apoyo, no como método de seguimiento principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977491") }, {"option_4": "Citriodiol (PMD)", "long_answer": "El DEET (N,N-dietil-m-toluamida) es el repelente de referencia y resulta eficaz frente a la mayoría de especies de insectos (mosquitos, flebotomos, moscas) y arácnidos (garrapatas) en concentraciones del 5% al 50%. Una mayor concentración prolonga la duración de la protección, pero no aumenta su eficacia. El IR3535 y la icaridina son repelentes eficaces con buen perfil de seguridad, aunque con un espectro o una duración algo menores según la concentración. El citriodiol (PMD), de origen vegetal, ofrece una protección más corta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977493") }, {"option_4": "Citriodiol (PMD)", "long_answer": "El DEET (N,N-dietil-m-toluamida) puede disolver plásticos, tejidos sintéticos, cuero o superficies barnizadas, por lo que debe evitarse su contacto con gafas, relojes o ropa sintética. A concentraciones superiores al 50% no aumenta su eficacia y se han descrito efectos adversos neurológicos, como insomnio y cambios del estado de ánimo, por lo que se recomienda no superar esa concentración. El IR3535, la icaridina y el citriodiol no presentan este efecto disolvente característico ni esa toxicidad descrita a concentraciones altas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977495") }, {"question": "¿Cuál es uno de los principales objetivos del reto mundial «Medicación sin daño» de la OMS?", "long_answer": "El tercer reto mundial por la seguridad del paciente de la OMS, «Medicación sin daño», lanzado en 2017, tiene como objetivo reducir en un 50% el daño grave y evitable relacionado con la medicación a nivel mundial en un plazo de cinco años. Para ello actúa sobre los pacientes, los profesionales, los medicamentos y los sistemas, y prioriza tres áreas: las situaciones de alto riesgo, la polimedicación y las transiciones asistenciales, ámbito en el que la conciliación de la medicación es clave. Las cifras del 25%, 75% y 100% no corresponden a la meta fijada por la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977498") }, {"long_answer": "Diversos estudios recogidos en los documentos de conciliación de la medicación muestran que hasta el 67% de los pacientes presenta al menos un error en la historia de medicación domiciliaria registrada al ingreso hospitalario, como omisiones, dosis o frecuencias incorrectas o fármacos que ya no toma. Esta elevada frecuencia justifica obtener sistemáticamente una historia farmacoterapéutica completa y contrastada en las transiciones asistenciales, y conciliarla con la prescripción hospitalaria. Las cifras del 15%, 25% y 50% infraestiman la magnitud del problema descrita en la literatura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97749c") }, {"long_answer": "El error de conciliación más frecuente es la omisión de un medicamento, es decir, que un fármaco que el paciente tomaba de forma crónica no se prescriba al ingreso, en el traslado o al alta sin que exista una justificación clínica. Supone aproximadamente la mitad de las discrepancias no justificadas. Le siguen las diferencias de dosis, vía o frecuencia y la prescripción incompleta. Los errores de administración se producen en otra fase del proceso. Los errores de prescripción en general constituyen una categoría amplia, y los errores de dosis existen, pero son menos frecuentes que la omisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a4") }, {"long_answer": "Los errores en la medicación domiciliaria registrada se han observado en hasta el 67% de los pacientes en el momento del ingreso hospitalario, cuando se elabora la historia farmacoterapéutica a partir de fuentes incompletas y con el paciente a menudo en situación aguda. Por eso el ingreso es un punto crítico para iniciar la conciliación. Aunque las transiciones asistenciales en general, incluida el alta, son momentos de riesgo, la cifra del 67% se refiere específicamente al ingreso. La consulta previa al alta y el propio momento del alta tienen sus propias tasas de discrepancias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a8") }, {"long_answer": "El riesgo de errores de conciliación aumenta con el número de medicamentos que toma el paciente y con el número de patologías crónicas que presenta: a mayor polimedicación y complejidad clínica, más probabilidad de omisiones, duplicidades o diferencias de dosis en las transiciones asistenciales. Por eso los pacientes crónicos, pluripatológicos y polimedicados son prioritarios en los programas de conciliación. Las demás opciones describen situaciones opuestas, como pocos medicamentos, ausencia de enfermedades crónicas o pacientes jóvenes, que se asocian a un menor riesgo de error."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ab") }, {"long_answer": "En 2005, la Joint Commission on Accreditation of Healthcare Organizations incluyó entre sus objetivos nacionales de seguridad del paciente el desarrollo de procedimientos para conciliar de forma precisa y completa la medicación a lo largo de la continuidad asistencial, lo que impulsó la implantación de la conciliación en los hospitales. Posteriormente organismos como la OMS, con las High 5s, y el Institute for Healthcare Improvement reforzaron esta práctica. Los años 2001, 2003 y 2007 no corresponden a esta recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b0") }, {"long_answer": "La experiencia en la implantación de la conciliación de la medicación pone de manifiesto que disponer de herramientas informáticas, como la historia clínica electrónica compartida, la receta electrónica o los módulos de conciliación integrados, es conveniente porque reduce los errores de conciliación: permite acceder a fuentes fiables de la medicación domiciliaria, detectar discrepancias y documentarlas de forma estructurada. La mejora de la comunicación, el acceso a la historia clínica o la agilización del alta son beneficios secundarios que, en último término, contribuyen a ese objetivo principal de seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b2") }, {"long_answer": "La historia completa de la medicación domiciliaria debe obtenerla un profesional sanitario siguiendo un procedimiento sistemático y normalizado, ya sea médico, farmacéutico o enfermera según la organización del centro. Este procedimiento consiste en contrastar varias fuentes (entrevista con el paciente o la persona cuidadora, historia de atención primaria, receta electrónica, informes previos) para obtener la lista más completa y exacta posible. El paciente y sus familiares son fuentes de información imprescindibles, pero no los responsables de elaborarla. Tampoco puede encargarse cualquier miembro del personal sin formación ni procedimiento definido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b3") }, {"long_answer": "En pacientes crónicos, el procedimiento recomendado para conciliar la medicación consiste en revisar las fuentes disponibles (historia clínica electrónica, receta electrónica, informes) y completar y verificar esa información mediante una entrevista estructurada con el paciente o su cuidador, preguntando qué toma realmente, cómo lo toma y si usa medicamentos sin receta, plantas medicinales o suplementos. Depender únicamente de la historia electrónica no detecta las discrepancias entre lo prescrito y lo que realmente se toma. No verificar la información o no entrevistar al paciente omite precisamente la fuente que permite detectar los errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b6") }, {"long_answer": "En pacientes crónicos se consideran medicamentos de alto riesgo aquellos cuyos errores pueden causar daños graves, como los anticoagulantes orales, los corticosteroides a largo plazo, las insulinas y los antidiabéticos orales, los opioides, el metotrexato oral o los antiinflamatorios no esteroideos, entre otros, según la lista MARC del ISMP-España. Requieren especial atención en la conciliación y en la educación al paciente. Los medicamentos de venta libre o sin receta no son, por definición, de alto riesgo, y la categoría genérica de medicamentos para enfermedades crónicas es demasiado amplia para considerarla de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774b8") }, {"long_answer": "Según el Plan Estratégico para la Prevención y Control de la Infección por el VIH y las ITS 2021-2030, la tasa de nuevos diagnósticos de VIH en España en 2019 fue de 7,46 por 100.000 habitantes, una vez corregido el retraso en la notificación. Esta cifra es similar a la media de Europa occidental, y la principal vía de transmisión son las relaciones sexuales entre hombres. Se observa una tendencia descendente, pero persiste un elevado porcentaje de diagnóstico tardío. Las tasas de 8,58, 5,0 y 10,0 por 100.000 no corresponden al dato de 2019 que recoge el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774bc") }, {"long_answer": "El Plan Estratégico para la Prevención y Control del VIH y las ITS 2021-2030 adopta como enfoque transversal que sitúa en el centro la dignidad de las personas con el VIH o con otras ITS el enfoque de derechos humanos, de género, de situación migratoria y de diversidad sexual. Este enfoque busca eliminar el estigma y la discriminación y garantizar la equidad en el acceso a la prevención, el diagnóstico y el tratamiento. Los determinantes sociales de la salud, la participación comunitaria con acciones basadas en la evidencia y el enfoque de salud pública son otros principios del Plan, pero no el que pone la dignidad en el centro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c4") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "El objetivo estratégico 4 del Plan Estratégico para la Prevención y Control del VIH y las ITS 2021-2030 se dirige a mejorar la calidad de vida de las personas con el VIH e incluye varias líneas complementarias: la monitorización e incorporación de la medición de la calidad de vida en la práctica clínica (4.1), la promoción de la salud psicosocial (4.2) y la eliminación de las barreras sociales y legales, reduciendo el estigma hacia las personas con el VIH y las que están en riesgo de adquirirlo (4.3). Por ello la respuesta correcta es la que engloba las tres líneas. Elegir una sola dejaría fuera componentes igualmente incluidos en el objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774cc") }, {"long_answer": "La línea 3.1 del Plan Estratégico para la Prevención y Control del VIH y las ITS 2021-2030 tiene como objetivo promover una asistencia sanitaria integral a las personas con el VIH. Esta asistencia abarca el tratamiento antirretroviral precoz, la atención a las comorbilidades y al envejecimiento, la salud sexual y reproductiva y la coordinación entre atención especializada, atención primaria y recursos comunitarios. El desarrollo de herramientas digitales, la eliminación de barreras sociales y legales y la promoción de la salud psicosocial forman parte de otras líneas del Plan, vinculadas sobre todo a la calidad de vida y al estigma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774cd") }, {"long_answer": "La OMS define la gobernanza en salud como la participación de los distintos actores (administraciones, profesionales, sociedad civil, personas afectadas y sector privado) en la definición e implementación de las políticas de salud, mediante mecanismos de rendición de cuentas, transparencia y coordinación. El Plan Estratégico para la Prevención y Control del VIH y las ITS adopta este concepto para su gestión. La coordinación entre entidades aseguradoras, el seguimiento y la evaluación anual del Plan y la colaboración con la Comisión Nacional de Coordinación son instrumentos o actuaciones concretas, no la definición de gobernanza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d1") }, {"long_answer": "El Comité de Seguimiento del Plan Estratégico para la Prevención y Control del VIH y las ITS tiene como función coordinar el seguimiento y la evaluación interna anual, revisando los indicadores y el grado de cumplimiento de las líneas de actuación para proponer ajustes. La evaluación intermedia es un hito puntual del Plan, no la función continuada del Comité. Eliminar el trato discriminatorio en el acceso a seguros es una línea de actuación frente al estigma, y la participación en grupos internacionales corresponde a la gobernanza y a la cooperación internacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d2") }, {"long_answer": "Uno de los principales objetivos del Plan Integral para la Prevención y Control del Tabaquismo 2024-2027 es reducir la prevalencia del consumo de tabaco y productos relacionados en la población, junto con retrasar la edad de inicio, proteger frente a la exposición al humo y a las emisiones, y fomentar el abandono. Para ello plantea medidas normativas, preventivas, asistenciales y de coordinación. Las demás opciones son contrarias al propósito del Plan, como aumentar la prevalencia o promover el consumo en jóvenes, o falsas, ya que el Plan sí establece objetivos concretos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d5") }, {"option_1": "En las terrazas al aire libre de la hostelería", "long_answer": "La Ley 28/2005, modificada por la Ley 42/2010, prohíbe fumar en los espacios al aire libre de los parques infantiles y áreas o zonas de juego para la infancia, además de en los recintos de centros educativos y sanitarios, entre otros. Su objetivo es proteger a la población, especialmente a menores, del humo ambiental de tabaco. Las terrazas al aire libre de la hostelería no están incluidas en la prohibición general de la ley, y ampliar los espacios sin humo a estas zonas es una de las propuestas del Plan Integral 2024-2027. Los hogares particulares no están regulados, y los centros de entretenimiento para adultos no figuran como supuesto específico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774dd") }, {"long_answer": "Para disponer de datos sobre tabaquismo en población adulta en distintos periodos, en España se alternan la Encuesta Nacional de Salud de España (ENSE) y la Encuesta Europea de Salud en España (EESE), que se realizan de forma intercalada y aportan información comparable sobre la prevalencia del consumo, la exposición al humo y otros hábitos. EDADES y ESTUDES son encuestas sobre consumo de drogas en población general y estudiantes, respectivamente, que se complementan entre sí, pero no son las que se alternan. HBSC estudia las conductas de salud en escolares. La combinación ESE y ESTUDES no corresponde a ninguna serie alternante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e6") }, {"option_1": "Unas 50.000", "option_2": "Unas 60.000", "option_3": "Unas 40.000", "option_4": "Unas 30.000", "long_answer": "Según el Ministerio de Sanidad, en el periodo 2010-2014 se produjeron en España una media de unas 50.000 muertes anuales atribuibles al consumo de tabaco, en torno a 52.000 al año, la mayoría en hombres y por cáncer de pulmón, enfermedad pulmonar obstructiva crónica y enfermedades cardiovasculares. El tabaquismo es la principal causa de muerte evitable, lo que justifica las medidas del Plan Integral para la Prevención y Control del Tabaquismo 2024-2027. Las cifras de 30.000, 40.000 y 60.000 muertes anuales no corresponden a la estimación para ese periodo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e9") }, {"long_answer": "El tabaquismo y la exposición al radón residencial tienen un efecto sinérgico sobre el riesgo de cáncer de pulmón: el radón es la segunda causa de cáncer de pulmón después del tabaco y la primera en no fumadores, y en las personas fumadoras expuestas a niveles elevados de radón el riesgo es mucho mayor que la suma de ambos factores por separado. Por eso el Plan considera relevante esta interacción, sobre todo en zonas con alta concentración de radón. La diabetes, las enfermedades cardíacas y las cerebrovasculares están relacionadas con el tabaco, pero no se describe una sinergia con el radón."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ef") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774f2") }, {"long_answer": "Según la Encuesta Europea de Salud en España 2020, la mayor prevalencia de consumo de tabaco se observa en los hombres de 45 a 54 años, y los hombres presentan en todos los grupos de edad cifras superiores a las de las mujeres. Este patrón refleja diferencias históricas de inicio y abandono del consumo entre sexos y generaciones. Los hombres de 25 a 34 años tienen también una prevalencia elevada, pero inferior a la del grupo de 45 a 54 años. En las mujeres, las prevalencias son menores en ambos tramos de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774f7") }, {"long_answer": "El Plan Integral para la Prevención y Control del Tabaquismo 2024-2027 define varios ejes de actuación, entre ellos el normativo, que incluye las modificaciones legislativas para ampliar los espacios sin humo, regular los nuevos productos relacionados con el tabaco, el empaquetado y los aromas, y reforzar la fiscalidad. Junto a él se sitúan ejes como la prevención, la asistencia o la coordinación. Los ejes cultural, deportivo y artístico no figuran como ejes de actuación del Plan, aunque algunas medidas puedan desarrollarse en esos ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774fa") }, {"long_answer": "Ampliar los espacios sin humo es importante para que la población pueda llevar a cabo su rutina diaria alejada de un ambiente afectado por el humo y las emisiones del tabaco, lo que reduce la exposición involuntaria, especialmente de menores, y contribuye a desnormalizar el consumo, facilitando que no se inicie y que quienes fuman lo dejen. Las demás opciones son contrarias al objetivo de los espacios sin humo: facilitar la exposición, desarrollar una rutina afectada por el humo o promover la adicción son justamente lo que esta medida pretende evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774fb") }, {"long_answer": "Eliminar los sabores y aromas que enmascaran el sabor propio del tabaco disminuye el atractivo del producto entre la población juvenil, ya que los aromas como el mentol, frutas o dulces suavizan la aspereza del humo, facilitan la iniciación y aumentan la percepción de menor riesgo. Por eso el Plan Integral 2024-2027 propone prohibirlos también en los productos relacionados con el tabaco. Añadir sabores tiene el efecto contrario. Eliminar los espacios sin humo y aumentar el atractivo del producto favorecerían el consumo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774fd") }, {"long_answer": "Uno de los riesgos añadidos del consumo de pipas de agua, shishas o cachimbas es que, al percibirse como una práctica social, ocasional y menos dañina, por los sabores y el paso del humo por el agua, puede servir como puerta de entrada a un consumo más regular de tabaco y nicotina, especialmente entre jóvenes. Además, en una sesión se inhalan grandes cantidades de monóxido de carbono, alquitrán y metales. Es incorrecto que no presente riesgos añadidos o que no necesite regulación, y presentarlo como un consumo ocasional minimiza su peligro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977500") }, {"long_answer": "El Plan Integral para la Prevención y Control del Tabaquismo destaca el papel de los profesionales de la educación y de la salud en el abordaje del tabaquismo en la población general. Los educadores intervienen en la prevención del inicio en niños, niñas y adolescentes y en la promoción de entornos escolares sin humo. Los profesionales sanitarios, como enfermeras, médicos o farmacéuticos, realizan el consejo breve, el diagnóstico y el tratamiento de la dependencia y son modelo para la población. Los profesionales de la moda, la construcción o la tecnología no tienen un papel específico en este abordaje."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977501") }, {"long_answer": "El Plan Integral para la Prevención y Control del Tabaquismo busca promover estándares homogéneos en la intervención en tabaquismo en todas las comunidades autónomas, mediante un protocolo común que unifique los programas de cesación. El objetivo es garantizar la equidad, de modo que cualquier persona reciba una atención de calidad similar con independencia de dónde viva. Los estándares heterogéneos o una intervención distinta en cada comunidad perpetuarían las desigualdades territoriales, y la ausencia de intervención es contraria a los objetivos del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977504") }, {"long_answer": "El artículo 8 del Convenio Marco de la OMS para el Control del Tabaco establece la protección contra la exposición al humo de tabaco, ya que reconoce que esta causa muerte, enfermedad y discapacidad. Obliga a las Partes a adoptar medidas eficaces para proteger a la población en los lugares de trabajo interiores, el transporte público, los lugares públicos cerrados y, según proceda, otros lugares públicos. Las demás opciones son falsas: el artículo sí establece medidas de protección, sí menciona expresamente la exposición al humo y en ningún caso la promueve."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977506") }, {"long_answer": "Según la OMS, uno de los impactos económicos del consumo de tabaco es la pérdida de capital humano, por la mortalidad prematura, la discapacidad y la menor productividad de las personas que enferman por su causa, a lo que se suman los elevados costes sanitarios. Además, la mayor parte de los fumadores del mundo vive en países de ingresos medianos o bajos, donde el tabaco agrava la pobreza. Por tanto, los costes sanitarios no son bajos, el porcentaje de fumadores en esos países no es bajo y el tabaco no tiene una influencia positiva en la economía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977507") }, {"long_answer": "El Plan Integral para la Prevención y Control del Tabaquismo menciona como repercusión negativa del consumo de tabaco sobre el medio ambiente la presencia y visibilidad de las colillas, que son uno de los residuos más abundantes en calles, playas y espacios naturales. Las colillas contienen plásticos y sustancias tóxicas que contaminan el suelo y el agua y afectan a los seres vivos. La reconversión del sector del tabaco no es una repercusión negativa sobre el medio ambiente. La normalización de conductas es un efecto social, no ambiental, y es falso que el tabaco no genere residuos ni impacto medioambiental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97750d") }, {"long_answer": "Una de las fuentes principales de conocimiento sobre el consumo de tabaco en la población son las encuestas y sondeos poblacionales, como la Encuesta Nacional de Salud (ENSE), la Encuesta Europea de Salud en España (EESE), EDADES y ESTUDES. Estas encuestas permiten estimar la prevalencia, las tendencias, la edad de inicio y las diferencias por sexo y nivel socioeconómico, y en ellas se basa la planificación de las políticas de control del tabaquismo. La televisión, las redes sociales y la publicidad no son fuentes válidas de datos epidemiológicos, y la publicidad del tabaco está además prohibida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97750e") }, {"long_answer": "La Directiva (UE) 2019/904, relativa a la reducción del impacto de determinados productos de plástico en el medio ambiente, establece regímenes de responsabilidad ampliada del productor: los productores de productos de plástico de un solo uso, entre ellos los filtros de los productos del tabaco, deben financiar los costes de recogida y limpieza de sus residuos y de las medidas de concienciación. Así se aplica el principio de «quien contamina paga». No recae en los consumidores, los gobiernos locales ni los minoristas, aunque estos colaboren en la gestión de los residuos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97750f") }, {"long_answer": "La iniciativa Playas sin Humo promueve espacios libres de humo en el litoral y aboga por una mayor concienciación sobre las consecuencias negativas del consumo de tabaco en la calidad del agua y en los seres vivos de mares y océanos. Las colillas desechadas en la arena liberan nicotina, metales pesados y microplásticos tóxicos para la fauna marina. Las iniciativas en parques, bosques o montañas se centran en otros entornos y no en la protección del medio marino, que es el ámbito al que se refiere la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977511") }, {"long_answer": "Entre los objetivos que el Plan Integral para la Prevención y Control del Tabaquismo 2024-2027 vincula a la reducción del porcentaje de jóvenes que se inician en el consumo de tabaco y productos relacionados figura reducir la exposición ambiental a las emisiones de tabaco en espacios públicos. Ver fumar con menos frecuencia desnormaliza el consumo y reduce la imitación por parte de los jóvenes. Garantizar la equidad en el acceso a los programas de cesación corresponde al eje de abandono. Promover el cumplimiento de la ley de espacios sin humo y reforzar la inspección se enmarcan en los objetivos normativos y de control del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977514") }, {"option_3": "Ampliar los espacios al aire libre libres de humo", "answer": 4, "long_answer": "Dentro del fomento del abandono del tabaquismo, una de las líneas de actuación del Plan Integral 2024-2027 es difundir material informativo de ayuda para dejar de fumar con perspectiva de género, que tenga en cuenta los motivos de inicio y mantenimiento del consumo y las barreras específicas para dejarlo de mujeres y hombres. Las campañas para desnormalizar el consumo pertenecen al eje de prevención. Regular la venta y el consumo de productos relacionados con el tabaco es una medida normativa. Ampliar los espacios sin humo corresponde a la protección frente a la exposición al humo ambiental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977517") }, {"option_3": "Ampliar los espacios sin humo a las terrazas de la hostelería", "long_answer": "Una de las líneas de actuación del Plan Integral 2024-2027 para fomentar el abandono del tabaquismo es habilitar los medios para facilitar la disponibilidad de los tratamientos farmacológicos de probada evidencia, como la vareniclina, el bupropión o la terapia sustitutiva con nicotina, ya que combinados con apoyo conductual duplican o triplican las tasas de abstinencia. Realizar cursos de formación para colectivos de interés y colaborar con programas de investigación son líneas transversales de formación e investigación. Ampliar los espacios sin humo a las terrazas es una medida de protección frente al humo ambiental, no de cesación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97751b") }, {"long_answer": "El objetivo 5.2 del Plan Integral para la Prevención y Control del Tabaquismo 2024-2027, dentro del eje de coordinación y participación, consiste en fomentar la participación social y del Tercer Sector, implicando a sociedades científicas, asociaciones de pacientes, ONG y otras entidades en el desarrollo y seguimiento de las medidas. La coordinación institucional, la coordinación con los Estados miembros de la UE y la coordinación internacional son otros objetivos del mismo eje, con números distintos dentro del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97751e") }, {"long_answer": "Los indicadores de proceso muestran el estado de cada actividad y su grado de avance, es decir, si las acciones previstas en el Plan se están ejecutando según lo planificado, como el número de campañas realizadas o de profesionales formados. Los indicadores de resultado miden el efecto conseguido sobre el problema, por ejemplo la prevalencia de consumo o la edad de inicio. Los indicadores generales y específicos no son tipos que describan el avance de cada actividad, sino denominaciones según su alcance."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97751f") }, {"long_answer": "En la ficha de evaluación de los indicadores del Plan Integral para la Prevención y Control del Tabaquismo, la herramienta de obtención o la fórmula de cálculo se establece mediante la relación entre dos o más variables, como un numerador y un denominador expresados en porcentaje o en tasa, lo que permite medir de forma objetiva y comparable el avance. Las demás opciones, como realizar actuaciones con el sector hostelero, participar en encuestas internacionales o coordinarse con la Conferencia de las Partes del Convenio Marco, son actividades del Plan, no fórmulas de cálculo de indicadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977522") }, {"long_answer": "Fortalecer los sistemas de vigilancia epidemiológica es una medida fundamental para eliminar el sarampión y la rubeola, porque permite detectar, investigar y confirmar por laboratorio cada caso sospechoso, identificar los brotes y la importación del virus y documentar la interrupción de la transmisión endémica, requisito para verificar la eliminación. Esta medida se acompaña de coberturas vacunales iguales o superiores al 95% con dos dosis de triple vírica. Mantener coberturas bajas, reducir la información sobre la vacunación o renunciar a verificar la eliminación son medidas contrarias al objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97752b") }, {"long_answer": "Según el plan para la eliminación del sarampión y la rubeola en España, entre 2014 y 2018 el 12,6% de los casos confirmados de sarampión había recibido al menos dos dosis de vacuna. Estos casos en vacunados reflejan fallos vacunales primarios o secundarios, como la disminución de la inmunidad con el tiempo, y aparecen en un contexto de alta cobertura. No cuestionan la efectividad de la vacuna, que ronda el 97% con dos dosis, pero justifican la vigilancia y el estudio de laboratorio de todos los casos. Los porcentajes del 8,9%, 15,2% y 20,5% no corresponden al dato del periodo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977531") }, {"long_answer": "La estrategia para mantener la eliminación del sarampión y la rubeola en España incluye varios objetivos complementarios: fortalecer la inmunidad de la población, con coberturas iguales o superiores al 95% con dos dosis de triple vírica y la captación de susceptibles; detectar y controlar con rapidez los casos aislados y los brotes mediante una vigilancia de alta calidad; y desarrollar estrategias de comunicación dirigidas a profesionales y población para mantener la confianza en la vacunación. Por eso la respuesta correcta es la que los engloba todos. Elegir uno solo dejaría fuera componentes igualmente necesarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977532") }, {"long_answer": "El Plan Estratégico para la eliminación del sarampión y la rubeola en España fija, dentro de la estrategia de fortalecer la inmunidad de la población, el objetivo específico de alcanzar y mantener coberturas de vacunación de al menos el 95% con dos dosis de triple vírica, porque ese umbral es el que garantiza la inmunidad de grupo frente a virus tan transmisibles como el del sarampión. Una cobertura del 90% es insuficiente para interrumpir la transmisión. La población inmunocomprometida grave no es diana de la triple vírica, al tratarse de una vacuna atenuada contraindicada en ella, y la vacunación de mayores de 60 años no es un objetivo de este plan, centrado en la población susceptible nacida tras la era prevacunal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977535") }, {"long_answer": "En farmacovigilancia, una señal es la información sobre una posible nueva asociación causal, o un aspecto nuevo de una asociación ya conocida, entre un medicamento o vacuna y un acontecimiento adverso, que se considera suficientemente probable como para justificar una verificación y evaluación posteriores. Su carácter es, por tanto, hipotético y novedoso. Una reacción adversa ya establecida no es una señal, sino un riesgo identificado; un aspecto ya conocido y documentado de una asociación tampoco aporta información nueva que deba validarse. Una contraindicación es una condición del paciente que impide el uso del fármaco, un concepto distinto que no tiene relación con la detección de nuevos riesgos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97753a") }, {"long_answer": "En el marco del plan de eliminación del sarampión y la rubeola, la Agencia Española de Medicamentos y Productos Sanitarios (AEMPS), como autoridad responsable de la farmacovigilancia de medicamentos de uso humano, incluidas las vacunas, es quien elabora anualmente un informe sobre las señales validadas relacionadas con las vacunas frente al sarampión y la rubeola. El Consejo Interterritorial del SNS es el órgano de coordinación entre el Ministerio y las comunidades autónomas y no evalúa señales de seguridad. El Centro Nacional de Epidemiología se ocupa de la vigilancia epidemiológica de los casos de la enfermedad, no de la seguridad de las vacunas, y el Consejo Nacional de Sanidad no tiene competencias en esta materia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977541") }, {"long_answer": "Según los protocolos de vigilancia, la confirmación por laboratorio de una infección por rubeola en la madre durante la gestación se notifica como un caso de rubeola confirmado por laboratorio, ya que se trata de una infección postnatal adquirida por la gestante y es además la situación que exige el seguimiento del recién nacido. Las infecciones del recién nacido se notifican en categorías propias: un recién nacido sin signos clínicos pero con criterios de laboratorio es una infección congénita por rubeola, y uno con signos clínicos y confirmación de laboratorio es un síndrome de rubeola congénita confirmado. Un resultado que descarta la infección, lógicamente, no genera la notificación de ningún caso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977542") }, {"long_answer": "El Consejo Interterritorial del Sistema Nacional de Salud, como órgano permanente de coordinación, cooperación y comunicación entre el Ministerio de Sanidad y las comunidades autónomas, es la institución a la que el plan atribuye la función de informar, capacitar, relacionar e involucrar a todos los actores implicados en la eliminación del sarampión y la rubeola, garantizando que las actuaciones sean homogéneas en todo el territorio. Las comunidades autónomas ejecutan la vigilancia y la vacunación en su ámbito territorial, pero no coordinan al conjunto de actores del Estado. Las demás unidades citadas tienen funciones técnicas o administrativas concretas dentro del Ministerio, sin ese papel integrador de todos los agentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977547") }, {"long_answer": "La Oficina Regional para Europa de la OMS señala que, en la etapa de eliminación, cuando los casos son muy escasos, lo relevante de la vigilancia es conocer su sensibilidad, es decir, su capacidad para detectar cualquier caso sospechoso que aparezca. Por eso se usan indicadores de calidad como la tasa de casos sospechosos estudiados y descartados. Conocer la incidencia tiene poco valor si el sistema no es sensible, porque una incidencia baja podría reflejar infradetección. La evaluación de la inmunidad de la población se realiza mediante coberturas y estudios de seroprevalencia, no es el objetivo propio de la vigilancia de casos, y el mantenimiento de la eliminación es el fin global, no un atributo del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977548") }, {"option_1": "Incidencia: objetivo de <10 casos de sarampión o de rubeola por millón de habitantes.", "option_2": "Tamaño y origen de los brotes: se consideran aceptables brotes de mayor tamaño y duración.", "option_3": "Inmunidad de la población: coberturas de vacunación mantenidas iguales o superiores al 80% con una dosis.", "long_answer": "Entre los indicadores para monitorizar el mantenimiento de la eliminación figura el origen de los casos y los genotipos: cada caso se clasifica según su método de confirmación (laboratorio, vínculo epidemiológico o clínico) y según el origen de la infección (importado, relacionado con importación o autóctono), lo que, junto con la genotipación, permite demostrar la ausencia de transmisión endémica. Los demás enunciados son incorrectos: el objetivo de incidencia es inferior a 1 caso por millón de habitantes, no a 10; los brotes deben ser cada vez de menor tamaño y duración; y la cobertura exigida es igual o superior al 95% con dos dosis de triple vírica, no del 80% con una dosis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977549") }, {"option_2": "Persona recientemente vacunada en la que solo se detecta el genotipo vacunal del virus.", "long_answer": "Según los protocolos de vigilancia, un caso confirmado por laboratorio de sarampión o rubeola es una persona no vacunada recientemente que satisface los criterios clínicos y los de laboratorio. En una persona vacunada en las semanas previas, solo se confirma el caso si se detecta un genotipo salvaje; si únicamente aparece el genotipo vacunal, se trata de una reacción a la vacuna y no de un caso. La definición de menor de un año con afecciones de la lista A y criterios de laboratorio corresponde al síndrome de rubeola congénita, y la última opción describe un caso endémico, que es una clasificación según el origen de la infección, no según el método de confirmación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97754d") }, {"long_answer": "Los anticuerpos totales o de clase IgG frente al sarampión o la rubeola persisten durante años tras la infección o la vacunación, por lo que su detección aislada solo indica una infección pasada en un momento indeterminado o inmunidad previa, sin permitir fecharla. Para diagnosticar una infección reciente se requiere la detección de IgM específica, la seroconversión o un aumento significativo del título de IgG entre dos muestras pareadas, o la detección del virus. La infección congénita por rubeola se confirma con IgM en el recién nacido o persistencia de IgG más allá de lo esperable por transferencia materna, y la infección primaria se caracteriza por IgM y baja avidez de IgG."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97747c") }, {"long_answer": "Según el plan de vigilancia y control de las enfermedades transmitidas por vectores, la mayoría de las infecciones por el virus del Nilo Occidental son asintomáticas o cursan como un cuadro febril leve, pero en menos del 1% aparece afectación neurológica (meningitis, encefalitis o parálisis flácida aguda). En estos casos neuroinvasivos la letalidad es apreciable y el riesgo de secuelas neurológicas, cognitivas o motoras persistentes es elevado, del orden del 50-70%. Las cifras de 10-20% y 20-30% infravaloran claramente este riesgo y la de 80-90% lo sobrestima. Por ello estos pacientes requieren seguimiento y rehabilitación tras la fase aguda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97747d") }, {"long_answer": "El diagnóstico de laboratorio de la infección por el virus del Nilo Occidental se basa en la detección del genoma viral mediante RT-PCR en sangre, orina o líquido cefalorraquídeo, junto con la serología (IgM específica en suero o LCR, seroconversión y confirmación mediante neutralización por las reacciones cruzadas con otros flavivirus). Entre las opciones, la única que describe una técnica específica es la RT-PCR. Un análisis de sangre genérico no es un método diagnóstico en sí mismo, y la radiografía de tórax o la ecografía abdominal son pruebas de imagen que no permiten identificar el virus ni tienen papel en el diagnóstico de esta infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977480") }, {"long_answer": "La gestión integrada de vectores, tal como la recoge el plan nacional, se apoya en conocer la distribución de las especies vectoriales presentes, conocer el riesgo de transmisión de las enfermedades que pueden vehicular y, a partir de ello, planificar las medidas de control más adecuadas, combinando métodos y priorizando los menos dañinos para el entorno. La coordinación, la comunicación y la educación son herramientas transversales del plan, pero no los componentes de la gestión del vector. La gestión de residuos, la salud laboral o la sanidad ambiental son ámbitos relacionados, y el control de poblaciones o de plagas es solo una parte de la intervención, no su estructura completa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977481") }, {"option_1": "Flavivirus", "long_answer": "El virus Usutu pertenece al género Flavivirus, dentro de la familia Flaviviridae, el mismo género que el virus del Nilo Occidental, el del dengue o el de la fiebre amarilla, con el que comparte el ciclo enzoótico entre aves y mosquitos del género Culex. Esta proximidad explica las reacciones cruzadas en las pruebas serológicas. Bunyaviridae es una familia distinta, Phlebovirus es el género al que pertenece, por ejemplo, el virus de la fiebre del valle del Rift o el Toscana, y Alphavirus es el género de virus como el chikungunya, transmitidos por Aedes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977485") }, {"long_answer": "El plan nacional considera que, para España, la vía de introducción del virus de la fiebre del valle del Rift que supone mayor riesgo para la salud humana es la llegada de un viajero en periodo virémico procedente de una zona afectada, que pudiera infectar a mosquitos locales competentes e iniciar transmisión autóctona. La llegada de mosquitos infectados arrastrados por el viento desde el norte de África se considera poco probable, el transporte ilegal de animales vivos está muy restringido y controlado, y la importación de carne de ungulados procedentes de terceros países está prohibida desde zonas afectadas, por lo que estas vías suponen un riesgo menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97748f") }, {"long_answer": "El tipo de hábitat larvario es el parámetro que informa sobre la capacidad de una zona para albergar poblaciones larvarias de mosquitos, porque describe la disponibilidad y las características de las masas de agua (naturales o artificiales, permanentes o temporales, limpias o con materia orgánica) donde se desarrollan las larvas de cada especie. La densidad de población larvaria mide cuántas larvas hay en un momento dado, no la capacidad del entorno. La duración del ciclo gonotrófico se refiere al intervalo entre ingesta de sangre y puesta en la hembra adulta, y la interacción humano-mosquito se relaciona con el riesgo de picadura y transmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977490") }, {"option_1": "Mantener recipientes abiertos con agua de lluvia en patios y terrazas", "option_3": "Dejar agua acumulada de forma permanente en los platos bajo las macetas", "option_4": "Aplicar insecticidas de forma rutinaria y generalizada en todo el municipio", "long_answer": "La medida general más eficaz para evitar la proliferación de mosquitos es vaciar y limpiar, en la medida de lo posible, todos los objetos y contenedores donde pueda acumularse agua, ya que así se eliminan los criaderos en los que se desarrollan las larvas. Mantener recipientes abiertos con agua de lluvia o dejar agua estancada en los platos de las macetas favorece justamente la cría de especies como Aedes albopictus. La aplicación rutinaria e indiscriminada de insecticidas no es una medida general de prevención: la gestión integrada reserva los biocidas para situaciones justificadas, por su impacto ambiental y el riesgo de resistencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977494") }, {"option_4": "Citriodiol (PMD)", "long_answer": "El IR3535 (etil butilacetilaminopropionato) es un repelente con una estructura química similar al aminoácido beta-alanina, activo frente a mosquitos, garrapatas y moscas que pican, y con buen perfil de seguridad, por lo que se utiliza también en niños y embarazadas. El DEET (N,N-dietil-m-toluamida) es el repelente de referencia, pero es una amida sin relación estructural con la alanina. La icaridina (picaridina) es un derivado de la piperidina, relacionado con la pimienta. El citriodiol o PMD es un derivado del aceite de eucalipto limonero, de origen vegetal, y tampoco guarda semejanza con un aminoácido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977496") }, {"long_answer": "En su tercer reto mundial por la seguridad del paciente, Medicación sin daño, la OMS invitó a los países a establecer actuaciones de mejora en tres áreas prioritarias: las transiciones asistenciales, la polimedicación inapropiada y las situaciones de alto riesgo, porque es en ellas donde se concentran los errores de medicación con daño evitable. Las enfermedades crónicas no constituyen una de estas tres áreas, aunque guarden relación con la polimedicación. Por ello, todas las demás combinaciones son incorrectas, ya que incluyen las enfermedades crónicas o dejan fuera alguna de las tres áreas definidas por la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97749a") }, {"long_answer": "Las recomendaciones sobre prácticas de conciliación de la medicación se incluyen en la Estrategia de Seguridad del Paciente del Sistema Nacional de Salud, dentro de la línea dedicada a las prácticas clínicas seguras, en el objetivo de promover el uso seguro de los medicamentos, ya que los errores de conciliación en las transiciones asistenciales son una causa frecuente de eventos adversos. La Estrategia para el Abordaje de la Cronicidad trata la atención integral al paciente crónico y menciona la revisión de la medicación, pero no es el marco de estas recomendaciones. El Plan Nacional de Salud y la estrategia de prevención citados no recogen estas prácticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97749d") }, {"long_answer": "El objetivo principal de la conciliación de la medicación es garantizar una prescripción segura en las transiciones asistenciales (ingreso, traslado entre unidades o niveles y alta), asegurando que el paciente recibe todos los medicamentos que necesitaba previamente, a la dosis, vía y frecuencia correctas, y que cualquier discrepancia está justificada y documentada. Con ello se evitan omisiones, duplicidades e interacciones. Evitar errores de diagnóstico no es su finalidad. La mejora de la adherencia y la reducción de costes pueden ser beneficios secundarios, pero no constituyen el objetivo del proceso, centrado en la seguridad del tratamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97749f") }, {"long_answer": "La definición de conciliación de la medicación, inicialmente centrada en el ingreso y el alta hospitalaria, amplió su alcance en los últimos años debido a la extensión del proceso a la atención primaria y a los servicios de urgencias, entendiendo que cualquier transición asistencial es un punto de riesgo para la aparición de discrepancias. La inclusión de medicamentos sin receta forma parte de una buena anamnesis farmacoterapéutica, pero no motivó la ampliación del concepto. La disminución de errores en hospitales es un resultado buscado, no la causa del cambio, y la prescripción de medicamentos controlados no guarda relación con este proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a3") }, {"long_answer": "La OMS, en su reto mundial Medicación sin daño, estableció como áreas prioritarias para mejorar la seguridad en el uso de los medicamentos las transiciones asistenciales, la polimedicación inapropiada y las situaciones de alto riesgo, por ser los contextos en los que se producen más errores con daño evitable. La división en atención primaria, secundaria y terciaria corresponde a niveles asistenciales, no a áreas de riesgo. Cuidados críticos, intensivos y paliativos son ámbitos clínicos concretos, y la agrupación por edad (mayores, pediátricos, adolescentes) define poblaciones vulnerables, pero ninguna de estas clasificaciones es la propuesta por la OMS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a5") }, {"long_answer": "La conciliación de la medicación se define como un proceso formal, estructurado y multidisciplinar que mejora la comunicación entre profesionales y con el paciente: consiste en obtener una lista completa y exacta de la medicación previa y compararla con la prescrita en cada transición asistencial, analizando y resolviendo las discrepancias. Aunque reduce errores, no es un simple programa de reducción de errores de prescripción, ya que abarca la comunicación y la continuidad del tratamiento. Tampoco es un sistema de registro de la historia clínica ni un protocolo exclusivo de los servicios de urgencias, puesto que se aplica en todas las transiciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774a6") }, {"long_answer": "En la Estrategia de Seguridad del Paciente del SNS 2015-2020, las recomendaciones sobre conciliación de la medicación se incluyen en la línea estratégica 2, Prácticas clínicas seguras, concretamente en el objetivo de promover el uso seguro de los medicamentos, junto con la gestión de medicamentos de alto riesgo y la prevención de errores. La línea 1 se dedica a la cultura de seguridad, los factores humanos, la organización y la formación. La línea 3 trata la gestión del riesgo y los sistemas de notificación y aprendizaje, y la línea 4 la participación de pacientes y ciudadanos en su seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774aa") }, {"long_answer": "En Canadá, el Institute for Safe Medication Practices-Canada (ISMP Canada) y el Canadian Patient Safety Institute (CPSI) desarrollaron programas, directrices y herramientas para promover la conciliación de la medicación, en particular dentro de la campaña Safer Healthcare Now!. El Institute for Healthcare Improvement y la Agency for Healthcare Research and Quality son organismos estadounidenses, igual que la Massachusetts Coalition for the Prevention of Medical Errors y la Joint Commission, que también impulsaron la conciliación, pero en Estados Unidos. La OMS y la OPS son organismos internacionales, no canadienses, aunque la OMS promovió la conciliación dentro del proyecto High 5s."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ad") }, {"long_answer": "Los estudios recogidos en el documento sobre conciliación de la medicación muestran que la proporción de pacientes con al menos un error de conciliación al ingreso hospitalario es muy variable según el ámbito y la metodología, llegando hasta el 86,8% de los pacientes en algunas series. Esta elevada frecuencia justifica la necesidad de implantar procedimientos sistemáticos de conciliación en las transiciones asistenciales. Las cifras del 20%, 50% o 75% quedan por debajo del máximo descrito en los estudios, por lo que no reflejan el límite superior de la magnitud del problema que se cita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774bd") }, {"long_answer": "El Plan Estratégico para la Prevención y Control de la infección por el VIH y las ITS propone acciones de participación comunitaria para promover la educación, la formación, el conocimiento, el empoderamiento y la participación de las personas con VIH y otras ITS, reconociendo el papel de las organizaciones comunitarias y de los propios afectados en el diseño y la ejecución de las intervenciones. Las acciones basadas en la evidencia y la innovación, las de coordinación y complementariedad entre administraciones, y las de reducción de inequidades son principios rectores del plan, pero no las que se dirigen específicamente al empoderamiento de las personas afectadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c1") }, {"long_answer": "Entre las acciones para la implementación de la profilaxis preexposición (PrEP), el plan recoge trabajar en la ampliación de los criterios de indicación para dar cobertura a adolescentes, mujeres y hombres cis y personas que se inyectan drogas con riesgo alto de infección por el VIH, ya que inicialmente la prestación se centró en hombres que tienen sexo con hombres y mujeres trans. La promoción de la vacunación frente a ITS y del uso del preservativo y lubricante son acciones de prevención combinada, pero no específicas de la PrEP. El conocimiento de infraestructuras de atención forma parte de otro ámbito del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c2") }, {"option_4": "Promoción de la vacunación frente a la hepatitis A y B en grupos de riesgo", "long_answer": "Para promover el diagnóstico precoz del VIH y otras ITS, el plan incluye la promoción de la oferta de la prueba del VIH en entornos comunitarios, que facilita el acceso a poblaciones que no acuden a los servicios sanitarios convencionales y reduce el diagnóstico tardío. Incrementar el conocimiento de las infraestructuras de atención es una acción de información general. La vinculación del diagnóstico con el inicio del tratamiento antirretroviral corresponde a la continuidad asistencial, una vez establecido el diagnóstico, y la vacunación frente a las hepatitis A y B es una medida de prevención primaria, no de diagnóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774c5") }, {"long_answer": "El objetivo estratégico 3 del plan frente al VIH y las ITS se centra en promover la asistencia temprana y el manejo de la cronicidad de la infección por el VIH, es decir, la vinculación rápida a la atención y al tratamiento antirretroviral, la retención en el sistema y la atención integral a las personas que viven con VIH, incluida su calidad de vida. La prevención de riesgos de adquisición del VIH corresponde a un objetivo previo centrado en la prevención. La innovación en el tratamiento de las ITS y la vigilancia epidemiológica son ámbitos transversales del plan, pero no definen este objetivo estratégico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774d4") }, {"long_answer": "El Plan Integral de Prevención y Control del Tabaquismo 2024-2027 aborda, entre sus temas fundamentales, el comercio ilícito de productos de tabaco, ya que el contrabando y la falsificación abaratan el producto, facilitan el acceso a menores y eluden las medidas fiscales y de etiquetado, debilitando las políticas de control. El cultivo del tabaco no es un eje del plan, y la promoción del consumo es justamente lo contrario de lo que persigue, que es reducir la prevalencia y la exposición. El control del medio ambiente en sentido genérico tampoco es un tema propio, aunque el plan sí considera el impacto medioambiental del tabaco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774da") }, {"long_answer": "El Convenio Marco de la OMS para el Control del Tabaco, primer tratado internacional de salud pública, tiene como propósito proteger a las generaciones presentes y futuras de las devastadoras consecuencias sanitarias, sociales, ambientales y económicas del consumo de tabaco y de la exposición al humo, reduciendo de manera continua y sustancial su consumo. Aunque recomienda subir los impuestos, su finalidad no es recaudar sino disminuir el consumo. La protección del medio ambiente aparece como una de las consecuencias a evitar, no como su objetivo principal, y el tratado busca restringir, nunca promover, el comercio de tabaco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774dc") }, {"answer": 3, "long_answer": "La Encuesta Nacional de Salud de España (ENSE), elaborada por el Ministerio de Sanidad y el Instituto Nacional de Estadística, es una investigación de periodicidad quinquenal, es decir, se realiza aproximadamente cada 5 años. En los periodos intermedios se lleva a cabo la Encuesta Europea de Salud en España, de forma que ambas encuestas alternadas proporcionan información sobre el consumo de tabaco y otros determinantes de salud cada 2 o 3 años, pero esa cifra no corresponde a la periodicidad de la ENSE por sí sola. No es una encuesta anual, y la periodicidad de 10 años sería demasiado amplia para monitorizar las políticas sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774df") }, {"long_answer": "En España, el producto de tabaco preferentemente consumido sigue siendo el cigarrillo manufacturado, que es la forma de consumo mayoritaria entre las personas fumadoras según las encuestas nacionales recogidas en el plan. El tabaco de liar ha aumentado su peso en los últimos años, sobre todo entre jóvenes y personas con menos recursos por su menor precio, pero sigue siendo minoritario frente al cigarrillo. Los puritos y la pipa tienen un consumo residual. Esta preferencia orienta muchas de las medidas regulatorias, como el empaquetado y la fiscalidad, hacia el cigarrillo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774e0") }, {"long_answer": "El indicador que muestra en España una tendencia a la disminución gradual es la prevalencia del consumo de tabaco, es decir, el porcentaje de población que fuma, que ha descendido de forma lenta pero sostenida en las últimas décadas, aunque sigue siendo elevada. La edad de inicio se ha mantenido bastante estable en torno a la adolescencia, sin una tendencia clara a retrasarse. Las preferencias por los productos consumidos han cambiado hacia el tabaco de liar y los nuevos productos, lo que no refleja una disminución. La exposición al humo ambiental se redujo tras las leyes de espacios sin humo, pero no es el indicador de prevalencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ed") }, {"long_answer": "El plan recoge que el estrés es un factor que promueve especialmente el inicio y el mantenimiento del consumo de tabaco, ya que la nicotina se utiliza como un mecanismo de afrontamiento ante situaciones de tensión, sobrecarga o malestar emocional, y esta percepción de alivio refuerza la conducta. La depresión se asocia a mayor consumo y a más dificultad para dejarlo, pero no se señala como el principal desencadenante del inicio. La falta de ejercicio y la mala alimentación son otros factores de riesgo de estilo de vida que pueden coexistir con el tabaquismo, sin ser causas de su inicio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9774ee") }, {"long_answer": "Según el plan, las mujeres utilizan la nicotina con mayor frecuencia para mejorar su estado de ánimo y regular las emociones negativas, como la ansiedad, el estrés o la tristeza, lo que tiene implicaciones para la deshabituación, ya que requiere abordar estrategias alternativas de manejo emocional. Mejorar la concentración y aumentar la energía son efectos atribuidos a la nicotina en general, pero no se describen como un motivo diferencial de las mujeres. Aliviar el insomnio no es un efecto de la nicotina, que por su acción estimulante tiende a empeorar el sueño."});
print(`\nParte terminada: ${ok} corregidas, ${del} borradas, ${warn} avisos.`);
